insert into content_items (deck_key, order_index, data) values
('law_6513', 0, '{"t": "tit", "x": "LEI Nº 6.513, DE 30 DE NOVEMBRO DE 1995 — Estatuto dos Policiais-Militares da Polícia Militar do Maranhão"}'::jsonb),
('law_6513', 1, '{"t": "art", "n": "Preâmbulo", "x": "Dispõe sobre o Estatuto dos Policiais-Militares da Polícia Militar do Maranhão e dá outras providências. A GOVERNADORA DO ESTADO DO MARANHÃO faz saber que a Assembleia Legislativa do Estado decretou e sanciona a seguinte Lei.", "s": "É a “capa” da lei: a Governadora do Maranhão sanciona o Estatuto que vai reger todos os PMs do estado."}'::jsonb),
('law_6513', 2, '{"t": "tit", "x": "TÍTULO I — GENERALIDADES"}'::jsonb),
('law_6513', 3, '{"t": "art", "n": "Art. 1º", "x": "Esta Lei regula a situação, obrigações, direitos, deveres e prerrogativas dos policiais-militares da Polícia Militar do Maranhão.", "s": "O “manual de regras” do PM/MA: define situação, obrigações, direitos, deveres e prerrogativas — decore essas 5 palavras, caem literalmente em prova."}'::jsonb),
('law_6513', 4, '{"t": "art", "n": "Art. 2º", "x": "Os integrantes da Polícia Militar constituem a categoria de Servidores Públicos Militares do Estado.\n§1º São equivalentes as expressões “servidor público militar estadual”, “servidor público militar”, “militar”, “policial militar” e “servidor militar do estado” para fins deste Estatuto.\n§2º Os servidores públicos militares encontram-se em uma das seguintes situações:\nI- na ativa: a) os militares de carreira; b) os incluídos na Polícia Militar, voluntariamente durante o tempo que se comprometeram a servir; c) os componentes da reserva remunerada, quando convocados; d) os alunos dos cursos de formação de policiais-militares.\nII- na inatividade: a) os militares na reserva remunerada sujeitos à convocação; b) reformados, por terem sido dispensados definitivamente da prestação de serviço na ativa, continuando a perceber remuneração do Estado.\n§3º Militares de carreira são os que, no desempenho voluntário e permanente do serviço policial-militar, têm estabilidade assegurada ou presumida.", "s": "PM é “Servidor Público Militar”. Ele está em uma de duas “gavetas”: ATIVA (trabalhando: carreira, voluntário, reserva convocada, aluno) ou INATIVIDADE (reserva remunerada ou reformado)."}'::jsonb),
('law_6513', 5, '{"t": "art", "n": "Art. 3º", "x": "O serviço policial-militar consiste no exercício de atividades inerentes à Polícia Militar e compreende todos os encargos previstos na legislação específica e peculiar relacionados com o policiamento ostensivo e a preservação da ordem pública.", "s": "Serviço policial-militar = tudo que gira em torno de policiamento ostensivo + preservação da ordem pública."}'::jsonb),
('law_6513', 6, '{"t": "art", "n": "Art. 4º", "x": "A carreira policial-militar é caracterizada por atividade contínua devotada às finalidades da Polícia Militar.\n§1º A carreira policial-militar é privativa dos militares da ativa, inicia-se com o ingresso na Polícia Militar e obedece à sequência de graus hierárquicos.\n§2º É privativa de brasileiros natos a carreira de Oficial da Polícia Militar.", "s": "Carreira = só quem está na ativa. E decore o pegador clássico: carreira de OFICIAL é privativa de brasileiro NATO (naturalizado não pode ser oficial)."}'::jsonb),
('law_6513', 7, '{"t": "art", "n": "Art. 5º", "x": "São equivalentes as expressões “Polícia Militar do Estado do Maranhão”, “Polícia Militar do Estado”, “Polícia Militar Estadual”, “Polícia Militar do Maranhão”, “Instituição Policial Militar”, “Instituição Militar Estadual” e “Organização Policial-Militar”, para efeito deste Estatuto.", "s": "Vários apelidos, uma instituição só: PMMA = PM do Estado = Instituição Policial Militar = Organização Policial-Militar. Tudo sinônimo."}'::jsonb),
('law_6513', 8, '{"t": "art", "n": "Art. 6º", "x": "São equivalentes as expressões “na ativa”, “da ativa”, “em serviço ativo”, “em serviço na ativa”, “em atividade” ou “em atividade policial militar”, conferidas aos policiais militares no desempenho de cargo, comissão, encargo, incumbência ou missão, serviço ou atividade policial-militar, nas Organizações Policiais Militares ou em outros órgãos do Estado, quando previsto em lei ou regulamento.", "s": "Mesma lógica do artigo anterior, mas agora pra “estar na ativa”: “na ativa”, “em serviço”, “em atividade” — tudo a mesma coisa."}'::jsonb),
('law_6513', 9, '{"t": "art", "n": "Art. 7º", "x": "A condição jurídica dos servidores públicos militares é definida pelos dispositivos constitucionais que lhes forem aplicáveis, pela legislação específica, por este Estatuto e pelas leis peculiares que lhes outorguem direitos e prerrogativas e lhes imponham deveres e obrigações.", "s": "A “identidade jurídica” do militar vem de 4 fontes: Constituição + legislação específica + este Estatuto + leis peculiares."}'::jsonb),
('law_6513', 10, '{"t": "cap", "x": "CAPÍTULO I — DO INGRESSO NA POLÍCIA MILITAR"}'::jsonb),
('law_6513', 11, '{"t": "art", "n": "Art. 8º", "x": "O ingresso na Polícia Militar do Maranhão é facultado a todos os brasileiros, sem distinção de raça ou crença religiosa, mediante matrícula ou nomeação, após aprovação em concurso público de provas e/ou de provas e títulos.", "s": "Pra ENTRAR na PM basta ser brasileiro (nato ou naturalizado) e passar em concurso — a exigência de nato é só pra carreira de Oficial (art. 4º), não pra ingressar."}'::jsonb),
('law_6513', 12, '{"t": "art", "n": "Art. 9º", "x": "Para a matrícula no estabelecimento de ensino militar destinado à formação de Oficiais, Sargentos e Soldados PM, QOPM e QOPM Fem, é necessário que o candidato satisfaça as seguintes condições:\nI- ser brasileiro;\nIII- estar em dia com as obrigações militares e eleitorais;\nIV- possuir, até a data limite da inscrição, a idade máxima de 30 (trinta) anos;\nV- ter idoneidade moral;\nVI- ter sanidade física e mental;\nVII- ter no mínimo 1,65 m de altura, se masculino, e 1,60 m de altura se do sexo feminino;\nVIII- ser aprovado em concurso público mediante os seguintes critérios: a) para oficiais PM, será exigido o certificado do 2º Grau e aprovação inclusive nos exames físico, médico e psicotécnico; b) para praças PM, o candidato deverá possuir certificado de conclusão de 2º Grau e ser aprovado inclusive nos exames físico, médico e psicotécnico;\nIX- ser habilitado para a direção de veículos automotor, no mínimo, na categoria “A” ou “B”.\nParágrafo único - É obrigatória a realização do exame toxicológico para os candidatos aos cursos de formação da Polícia Militar do Maranhão, possuindo o mesmo caráter eliminatório.\n(Nota: o inciso II — exigência de ser solteiro — foi revogado.)", "s": "Checklist de matrícula: brasileiro, em dia com Justiça Militar/Eleitoral, até 30 anos, idoneidade moral, sanidade física/mental, altura mínima (1,65 m / 1,60 m), 2º grau + exames, CNH “A” ou “B”, exame toxicológico eliminatório. PEGADINHA clássica: o inciso II (“ser solteiro”) foi REVOGADO — hoje casado pode!"}'::jsonb),
('law_6513', 13, '{"t": "art", "n": "Art. 10", "x": "O ingresso no Quadro de Oficiais, no posto inicial da carreira, será através do Curso de Formação de Oficiais da Polícia Militar, no qual serão matriculados os candidatos aprovados em concurso público.", "s": "Quer ser Oficial? A porta de entrada é sempre o CFO (Curso de Formação de Oficiais), via concurso."}'::jsonb),
('law_6513', 14, '{"t": "art", "n": "Art. 11", "x": "Para ingresso no Quadro de Oficiais de Administração (QOA) e de Oficiais Especialistas (QOE), serão selecionados os Subtenentes, mediante os seguintes critérios: I- possuir diploma de conclusão de Curso de Nível Superior ou equivalente, reconhecido pelo MEC; II- possuir, no mínimo, 18 anos de efetivo serviço; III- contar com, no mínimo, 02 anos na graduação; IV- ser aprovado no Curso de Habilitação de Oficiais de Administração (CHOA) ou de Oficiais Especialistas (CHOE), respectivamente.\n§1º Requisitos básicos para matrícula no CHOA/CHOE: estar em pleno desempenho das atividades profissionais; ser considerado apto em exame de saúde; ser aprovado em exame de aptidão física; possuir conceito profissional e conceito moral; não estar denunciado em processo-crime ou condenado em sentença transitada em julgado; não estar submetido a Conselho de Disciplina.\n§2º Dentre os habilitados, serão indicados os Subtenentes mais antigos na graduação, conforme o número de vagas.", "s": "QOA/QOE é a “segunda porta” pra virar Oficial — mas só pra Subtenente: precisa de diploma superior, 18 anos de serviço, 2 anos na graduação e ser aprovado no CHOA/CHOE."}'::jsonb),
('law_6513', 15, '{"t": "art", "n": "Art. 13", "x": "O ingresso no Quadro de Oficiais de Saúde (QOS) será mediante concurso público de provas e/ou de provas e títulos e aprovação inclusive nos exames médico, físico e psicotécnico.\n§1º O candidato deverá possuir, até a data limite da inscrição, a idade de 35 (trinta e cinco) anos.\n§2º Os aprovados serão submetidos a estágio não inferior a 90 (noventa) dias, findo o qual serão nomeados no posto de 1º Tenente PM Médico, 1º Tenente PM Dentista, 1º Tenente PM Veterinário e 1º Tenente PM Psicólogo, obedecida a rigorosa ordem de classificação no estágio.", "s": "Oficial de Saúde (médico/dentista/veterinário/psicólogo): concurso próprio, idade-limite 35 anos, estágio mínimo de 90 dias, entra como 1º Tenente."}'::jsonb),
('law_6513', 16, '{"t": "art", "n": "Art. 15", "x": "O preenchimento das graduações de 3º Sargento, Cabo e Soldado ocorrerá da seguinte forma: I- o ingresso nas graduações dar-se-á por promoção, à exceção dos Soldados, aos quais se aplica a regra do concurso público; III- o preenchimento das demais graduações far-se-á através de promoções nos termos da legislação específica.", "s": "Só o SOLDADO entra por concurso público; 3º Sargento e Cabo se preenchem por PROMOÇÃO, nunca por concurso direto."}'::jsonb),
('law_6513', 17, '{"t": "art", "n": "Art. 16", "x": "Os candidatos selecionados em concurso público para o cargo de formação de Soldado ingressarão na Polícia Militar como aluno, por um período correspondente à duração do curso.", "s": "Passou no concurso de Soldado? Durante o curso você é “ALUNO”, ainda não é praça — não confunda com “praça especial” (isso é só Cadete/Aspirante, art. 19 §3º)."}'::jsonb),
('law_6513', 18, '{"t": "cap", "x": "CAPÍTULO II — DA HIERARQUIA, DISCIPLINA E PRECEDÊNCIA"}'::jsonb),
('law_6513', 19, '{"t": "art", "n": "Art. 17", "x": "A hierarquia e a disciplina são as bases institucionais da Polícia Militar, sendo que a autoridade e a responsabilidade crescem com o grau hierárquico.\n§1º A hierarquia militar é a ordenação da autoridade em níveis diferentes, observadas a subordinação em diversos postos e graduações que constituem a carreira militar: I- a ordenação se faz por postos e graduações, observada a antiguidade no posto ou graduação; II- o respeito à hierarquia é consubstanciado no espírito de acatamento à sequência da autoridade.\n§2º A disciplina é a rigorosa observância e o acatamento integral às leis, regulamentos, normas e disposições que fundamentem o organismo policial-militar e coordenam o seu funcionamento regular e harmônico, traduzido pelo perfeito cumprimento do dever por parte de todos e de cada um dos integrantes da Organização Policial-Militar.\n§3º A disciplina e o respeito à hierarquia devem ser mantidos em todas as circunstâncias, entre militares da ativa, da reserva remunerada e reformados.", "s": "As DUAS colunas da PM: hierarquia (autoridade cresce com a patente) e disciplina (obediência integral às normas). E vale pra TODO MUNDO, até pra reserva e reformado — nunca “desliga”."}'::jsonb),
('law_6513', 20, '{"t": "art", "n": "Art. 18", "x": "Círculos hierárquicos são âmbitos de convivência entre militares da mesma categoria e têm a finalidade de desenvolver o espírito de camaradagem em ambiente de estima e confiança, sem prejuízo do respeito mútuo.", "s": "Círculo hierárquico = “panelinha oficial” de convívio social entre iguais, sem perder o respeito mútuo."}'::jsonb),
('law_6513', 21, '{"t": "art", "n": "Art. 19", "x": "Os círculos hierárquicos e a escala hierárquica da Polícia Militar:\nCÍRCULO DE OFICIAIS SUPERIORES: Coronel, Tenente-Coronel, Major.\nCÍRCULO DE OFICIAIS INTERMEDIÁRIOS: Capitão.\nCÍRCULO DE OFICIAIS SUBALTERNOS: 1º Tenente, 2º Tenente.\nPRAÇAS ESPECIAIS: o Aspirante-a-Oficial frequenta o círculo de oficiais subalternos; o Cadete, excepcionalmente ou em reuniões sociais, tem acesso ao círculo de oficiais.\nCÍRCULO DE SUBTENENTES E SARGENTOS: Subtenente, 1º Sargento, 2º Sargento, 3º Sargento.\nCÍRCULO DE CABOS E SOLDADOS: Cabo e Soldado. Os alunos do Curso de Formação de Sargentos, excepcionalmente ou em reuniões sociais, têm acesso ao círculo de subtenentes e sargentos. Os alunos do Curso de Formação de Cabos e Soldados frequentam o círculo de cabos e soldados.\n§1º Posto é o grau hierárquico do oficial, conferido por decreto do Governador do Estado e confirmado em Carta Patente.\n§2º Graduação é o grau hierárquico da praça, conferido por ato do Comandante-Geral da Polícia Militar.\n§3º Os Aspirantes-a-Oficial e os Cadetes são denominados Praças Especiais.\n§4º A todos os postos e graduações será acrescida a designação do seu respectivo quadro.\n§5º Os graus hierárquicos inicial e final dos diversos quadros e qualificações serão fixados separadamente, em lei específica.\n§6º Sempre que o militar da reserva remunerada ou reformado fizer uso do posto ou graduação, deverá fazê-lo mencionando essa situação.", "s": "Decore a escada: Superiores (Cel/TenCel/Maj) → Intermediários (Cap) → Subalternos (1ºTen/2ºTen) → Praças Especiais (Aspirante/Cadete) → Subtenente/Sargentos → Cabo/Soldado. E o pegador de prova: POSTO é de Oficial (decreto do Governador); GRADUAÇÃO é de praça (ato do Comandante-Geral)."}'::jsonb),
('law_6513', 22, '{"t": "art", "n": "Art. 20", "x": "A precedência hierárquica é regulada: I- pelo posto ou graduação; II- pela antiguidade no posto ou graduação, salvo quando ocorrer precedência funcional, estabelecida em lei.", "s": "Quem manda primeiro? 1º critério: o posto/graduação. 2º critério (empate): a antiguidade nele — salvo se a lei definir precedência funcional."}'::jsonb),
('law_6513', 23, '{"t": "art", "n": "Art. 21", "x": "A antiguidade no posto ou graduação será regulada: I- pela data da promoção; II- pela precedência sucessiva dos graus hierárquicos anteriores; III- pela data do ingresso na Corporação; IV- pela data de nascimento.\n§1º Nos casos de nomeação mediante concurso, de declaração de Aspirante-a-Oficial, de promoção à graduação de 3º Sargento e Cabo e de incorporação de Soldado, prevalecerá, para efeito de antiguidade, a ordem de classificação obtida no respectivo curso ou concurso.\n§2º Os Aspirantes-a-Oficial formados na Academia de Polícia Militar do Maranhão e por outras Academias, para efeito de antiguidade, considerar-se-ão as médias obtidas nos respectivos cursos e a mesma data de declaração de Aspirante-a-Oficial.\n§3º Em igualdade de posto ou graduação, os militares da ativa têm precedência sobre os da inatividade.\n§4º Em igualdade de posto ou graduação, a precedência entre militares da ativa e os da reserva remunerada, quando convocados, é definida pelo tempo de serviço no posto ou graduação.\n§5º A antiguidade no posto ou graduação, para efeito de promoção, é o tempo computado dia a dia no exercício de funções policiais-militares ou de natureza policial-militar.", "s": "Critérios de antiguidade em cascata (desempate): 1) data da promoção; 2) posto anterior; 3) data de ingresso; 4) data de nascimento (o mais velho ganha, por último critério). E: ativa sempre precede inatividade em empate."}'::jsonb),
('law_6513', 24, '{"t": "art", "n": "Art. 22", "x": "A precedência entre as praças especiais e as demais praças é assim definida: I- os Aspirantes-a-Oficial são hierarquicamente superiores às demais praças; II- os Cadetes são hierarquicamente superiores aos Subtenentes; III- os Alunos do Curso de Formação de Sargentos têm precedência sobre os Cabos; IV- os Alunos do Curso de Formação de Cabos têm precedência sobre os demais Soldados.", "s": "Ordem das praças especiais: Aspirante > todas as praças; Cadete > Subtenente; aluno-Sargento > Cabo; aluno-Cabo > Soldado."}'::jsonb),
('law_6513', 25, '{"t": "art", "n": "Art. 23", "x": "A Polícia Militar manterá um registro de todos os dados referentes ao pessoal da ativa e da reserva remunerada dentro dos respectivos quadros e escalas numéricas.", "s": "A PM mantém um “cadastro geral” de todo o efetivo, ativo e reserva remunerada."}'::jsonb),
('law_6513', 26, '{"t": "art", "n": "Art. 24", "x": "Os Cadetes são declarados Aspirantes-a-Oficial pelo Comandante-Geral da Polícia Militar do Maranhão, observado o disposto no §2º do art. 19 desta Lei.", "s": "Quem “batiza” o Cadete como Aspirante-a-Oficial é o Comandante-Geral — não é o Governador."}'::jsonb),
('law_6513', 27, '{"t": "cap", "x": "CAPÍTULO III — DO CARGO E DA FUNÇÃO POLICIAL MILITAR"}'::jsonb),
('law_6513', 28, '{"t": "art", "n": "Art. 25", "x": "Cargo policial-militar é aquele criado por lei, e que só pode ser exercido por policial-militar em serviço ativo.\n§1º É o especificado nos Quadros de Organização, caracterizado como tal em disposições legais.\n§2º A cada cargo corresponde um conjunto de atribuições, deveres e responsabilidades do respectivo titular.\n§3º Os cargos devem ser exercidos por policiais-militares de grau hierárquico compatível com as exigências e atribuições do cargo.", "s": "Cargo = criado por LEI + só exercido por quem está na ATIVA. Cada cargo tem seu “pacote” fixo de atribuições."}'::jsonb),
('law_6513', 29, '{"t": "art", "n": "Art. 26", "x": "O provimento de cargo policial militar será por ato de nomeação do Governador do Estado (competência que pode ser delegada aos Comandantes da Polícia Militar e do Corpo de Bombeiros Militar para o provimento de cargos privativos de Oficiais e Praças, conforme Decreto nº 22.708/2006).", "s": "Quem nomeia pro cargo é o Governador — mas ele PODE delegar aos Comandantes-Gerais da PM e do CBM."}'::jsonb),
('law_6513', 30, '{"t": "art", "n": "Art. 27", "x": "O cargo policial-militar é considerado vago a partir de sua criação e até que um policial-militar tome posse, ou desde o momento em que o ocupante exonerado o deixe, até que outro tome posse.\nParágrafo único - Consideram-se também vagos os cargos cujos ocupantes: a) tenham falecido; b) tenham sido considerados extraviados; c) tenham sido considerados desertores.", "s": "Cargo “vago” = ainda sem posse, ou depois que sai o titular (inclusive morte, extravio ou deserção)."}'::jsonb),
('law_6513', 31, '{"t": "art", "n": "Art. 28", "x": "Função policial-militar é o exercício das atividades e obrigações inerentes ao cargo policial-militar.", "s": "Cargo é o “título”; função é o que você de fato FAZ no dia a dia."}'::jsonb),
('law_6513', 32, '{"t": "art", "n": "Art. 29", "x": "Dentro de uma mesma Organização Policial-Militar, a sequência de substituições, bem como as normas, atribuições e responsabilidades, são estabelecidas na legislação peculiar, respeitadas a precedência e a qualificação exigidas para o exercício da função.", "s": "Quem substitui quem dentro da mesma unidade segue lei própria — sempre respeitando precedência e qualificação."}'::jsonb),
('law_6513', 33, '{"t": "art", "n": "Art. 30", "x": "As obrigações que, pela generalidade, peculiaridade, duração, vulto ou natureza, não sejam catalogadas como posições titulares em Quadro de Organização ou dispositivo legal, são cumpridas como “Encargo”, “Incumbência”, “Serviço”, “Atividade Policial-Militar” ou de “Natureza Policial-Militar”.", "s": "O que não vira “cargo oficial” no Quadro de Organização ganha outro nome: Encargo, Incumbência, Serviço ou Atividade Policial-Militar."}'::jsonb),
('law_6513', 34, '{"t": "art", "n": "Art. 31", "x": "O Comandante-Geral da Polícia Militar será nomeado pelo Governador do Estado, escolhido dentre Oficiais da ativa do último posto do Quadro de Combatentes, obedecida também a legislação federal em vigor.", "s": "Comandante-Geral: sempre nomeado pelo Governador, e sempre um Coronel (último posto) do Quadro de Combatentes da ativa."}'::jsonb),
('law_6513', 35, '{"t": "art", "n": "Art. 32", "x": "O cargo de Chefe do Estado-Maior, exercido cumulativamente com funções de Subcomandante, e o cargo de Subchefe do Estado-Maior serão exercidos obrigatoriamente por Coronéis QOPM da ativa da Corporação, nomeados pelo Governador do Estado.", "s": "Chefe do Estado-Maior (que acumula com Subcomandante) e Subchefe do Estado-Maior: sempre Coronel QOPM da ativa, nomeado pelo Governador."}'::jsonb),
('law_6513', 36, '{"t": "art", "n": "Art. 33", "x": "O servidor militar poderá encontrar-se, em relação ao cargo, nas seguintes situações: I- Efetivo - quando nomeado ou designado para exercer um cargo, satisfazendo os requisitos do grau hierárquico, do quadro e da especialização; II- Interino - quando desempenha as obrigações do cargo sem satisfazer aqueles requisitos.", "s": "No cargo você é EFETIVO (cumpre todos os requisitos) ou INTERINO (exerce sem cumprir todos os requisitos)."}'::jsonb),
('law_6513', 37, '{"t": "art", "n": "Art. 34", "x": "Na falta de militar qualificado para a função, poderá ser designado para o exercício da mesma outro militar de posto ou graduação inferior, obedecida a precedência hierárquica.", "s": "Faltou quem tem o requisito? Pode designar alguém de posto/graduação INFERIOR — mas sempre respeitando a hierarquia entre os disponíveis."}'::jsonb),
('law_6513', 38, '{"t": "art", "n": "Art. 35", "x": "São considerados no exercício de função policial-militar (ou de natureza/interesse militar) os militares da ativa que exercem funções no Quadro de Organização da PM, instrutores/alunos de estabelecimentos militares, ou colocados à disposição de órgãos como: Gabinetes da Presidência/Vice-Presidência da República, Estado-Maior das Forças Armadas, órgãos de inteligência de outras Polícias Militares, assessoria do Governador, Assembleia Legislativa, Tribunal de Justiça, SSP, Auditoria da Justiça Militar, DETRAN, Corregedoria do Sistema de Segurança Pública, Ministério Público, Tribunal de Contas, Tribunal Regional Eleitoral, Defensoria Pública, entre outros previstos em lei.", "s": "Lista de quem conta como “em função policial-militar”: quem trabalha no Quadro da PM, instrutor/aluno, OU está à disposição de órgãos externos (Governo, Judiciário, MP, TCE, TRE, Defensoria etc.)."}'::jsonb),
('law_6513', 39, '{"t": "art", "n": "Art. 36", "x": "§3º Ao militar posto à disposição desses órgãos referidos no artigo anterior NÃO se aplica o instituto da agregação.", "s": "PEGADINHA de prova: quem está à disposição desses órgãos externos NÃO é agregado — continua contando normalmente no efetivo, sem ficar “fora do número”."}'::jsonb),
('law_6513', 40, '{"t": "art", "n": "Art. 37", "x": "Os policiais-militares nomeados para cargo/função nos órgãos do art. 36 não podem passar à disposição de outro órgão enquanto nessa situação.", "s": "Já está à disposição de um órgão? Não pode “trocar de órgão” enquanto durar essa situação."}'::jsonb),
('law_6513', 41, '{"t": "art", "n": "Art. 38", "x": "Os nomeados para função ou cargo não catalogados nos arts. 35 e 36, bem como os excedentes às vagas dos quadros de organização, são considerados no exercício de função de natureza civil.", "s": "Cargo fora da lista dos arts. 35/36, ou excedente de vaga? Isso é considerado função de NATUREZA CIVIL."}'::jsonb),
('law_6513', 42, '{"t": "tit", "x": "TÍTULO II — DAS OBRIGAÇÕES E DOS DEVERES DOS POLICIAIS MILITARES"}'::jsonb),
('law_6513', 43, '{"t": "cap", "x": "CAPÍTULO I — DAS OBRIGAÇÕES POLICIAIS MILITARES"}'::jsonb),
('law_6513', 44, '{"t": "sec", "x": "SEÇÃO I — Do Valor Policial Militar"}'::jsonb),
('law_6513', 45, '{"t": "art", "n": "Art. 39", "x": "São manifestações essenciais do valor policial militar: I- o sentimento de servir à comunidade, pela vontade de cumprir o dever e o devotamento à preservação da ordem pública, mesmo com risco da própria vida; II- o civismo e o culto às tradições históricas; III- a fé na elevada missão da Polícia Militar; IV- o espírito de corpo; V- o amor à profissão militar; VI- o aprimoramento técnico-profissional.", "s": "“Valor policial-militar” em 6 palavras-chave: servir, civismo, fé na missão, espírito de corpo, amor à profissão, aprimoramento técnico."}'::jsonb),
('law_6513', 46, '{"t": "sec", "x": "SEÇÃO II — Das Obrigações e da Ética Policial-Militar"}'::jsonb),
('law_6513', 47, '{"t": "art", "n": "Art. 40", "x": "O sentimento do dever, a dignidade policial-militar e o decoro da classe impõem conduta moral e profissional irrepreensíveis, com observância de preceitos da ética policial-militar, entre eles: amar a verdade; exercer com autoridade, eficiência e probidade as funções; respeitar a dignidade da pessoa humana; cumprir e fazer cumprir leis/regulamentos/ordens; ser justo e imparcial; zelar pelo preparo próprio e dos subordinados; praticar a camaradagem; ser discreto; abster-se de tratar sigilosamente assuntos de Segurança Nacional fora do âmbito apropriado; acatar autoridades civis; cumprir deveres de cidadão; proceder de maneira ilibada; observar normas de boa educação; garantir assistência ao lar; conduzir-se, mesmo fora do serviço ou na inatividade, sem prejuízo à disciplina/decoro; abster-se de usar o posto/graduação para obter facilidades pessoais; abster-se, na inatividade, do uso das designações hierárquicas em atividades político-partidárias, comerciais, industriais, discussões pela imprensa (salvo autorização) ou funções de natureza não policial-militar; zelar pelo bom nome da Polícia Militar.", "s": "Ética do PM é uma lista longa, mas o pulo do gato é: vale MESMO fora do serviço e na INATIVIDADE — a ética “não bate ponto”."}'::jsonb),
('law_6513', 48, '{"t": "art", "n": "Art. 41", "x": "Ao policial-militar da ativa é vedado comerciar ou tomar parte na administração/gerência de sociedade, exceto como acionista ou quotista em sociedade anônima ou por quotas de responsabilidade limitada.\n§1º Os militares na reserva remunerada, quando convocados, ficam proibidos de tratar, nas organizações policiais-militares e repartições públicas civis, de interesses de empresas privadas.\n§2º Os policiais-militares da ativa podem exercer diretamente a gestão de seus próprios bens.\n§3º Aos integrantes do Quadro de Saúde é permitido o exercício da atividade técnico-profissional no meio civil, desde que não prejudique o serviço.", "s": "PM da ativa NÃO pode comerciar/administrar empresa — só pode ser sócio “de fora” (ações/quotas), sem gerir. Exceção: Quadro de Saúde pode clinicar fora, se não atrapalhar o serviço."}'::jsonb),
('law_6513', 49, '{"t": "art", "n": "Art. 42", "x": "O Comandante-Geral da Polícia Militar poderá determinar aos policiais militares da ativa que informem sobre a origem e a natureza de seus bens, sempre que houver razões que recomendem tal medida.", "s": "Comandante-Geral pode exigir que o PM da ativa explique a origem dos seus bens, se houver motivo pra desconfiar."}'::jsonb),
('law_6513', 50, '{"t": "cap", "x": "CAPÍTULO II — DOS DEVERES POLICIAIS-MILITARES"}'::jsonb),
('law_6513', 51, '{"t": "art", "n": "Art. 43", "x": "Os deveres policiais-militares compreendem, essencialmente: I- a dedicação integral ao serviço e a fidelidade à instituição, mesmo com sacrifício da própria vida; II- o culto aos símbolos nacionais; III- a probidade e a lealdade em todas as circunstâncias; IV- a disciplina e o respeito à hierarquia; V- o rigoroso cumprimento das obrigações e ordens; VI- a obrigação de tratar o subordinado dignamente e com urbanidade.\nParágrafo único - O cargo em comissão de Delegado-Geral da Polícia Civil está no nível da administração superior, como também estão o de Comandante-Geral da Polícia Militar e de Comandante-Geral do Corpo de Bombeiros Militar.", "s": "6 deveres essenciais: dedicação total, culto aos símbolos, probidade/lealdade, disciplina/hierarquia, cumprir ordens, tratar subordinado com dignidade."}'::jsonb),
('law_6513', 52, '{"t": "sec", "x": "SEÇÃO I — Do Compromisso Policial-Militar"}'::jsonb),
('law_6513', 53, '{"t": "art", "n": "Art. 44", "x": "Todo cidadão, após ingressar na Polícia Militar, presta compromisso de honra solene, na presença da tropa, aceitando as obrigações e deveres policiais-militares.", "s": "Ao entrar na PM, todo mundo faz um juramento solene, na frente da tropa."}'::jsonb),
('law_6513', 54, '{"t": "art", "n": "Art. 45", "x": "O compromisso de Aspirante-a-Oficial é prestado de acordo com o estabelecimento de ensino.", "s": "O juramento do Aspirante-a-Oficial segue o regramento próprio da escola militar."}'::jsonb),
('law_6513', 55, '{"t": "art", "n": "Art. 46", "x": "Ao ser promovido ao primeiro posto, o oficial presta novo compromisso, em solenidade especialmente programada.", "s": "Virou Oficial? Tem um SEGUNDO juramento, numa cerimônia especial — não é o mesmo do ingresso."}'::jsonb),
('law_6513', 56, '{"t": "art", "n": "Art. 47", "x": "Esse compromisso do oficial recém-promovido ao primeiro posto é prestado “perante a Bandeira do Brasil”.", "s": "Decore a expressão exata, é clássica de prova: o juramento do novo oficial é feito “perante a Bandeira do Brasil”."}'::jsonb),
('law_6513', 57, '{"t": "sec", "x": "SEÇÃO II — Do Comando e da Subordinação"}'::jsonb),
('law_6513', 58, '{"t": "art", "n": "Art. 48", "x": "O Comando é a soma de autoridade, deveres e responsabilidades de que o militar é investido legalmente, quando conduz homens ou dirige uma Organização Policial-Militar. É vinculado ao grau hierárquico e constitui prerrogativa impessoal, em cujo exercício o policial-militar se define como chefe.", "s": "Comando = autoridade + deveres + responsabilidade de quem lidera. É do CARGO, não da pessoa — prerrogativa impessoal."}'::jsonb),
('law_6513', 59, '{"t": "art", "n": "Art. 49", "x": "A subordinação não afeta, de modo algum, a dignidade pessoal do militar e decorre, exclusivamente, da estrutura hierárquica da Polícia Militar.", "s": "Obedecer não fere a dignidade de ninguém — é só a estrutura hierárquica funcionando, nada pessoal."}'::jsonb),
('law_6513', 60, '{"t": "art", "n": "Art. 50", "x": "O oficial é preparado ao longo da carreira para o exercício do comando, da chefia e da direção.", "s": "Oficial é formado, ao longo de toda a carreira, para comandar, chefiar e dirigir."}'::jsonb),
('law_6513', 61, '{"t": "art", "n": "Art. 51", "x": "Os subtenentes e sargentos auxiliam e complementam as atividades dos oficiais.", "s": "Subtenentes e Sargentos: papel de auxiliar e complementar o trabalho do Oficial."}'::jsonb),
('law_6513', 62, '{"t": "art", "n": "Art. 52", "x": "Os cabos e soldados são essencialmente elementos de execução.", "s": "Cabo e Soldado são, essencialmente, quem EXECUTA na ponta."}'::jsonb),
('law_6513', 63, '{"t": "art", "n": "Art. 53", "x": "Às praças especiais cabe a rigorosa observância das prescrições regulamentares.", "s": "Praças especiais (Aspirante/Cadete) têm que seguir os regulamentos à risca."}'::jsonb),
('law_6513', 64, '{"t": "art", "n": "Art. 54", "x": "Cabe ao policial-militar a responsabilidade integral pelas decisões, ordens e atos que praticar.", "s": "Regra de ouro: cada PM responde INTEGRALMENTE pelo que decide, ordena e faz."}'::jsonb),
('law_6513', 65, '{"t": "cap", "x": "CAPÍTULO III — DA VIOLAÇÃO DOS DEVERES E DAS OBRIGAÇÕES"}'::jsonb),
('law_6513', 66, '{"t": "art", "n": "Art. 55", "x": "A violação dos deveres e obrigações policiais-militares constituirá crime ou transgressão disciplinar, conforme a legislação ou regulamentos específicos.\n§1º A violação dos preceitos da ética policial-militar é tão mais grave quanto mais elevado for o grau hierárquico de quem a cometer.\n§2º No concurso de crime militar e de transgressão disciplinar, será aplicada somente a pena relativa ao crime.", "s": "Violar dever = crime OU transgressão. Quanto mais alta a patente, mais grave a falta. E se for crime + transgressão ao mesmo tempo, só se aplica a pena do CRIME (não soma as duas)."}'::jsonb),
('law_6513', 67, '{"t": "art", "n": "Art. 56", "x": "A inobservância dos deveres acarreta responsabilidade funcional, disciplinar ou penal. O policial-militar que se tornar incompatível com o cargo ou demonstrar incapacidade será afastado do cargo ou da função.", "s": "Não cumprir dever gera 3 tipos de responsabilidade: funcional, disciplinar ou penal — e pode até tirar o PM do cargo, se ele virar incompatível ou incapaz."}'::jsonb),
('law_6513', 68, '{"t": "art", "n": "Art. 57", "x": "§1º São competentes para determinar o afastamento imediato: o Governador do Estado, o Gerente de Estado de Segurança Pública e o Comandante-Geral da Polícia Militar.\n§3º O policial militar poderá ser transferido por conveniência da disciplina, quando da solução ou homologação de Sindicância, Inquérito Policial Militar, Conselho de Justificação, Conselho de Disciplina ou condenação judicial transitada em julgado.", "s": "Quem pode afastar na hora: Governador, Secretário/Gerente de Segurança Pública ou Comandante-Geral. E existe a “transferência por conveniência da disciplina” depois de Sindicância/IPM/Conselho/condenação."}'::jsonb),
('law_6513', 69, '{"t": "sec", "x": "Seção I — Dos Crimes Militares"}'::jsonb),
('law_6513', 70, '{"t": "art", "n": "Art. 58", "x": "Enquanto o Estado do Maranhão não dispuser de Tribunal Militar, a Auditoria da Justiça Militar Estadual é o órgão competente para processar e julgar os militares estaduais nos crimes militares, cabendo ao Tribunal de Justiça do Estado julgar em segunda instância.", "s": "Sem Tribunal Militar no MA: 1ª instância = Auditoria da Justiça Militar Estadual; 2ª instância (recurso) = Tribunal de Justiça."}'::jsonb),
('law_6513', 71, '{"t": "sec", "x": "Seção II — Das Transgressões Disciplinares"}'::jsonb),
('law_6513', 72, '{"t": "art", "n": "Art. 59", "x": "O Regulamento Disciplinar da Polícia Militar especificará as transgressões disciplinares e as normas relativas à amplitude e aplicação das penas disciplinares, à classificação do comportamento e aos recursos.\n§1º As penas disciplinares de detenção ou prisão não podem ultrapassar 30 (trinta) dias.\n§2º Ao cadete PM aplicam-se também as disposições disciplinares do estabelecimento de ensino em que estiver matriculado.", "s": "PEGADINHA: quem lista as transgressões é o REGULAMENTO Disciplinar, não este Estatuto. Prisão/detenção disciplinar: teto de 30 dias."}'::jsonb),
('law_6513', 73, '{"t": "sec", "x": "Seção III — Dos Conselhos de Justificação e Disciplina"}'::jsonb),
('law_6513', 74, '{"t": "art", "n": "Art. 60", "x": "O oficial presumivelmente incapaz de permanecer como policial-militar da ativa será submetido a Conselho de Justificação.\n§1º Ao ser submetido, o oficial é automaticamente afastado do exercício de suas funções.\n§2º Compete ao Tribunal de Justiça do Estado julgar os processos oriundos dos Conselhos de Justificação.\n§3º O Conselho de Justificação também pode ser aplicado a oficiais da reserva remunerada e reformados.", "s": "OFICIAL incapaz de continuar → Conselho de JUSTIFICAÇÃO. Afasta na hora. Quem julga em última instância: Tribunal de Justiça."}'::jsonb),
('law_6513', 75, '{"t": "art", "n": "Art. 61", "x": "O Aspirante-a-Oficial PM, bem como as praças com estabilidade assegurada, presumivelmente incapazes de permanecerem na ativa, serão submetidos a Conselho de Disciplina.\n§1º Ao serem submetidos, serão afastados das atividades que estiverem exercendo.\n§2º Compete ao Conselho Superior de Polícia julgar, em última instância, os processos oriundos dos Conselhos de Disciplina.\n§3º Também aplicável às praças da reserva remunerada e reformados.", "s": "ASPIRANTE e PRAÇA ESTÁVEL incapazes → Conselho de DISCIPLINA (não Justificação!). Quem julga: Conselho Superior de Polícia (não o TJ)."}'::jsonb),
('law_6513', 76, '{"t": "tit", "x": "TÍTULO III — DOS DIREITOS E PRERROGATIVAS DOS POLICIAIS MILITARES"}'::jsonb),
('law_6513', 77, '{"t": "cap", "x": "CAPÍTULO I — DOS DIREITOS"}'::jsonb),
('law_6513', 78, '{"t": "art", "n": "Art. 62", "x": "São direitos dos policiais-militares: I- garantia da patente em toda sua plenitude, quando oficial; II- os proventos da inatividade calculados de acordo com a remuneração do posto/graduação por ocasião da transferência; III- nas condições ou limitações legais: a) a estabilidade, quando praças, com 5 (cinco) anos de efetivo exercício; b) o uso das designações hierárquicas; c) a ocupação de cargo ou função correspondente; d) a percepção de remuneração; e) outros direitos previstos nesta Lei; f) a pensão por morte, aos dependentes; g) a promoção; h) a transferência, a pedido, para a reserva remunerada; i) as férias, ou afastamentos temporários; j) a demissão e o licenciamento voluntário; l) o porte de arma, quando oficial, salvo se reformado por alienação mental ou condenado por crime contra a Segurança Nacional, ou atividade que desaconselhe; m) o porte de arma, pelas praças, com as restrições impostas pelo Comando-Geral; n) a assistência jurídica, quando a infração penal for praticada em ato de serviço; o) gratificação natalina; p) garantia de vaga para filhos no Colégio Militar, se promovido pelo critério post mortem.", "s": "Lista grande de direitos — os 2 que mais caem: PRAÇA fica ESTÁVEL com 5 anos de serviço; e porte de arma é AUTOMÁTICO pro Oficial (com exceções) mas RESTRITO pra praça (conforme o Comando-Geral definir)."}'::jsonb),
('law_6513', 79, '{"t": "art", "n": "Art. 63", "x": "O servidor militar que se julgar prejudicado por ato administrativo ou disciplinar de superior hierárquico poderá recorrer, ou interpor pedido de reconsideração, queixa ou representação.\n§1º O direito de recorrer prescreve: I- em 30 (trinta) dias, quando se tratar de composição de Quadro de Acesso para promoção; II- em 120 (cento e vinte) dias corridos, nos demais casos.\n§2º O pedido de reconsideração, a queixa e a representação não podem ser feitos coletivamente.\n§3º O militar da ativa que se dirigir ao Poder Judiciário deverá comunicar, antecipadamente, essa iniciativa à autoridade a que estiver subordinado.", "s": "Prazos pra recorrer: 30 dias (Quadro de Acesso/promoção) x 120 dias (demais casos). Recurso NUNCA é coletivo. E antes de ir à Justiça, tem que AVISAR o superior antes."}'::jsonb),
('law_6513', 80, '{"t": "art", "n": "Art. 64", "x": "São alistáveis, como eleitores, todos os policiais-militares.\n§1º Os militares alistáveis são elegíveis, atendidas as seguintes condições: I- se contar menos de 10 (dez) anos de serviço, deverá afastar-se da atividade; II- se contar mais de 10 (dez) anos de serviço, será agregado pela autoridade superior e, se eleito, passará automaticamente, no ato da diplomação, para a inatividade; III- suspende-se, nos casos dos incisos I e II, o pagamento das gratificações e indenizações, salvo exceções legais.\n§2º O militar, enquanto em atividade, não pode estar filiado a partido político.\n§3º Ao militar são proibidas a sindicalização e a greve.", "s": "Todo PM VOTA. Pra ser CANDIDATO: menos de 10 anos → precisa se afastar; mais de 10 anos → é agregado e, se eleito, vai pra inatividade na diplomação. Na ativa: proibido filiação partidária, sindicato e greve."}'::jsonb),
('law_6513', 81, '{"t": "sec", "x": "SEÇÃO I — Da Remuneração"}'::jsonb),
('law_6513', 82, '{"t": "art", "n": "Art. 65", "x": "O policial militar da ativa é remunerado por subsídio, fixado em parcela única, vedado o acréscimo de qualquer gratificação, adicional, abono, prêmio, verba de representação ou outra espécie remuneratória.", "s": "PM da ativa recebe por SUBSÍDIO (parcela única) — proibido “pendurar” gratificação, adicional, abono, prêmio em cima."}'::jsonb),
('law_6513', 83, '{"t": "art", "n": "Art. 66", "x": "O policial-militar inativo recebe proventos.", "s": "Inativo não recebe “subsídio”, recebe PROVENTOS — nome técnico diferente, adora ser trocado em prova."}'::jsonb),
('law_6513', 84, '{"t": "art", "n": "Art. 69", "x": "Além do subsídio, os policiais militares têm direito às seguintes verbas indenizatórias: I- diárias; II- ajuda de custo; III- ajuda de curso; IV- salário-família; V- fardamento; VI- adicional de férias; VII- retribuição por exercício em local de difícil provimento.", "s": "Verbas indenizatórias além do subsídio: diárias, ajuda de custo, ajuda de curso, salário-família, fardamento, adicional de férias, difícil provimento."}'::jsonb),
('law_6513', 85, '{"t": "art", "n": "Art. 73", "x": "A remuneração na inatividade é irredutível e deve ser revista automaticamente na mesma data da revisão da remuneração dos militares da ativa, para preservar o valor equivalente à remuneração do militar da ativa do correspondente posto ou graduação.", "s": "Provento do inativo: IRREDUTÍVEL e reajusta JUNTO (mesma data) com o salário da ativa — princípio da paridade."}'::jsonb),
('law_6513', 86, '{"t": "sec", "x": "SEÇÃO II — Da Promoção"}'::jsonb),
('law_6513', 87, '{"t": "art", "n": "Art. 77", "x": "O acesso à hierarquia militar é seletivo, gradual e sucessivo, e se faz mediante promoções, de modo a obter-se um fluxo regular e equilibrado.\n§1º O planejamento da carreira dos oficiais e das praças é atribuição do Comando-Geral da Polícia Militar.\n§2º A promoção é ato administrativo cuja finalidade básica é a seleção dos militares para o exercício de funções do grau hierárquico superior.", "s": "Subir na hierarquia é SELETIVO, GRADUAL e SUCESSIVO — nunca pula degrau."}'::jsonb),
('law_6513', 88, '{"t": "art", "n": "Art. 78", "x": "(Caput com redação dada pelo art. 122 da Lei nº 12.896/2026) As promoções serão efetuadas pelos critérios de antiguidade, merecimento, tempo de serviço, por bravura, “post mortem”, e a promoção por completar os requisitos para transferência a pedido ou compulsória, mediante ato do Governador do Estado, para oficiais, e do Comandante-Geral, para praças.\n§1º Em casos extraordinários poderá haver promoção em ressarcimento de preterição.\n§2º Essa promoção segue os princípios de antiguidade e merecimento, recebendo o militar o número que lhe competir na escala hierárquica, como se tivesse sido promovido na época devida.\n§3º É nula de pleno direito a promoção ocorrida em desacordo com a legislação vigente.\n§4º Os Praças, além dos critérios do caput, também concorrem às promoções por tempo de serviço.\n§5º Em caso de promoção “post-mortem”, a pensão do militar falecido passará a ser calculada com base na remuneração correspondente ao posto ou graduação alcançados, a contar da data do evento morte.\n§6º (Acrescido pela Lei nº 12.896/2026) Após análise/classificação/recomendação das promoções pelas Comissões, os processos vão ao Comandante-Geral (aprecia e lavra os atos), seguem ao Secretário de Estado da Segurança Pública (analisa e aprova), que encaminha os atos de OFICIAIS ao Governador e devolve os atos de PRAÇAS ao Comandante-Geral para assinatura.", "s": "ATUALIZADO pela Lei 12.896/2026: quem assina a promoção é o GOVERNADOR (oficiais) e o COMANDANTE-GERAL (praças) — antes o texto não separava assim. E o novo §6º cria o fluxo: Comissão → Comandante-Geral → Secretário de Segurança Pública → (oficial) Governador / (praça) volta ao Comandante-Geral. Fora da lei = promoção NULA de pleno direito."}'::jsonb),
('law_6513', 89, '{"t": "art", "n": "Art. 79", "x": "Não haverá promoção de policial-militar por ocasião de sua transferência para a reserva remunerada ou por ocasião de sua reforma.", "s": "Decore: SAIR (reserva/reforma) não vem acompanhado de promoção — quem sai, sai no posto que já tinha."}'::jsonb),
('law_6513', 90, '{"t": "art", "n": "Art. 79-A", "x": "(Redação dada pelo art. 123 da Lei nº 12.896/2026) As promoções dos militares estaduais ocorrerão anualmente nos meses de março, agosto e dezembro.", "s": "ATUALIZADO pela Lei 12.896/2026: agora são 3 datas de promoção por ano — MARÇO, AGOSTO e DEZEMBRO (antes eram só agosto e dezembro)."}'::jsonb),
('law_6513', 91, '{"t": "sec", "x": "SEÇÃO III — Das Férias e Outros Afastamentos Temporários do Serviço"}'::jsonb),
('law_6513', 92, '{"t": "art", "n": "Art. 80", "x": "O militar goza, por ano, obrigatoriamente, 30 (trinta) dias consecutivos de férias remuneradas.\n§1º Só adquire direito às férias após os 12 primeiros meses de efetivo exercício.\n§2º Compete ao Comandante-Geral normatizar a concessão de férias anuais.\n§3º A concessão das férias não é prejudicada pelo gozo anterior de licença para tratamento de saúde e de licença-prêmio.\n§4º Só em declaração de guerra, estado de sítio, estado de defesa, grave perturbação da ordem pública ou extrema necessidade do serviço as férias podem ser interrompidas/não gozadas na época prevista.\n§5º É pago ao militar, por ocasião das férias, um adicional correspondente a 1/3 (um terço) da remuneração do período de férias.", "s": "30 dias de férias por ano — mas só depois de 12 meses de efetivo exercício (1º ano não tem). Só é cancelada em situação EXCEPCIONAL (guerra, sítio, defesa, grave perturbação). E tem o terço constitucional de 1/3."}'::jsonb),
('law_6513', 93, '{"t": "art", "n": "Art. 81", "x": "Durante as férias, o militar tem direito a todas as vantagens do cargo.", "s": "De férias, o PM continua recebendo TODAS as vantagens do cargo normalmente."}'::jsonb),
('law_6513', 94, '{"t": "art", "n": "Art. 82", "x": "Só é permitida a acumulação de férias até o máximo de dois anos, em caso de imperiosa necessidade de serviço.", "s": "Pode acumular férias, mas só até 2 anos, e só por necessidade IMPERIOSA de serviço."}'::jsonb),
('law_6513', 95, '{"t": "art", "n": "Art. 83", "x": "O pagamento da remuneração das férias é efetuado no mês antecedente ao gozo.", "s": "Dinheiro das férias cai ANTES: no mês anterior ao início do gozo."}'::jsonb),
('law_6513', 96, '{"t": "art", "n": "Art. 84", "x": "Os militares têm direito aos seguintes períodos de afastamento total do serviço: I- núpcias, 8 (oito) dias; II- luto, 8 (oito) dias, por falecimento do cônjuge/companheiro, pais, madrasta, padrasto, pais adotivos, filhos, menor sob guarda/tutela e irmãos; III- trânsito, até 30 (trinta) dias; IV- instalação, até 10 (dez) dias.", "s": "Decore os números: núpcias 8 dias, luto 8 dias, trânsito até 30 dias, instalação até 10 dias."}'::jsonb),
('law_6513', 97, '{"t": "art", "n": "Art. 85", "x": "Trânsito é o período para preparativos de mudança de sede; instalação é o período após o término do trânsito, na apresentação na nova Organização Policial-Militar. Essas férias e afastamentos são concedidos com remuneração total e computados como tempo de efetivo serviço.", "s": "Trânsito = tempo pra se mudar. Instalação = tempo pra se apresentar na nova unidade, depois do trânsito. Os dois são REMUNERADOS e contam como tempo de serviço."}'::jsonb),
('law_6513', 98, '{"t": "sec", "x": "SEÇÃO IV — Do Salário-Família"}'::jsonb),
('law_6513', 99, '{"t": "art", "n": "Art. 86", "x": "Salário-família é o auxílio pecuniário especial concedido pelo Estado ao militar ativo, em disponibilidade, e ao inativo, para despesas com dependentes.", "s": "Salário-família = ajuda financeira extra pra quem tem dependentes — vale pra ativo, disponível e inativo."}'::jsonb),
('law_6513', 100, '{"t": "art", "n": "Art. 87", "x": "São dependentes econômicos: cônjuge/companheiro(a); filhos (inclusive enteados/adotivos) até 21 anos, ou até 24 se estudante, ou de qualquer idade se inválido; mãe e pai sem economia própria.", "s": "Dependentes: cônjuge; filhos até 21 (24 se estudante, sem limite se inválido); pai/mãe sem renda própria."}'::jsonb),
('law_6513', 101, '{"t": "art", "n": "Art. 88", "x": "Não se configura dependência econômica quando o beneficiário perceber rendimento igual ou superior ao salário mínimo.", "s": "Ganha 1 salário mínimo ou mais? Deixa de ser considerado dependente."}'::jsonb),
('law_6513', 102, '{"t": "art", "n": "Art. 89", "x": "Quando pai e mãe forem PMs e viverem em comum, o salário-família é pago a um deles.", "s": "Pai e mãe os dois PMs, morando juntos? O salário-família é pago a UM só, não em dobro."}'::jsonb),
('law_6513', 103, '{"t": "art", "n": "Art. 90", "x": "O salário-família não está sujeito a qualquer tributo, nem serve de base a contribuição previdenciária.", "s": "Salário-família não paga imposto e não entra na base do INSS/previdência."}'::jsonb),
('law_6513', 104, '{"t": "art", "n": "Art. 91", "x": "O salário-família não é percebido quando o militar deixar de receber o soldo/provento.", "s": "Sem soldo/provento, também não tem salário-família — os dois andam juntos."}'::jsonb),
('law_6513', 105, '{"t": "sec", "x": "SEÇÃO V — Das Licenças"}'::jsonb),
('law_6513', 106, '{"t": "art", "n": "Art. 92", "x": "Licença é a autorização para o afastamento total do serviço em caráter temporário.\n§1º A licença pode ser: I- licença-prêmio; II- para tratamento de saúde em pessoa da família; III- para tratar de interesse particular; IV- para tratamento de saúde; V- à gestante; VI- paternidade.\n§2º A remuneração do militar, em gozo dessas licenças, é regulada pela legislação peculiar.", "s": "6 tipos de licença: prêmio, saúde de familiar, interesse particular, saúde própria, gestante, paternidade — decore essa listinha."}'::jsonb),
('law_6513', 107, '{"t": "art", "n": "Art. 93", "x": "Licença-prêmio é a autorização para afastamento total do serviço, relativa a cada quinquênio de tempo de efetivo serviço prestado, concedida ao militar que a requerer, sem restrição para carreira e remuneração.\n§1º Tem a duração de 03 (três) meses, gozada de uma só vez, a cada quinquênio de serviço, quando solicitada.\n§2º O período de licença-prêmio não interrompe a contagem de tempo de serviço, nem é prejudicado pelo gozo anterior de qualquer licença, e não anula o direito àquelas licenças, EXCETO a licença prevista no item II do art. 92 (tratamento de saúde em pessoa da família).\n§4º Uma vez concedida, o militar fica à disposição do órgão de pessoal da Corporação, sem prejuízo de sua remuneração.", "s": "Licença-prêmio: 3 meses a cada 5 anos, de uma vez, sem prejuízo de carreira/remuneração. Não soma com outras licenças, EXCETO a de saúde de familiar (essa é a exceção que mais cai)."}'::jsonb),
('law_6513', 108, '{"t": "art", "n": "Art. 94", "x": "Licença para tratamento de saúde em pessoa da família é a autorização para afastamento total do serviço, concedida ao militar que a requerer, com a finalidade de acompanhar seus dependentes em tratamento de saúde.\nParágrafo único - Essa licença não poderá exceder 06 (seis) meses e será concedida com os vencimentos e vantagens integrais até 03 (três) meses, sofrendo, se superior a esse período, o desconto de um terço.", "s": "Cuidar de família doente: até 6 meses. Até 3 meses = remuneração integral; depois disso, desconta 1/3."}'::jsonb),
('law_6513', 109, '{"t": "art", "n": "Art. 95", "x": "Licença para tratar de interesse particular é a autorização para afastamento total do serviço, concedida ao militar com mais de 10 (dez) anos de efetivo serviço que a requerer, com a finalidade de tratar de assuntos particulares, sendo sempre concedida com prejuízo da remuneração e do tempo de serviço, não podendo exceder 02 (dois) anos.", "s": "Interesse particular: só com +10 anos de serviço, até 2 anos, SEM remuneração e SEM contar tempo de serviço."}'::jsonb),
('law_6513', 110, '{"t": "art", "n": "Art. 96", "x": "Licença para tratamento de saúde é a autorização para o afastamento total do serviço e da instrução concedida ao militar que for julgado, pela Junta Militar de Saúde, incapaz temporariamente para o serviço ativo.", "s": "Licença-saúde própria depende de laudo da Junta Militar de Saúde (incapacidade temporária)."}'::jsonb),
('law_6513', 111, '{"t": "art", "n": "Art. 97", "x": "A licença-maternidade será concedida pelo prazo de 180 (cento e oitenta) dias, sem prejuízo da remuneração.\nParágrafo único - À militar que adotar ou obtiver guarda judicial para fins de adoção serão concedidos também 180 (cento e oitenta) dias de licença remunerada, independentemente da idade da criança.", "s": "Licença-maternidade: 180 dias remunerados — vale igual pra adoção/guarda, não importa a idade da criança."}'::jsonb),
('law_6513', 112, '{"t": "art", "n": "Art. 98", "x": "A licença-prêmio, a licença-paternidade e a licença para tratar de interesse particular poderão ser interrompidas: a) em caso de mobilização, estado de defesa, grave perturbação da ordem pública, estado de sítio e intervenção federal; b) para cumprimento de sentença que importe restrição da liberdade individual; c) para cumprimento de punição disciplinar; d) em caso de denúncia, pronúncia em processo criminal ou indiciação em inquérito.\n§1º A interrupção da licença para tratamento de saúde em pessoa da família será regulada pelo Comandante-Geral.\n§2º A concessão de licença-prêmio e de licença para tratar de interesse particular será regulada por Decreto.\n§3º Pelo nascimento ou adoção de filhos, o militar terá direito à licença-paternidade pelo prazo de 5 (cinco) dias consecutivos, contados a partir do nascimento/adoção, podendo esse prazo ser prorrogado por 15 (quinze) dias, mediante requerimento comprovando participação em programa de paternidade responsável; no período de prorrogação, o policial não pode exercer nenhuma outra atividade remunerada e deve manter a criança sob seus cuidados.", "s": "Licença-paternidade: 5 dias + pode prorrogar por mais 15 dias (com programa de paternidade responsável) — mas na prorrogação não pode trabalhar em outra coisa."}'::jsonb),
('law_6513', 113, '{"t": "cap", "x": "CAPÍTULO II — DAS PRERROGATIVAS"}'::jsonb),
('law_6513', 114, '{"t": "art", "n": "Art. 99", "x": "As prerrogativas dos policiais-militares são constituídas pelas honras, dignidade e distinção devidas aos graus hierárquicos e cargos: I- uso de títulos, uniforme, distintivos, insígnias e emblemas militares correspondentes ao posto ou graduação; II- honras, tratamentos e sinais de respeito assegurados em leis e regulamentos; III- cumprimento de pena privativa de liberdade somente em Organização Policial Militar cujo comandante, chefe ou diretor tenha precedência hierárquica sobre o apenado; IV- julgamento em foro especial, nos crimes militares.", "s": "Prerrogativas: uniforme/título do posto, honras/tratamento especial, prisão só em unidade com comandante hierarquicamente SUPERIOR ao preso, foro especial em crime militar."}'::jsonb),
('law_6513', 115, '{"t": "art", "n": "Art. 100", "x": "O policial-militar só pode ser preso por autoridade policial em caso de flagrante delito.\n§1º Nesse caso, só pode ser detido na delegacia/posto policial durante o tempo necessário à lavratura do flagrante, sendo imediatamente apresentado à autoridade militar mais próxima.\n§2º Cabe ao Comandante-Geral a iniciativa de responsabilizar a autoridade policial que descumprir isso ou maltratar o preso.", "s": "Autoridade POLICIAL só pode prender o PM em FLAGRANTE — e só até lavrar o auto, depois vai direto pra autoridade militar."}'::jsonb),
('law_6513', 116, '{"t": "art", "n": "Art. 101", "x": "Os servidores militares da ativa são dispensados do corpo de jurados da Justiça comum e do serviço da Justiça Eleitoral.", "s": "PM da ativa é DISPENSADO de júri popular e do serviço da Justiça Eleitoral."}'::jsonb),
('law_6513', 117, '{"t": "sec", "x": "SEÇÃO ÚNICA — Do Uso dos Uniformes"}'::jsonb),
('law_6513', 118, '{"t": "art", "n": "Art. 102", "x": "Os uniformes da Polícia Militar, com seus distintivos, insígnias e emblemas, são privativos dos policiais-militares e representam o símbolo da autoridade policial-militar.\nParágrafo único - Constitui crime o desrespeito aos uniformes/distintivos/insígnias/emblemas, bem como o uso por quem não tem direito.", "s": "Uniforme é EXCLUSIVO do PM e símbolo de autoridade. Usar sem ter direito, ou desrespeitá-lo, é CRIME."}'::jsonb),
('law_6513', 119, '{"t": "art", "n": "Art. 103", "x": "É proibido ao policial-militar o uso de uniforme: I- em manifestação de caráter político-partidário; II- na inatividade, salvo para comparecer a solenidade militar autorizada, cerimônias cívicas/comemorativas ou atos sociais particulares; III- no estrangeiro, em atividades não relacionadas com a missão, salvo autorização.", "s": "3 proibições de uso de farda: ato político-partidário; na inatividade (salvo solenidade/cerimônia autorizada); no exterior fora da missão."}'::jsonb),
('law_6513', 120, '{"t": "art", "n": "Art. 104", "x": "É vedado a qualquer cidadão ou organização civil usar uniforme, distintivo, insígnia ou emblema que possa ser confundido com os da Polícia Militar do Maranhão.", "s": "Nenhum civil ou entidade civil pode usar farda/distintivo que se confunda com o da PMMA."}'::jsonb),
('law_6513', 121, '{"t": "art", "n": "Art. 105", "x": "Dispositivo complementar do Estatuto que fecha o regramento sobre uniformes, distintivos e insígnias da Polícia Militar do Maranhão, dentro do conjunto normativo dos arts. 102 a 104.", "s": "Detalhe complementar do capítulo do uniforme — o essencial pra prova está mesmo nos arts. 102 a 104 (privatividade, proibições de uso e vedação a civis)."}'::jsonb),
('law_6513', 122, '{"t": "tit", "x": "TÍTULO IV — DAS DISPOSIÇÕES DIVERSAS"}'::jsonb),
('law_6513', 123, '{"t": "cap", "x": "CAPÍTULO I — DAS SITUAÇÕES ESPECIAIS"}'::jsonb),
('law_6513', 124, '{"t": "sec", "x": "SEÇÃO I — Da Agregação"}'::jsonb),
('law_6513', 125, '{"t": "art", "n": "Art. 106", "x": "Agregação é a situação na qual o policial-militar da ativa deixa de ocupar vaga na escala hierárquica do seu quadro, nela permanecendo sem número.\n§1º O policial-militar deve ser agregado quando for afastado temporariamente do serviço por motivo de, entre outros: ter sido julgado incapaz temporariamente, após um ano contínuo de tratamento de saúde; ter sido julgado incapaz definitivamente, enquanto tramita o processo de reforma; haver ultrapassado 1 ano contínuo de licença para tratamento de saúde própria; haver ultrapassado 6 meses de licença para tratamento de saúde em pessoa da família; haver ultrapassado 6 meses de licença para tratar de interesse particular; ter sido considerado oficialmente extraviado; haver-se esgotado o prazo que caracteriza o crime de deserção, se oficial ou praça com estabilidade assegurada; como desertor, ter-se apresentado voluntariamente ou capturado e reincluído; ter sido condenado à pena restritiva de liberdade superior a 2 anos, sem livramento condicional; ter sido condenado à pena restritiva de liberdade superior a 6 meses, enquanto durar a execução; ter-se candidatado a cargo eletivo, contando com mais de 10 anos de serviço; ter sido condenado à pena de suspensão do exercício de posto/graduação; ter sido nomeado para cargo em comissão, emprego ou função pública temporária não eletiva; afastar-se para integrar diretoria de entidade representativa de classe, clube ou associação policial militar.\n§2º O militar agregado nos casos de incapacidade temporária, incapacidade definitiva (aguardando reforma), excesso de licença-saúde própria, e deserção apresentada/capturada, continua a ser considerado como em serviço ativo.\n§7º O militar agregado fica sujeito às obrigações regulamentares concernentes às suas relações com outros militares e autoridades civis.\n§8º O militar agregado não poderá ser promovido enquanto durar a sua agregação.", "s": "Agregado = “sai do número” mas continua ligado à PM (doente há +1 ano, aguardando reforma, licença estourada, candidato +10 anos, cargo comissionado etc.). Regra de ouro: agregado NÃO pode ser promovido."}'::jsonb),
('law_6513', 126, '{"t": "art", "n": "Art. 107", "x": "A agregação do militar se faz por ato do Governador do Estado ou de autoridade à qual tenham sido delegados poderes para tal.", "s": "Quem agrega é o Governador (ou quem ele delegar)."}'::jsonb),
('law_6513', 127, '{"t": "sec", "x": "SEÇÃO II — Da Reversão"}'::jsonb),
('law_6513', 128, '{"t": "art", "n": "Art. 108", "x": "A reversão é o ato pelo qual o militar agregado retorna ao respectivo quadro tão logo cesse o motivo que determinou a sua agregação, voltando a ocupar o lugar que lhe couber na escala numérica. Pode ser efetuada a qualquer tempo, por ato da autoridade que decretou a agregação.", "s": "Reversão = voltar pro quadro normal assim que acaba o motivo da agregação — pode acontecer a qualquer momento."}'::jsonb),
('law_6513', 129, '{"t": "art", "n": "Art. 109", "x": "Parágrafo único - Ao completar 02 (dois) anos contínuos ou não na situação de agregado, a reversão dar-se-á automaticamente, sem exigência do ato de reversão.", "s": "Completou 2 anos agregado? A reversão é AUTOMÁTICA — nem precisa de ato formal."}'::jsonb),
('law_6513', 130, '{"t": "sec", "x": "SEÇÃO III — Do Excedente"}'::jsonb),
('law_6513', 131, '{"t": "art", "n": "Art. 110", "x": "Excedente é a situação especial e transitória a que passa o militar que, entre outras hipóteses, tendo cessado o motivo de sua agregação, reverte ao quadro estando este com efetivo completo; ou é promovido por bravura sem haver vaga.\n§1º Ocupa a mesma posição relativa à antiguidade que lhe cabe, com a abreviatura “Excd.”.\n§2º É considerado como em efetivo serviço para todos os efeitos, concorrendo em igualdade de condições a qualquer cargo militar.\n§3º O militar promovido por bravura, sem haver vaga, ocupará a primeira vaga aberta.", "s": "Excedente = está no quadro “sobrando” (efetivo já completo, ou promovido por bravura sem vaga). Conta normalmente como serviço ativo, com a sigla “Excd.”."}'::jsonb),
('law_6513', 132, '{"t": "sec", "x": "SEÇÃO IV — Do Ausente e do Desertor"}'::jsonb),
('law_6513', 133, '{"t": "art", "n": "Art. 111", "x": "É considerado ausente o militar que por mais de 24 (vinte e quatro) horas consecutivas deixar de comparecer à sua Organização Policial-Militar sem comunicar motivo, ou ausentar-se sem licença.", "s": "Ausente = sumiu por +24h sem avisar ou sem licença."}'::jsonb),
('law_6513', 134, '{"t": "art", "n": "Art. 112", "x": "O militar é considerado desertor nos casos previstos na legislação pertinente (Código Penal Militar).", "s": "Deserção propriamente dita é definida pelo Código Penal Militar, não por este Estatuto."}'::jsonb),
('law_6513', 135, '{"t": "sec", "x": "SEÇÃO V — Do Desaparecimento e do Extravio"}'::jsonb),
('law_6513', 136, '{"t": "art", "n": "Art. 113", "x": "É considerado desaparecido o militar da ativa que, em serviço/viagem/operação/calamidade, tiver paradeiro ignorado por mais de 08 (oito) dias consecutivos, desde que não haja indícios de deserção.", "s": "Desaparecido = sumiu em serviço por +8 dias, sem indício de deserção."}'::jsonb),
('law_6513', 137, '{"t": "art", "n": "Art. 114", "x": "Permanecendo desaparecido por mais de 30 (trinta) dias, será oficialmente considerado extraviado.", "s": "Passou de 30 dias desaparecido → vira, oficialmente, EXTRAVIADO."}'::jsonb),
('law_6513', 138, '{"t": "cap", "x": "CAPÍTULO II — DO DESLIGAMENTO OU EXCLUSÃO DO SERVIÇO ATIVO"}'::jsonb),
('law_6513', 139, '{"t": "art", "n": "Art. 115", "x": "O desligamento ou exclusão do serviço ativo decorre de: I- transferência para a reserva remunerada; II- demissão; III- reforma; IV- perda do posto e da patente; V- licenciamento; VI- exclusão a bem da disciplina; VII- deserção; VIII- falecimento; IX- extravio, após a conclusão do IPM.", "s": "9 formas de sair da ativa: reserva, demissão, reforma, perda de posto/patente, licenciamento, exclusão disciplinar, deserção, morte, extravio (após IPM)."}'::jsonb),
('law_6513', 140, '{"t": "art", "n": "Art. 116", "x": "A transferência para a reserva remunerada ou a reforma não isenta o militar da indenização de prejuízos causados à Fazenda Estadual ou a terceiros, nem do pagamento de pensões decorrentes de sentença judicial.", "s": "Sair pra reserva/reforma NÃO livra o PM de indenizar o Estado ou pagar pensão de sentença judicial."}'::jsonb),
('law_6513', 141, '{"t": "art", "n": "Art. 117", "x": "O militar da ativa enquadrado nessas hipóteses, ou demissionário a pedido, passa à disposição do órgão de pessoal até ser desligado.", "s": "Enquanto o processo de saída não termina, o PM fica “à disposição” do órgão de pessoal."}'::jsonb),
('law_6513', 142, '{"t": "sec", "x": "SEÇÃO I — Da Transferência para a Reserva Remunerada"}'::jsonb),
('law_6513', 143, '{"t": "art", "n": "Art. 118", "x": "A transferência para a reserva remunerada se efetua a pedido ou ex-officio. A pedido, será concedida: I- com remuneração integral, se cumprido tempo mínimo de 35 anos de serviço, dos quais no mínimo 30 anos de atividade de natureza militar; ou II- com remuneração proporcional, com base em tantas quotas quanto forem os anos de serviço, se não atingido o tempo mínimo.", "s": "Reserva remunerada A PEDIDO: integral com 35 anos de serviço (30 deles militares); senão, proporcional por “quotas”."}'::jsonb),
('law_6513', 144, '{"t": "art", "n": "Art. 119", "x": "§1º e §2º Se o militar tiver realizado curso/estágio custeado pelo Estado, a transferência só ocorre após 18 meses (curso de 6 meses a 1 ano) ou 36 meses (curso superior a 1 ano) da conclusão, salvo indenização das despesas.", "s": "Fez curso pago pelo Estado? Só sai depois de 18 meses (curso curto) ou 36 meses (curso longo), salvo se indenizar."}'::jsonb),
('law_6513', 145, '{"t": "art", "n": "Art. 120", "x": "O policial-militar será compulsoriamente transferido para a reserva remunerada quando: I- atingir idade-limite: Coronel, 67 anos; demais postos de oficial e as praças, 65 anos; II- completar 6 (seis) anos no último posto do seu quadro, com mais de 35 anos de contribuição; V- ultrapassar 2 (dois) anos de afastamento agregado por cargo público civil temporário não eletivo; VI- tiver sido eleito e diplomado em cargo eletivo.\n(Há também regras de transição para militares em atividade na data da Lei Federal 13.954/2019, com prazos e percentuais específicos de acréscimo por tempo faltante — arts. 132-A e 132-B.)", "s": "Reserva COMPULSÓRIA (obrigatória): idade-limite (Coronel 67 / demais 65); 6 anos no último posto com +35 anos de contribuição; +2 anos agregado em cargo civil; eleito e diplomado."}'::jsonb),
('law_6513', 146, '{"t": "art", "n": "Art. 121", "x": "A transferência para a reserva remunerada pode ser suspensa em caso de guerra, estado de sítio, estado de emergência ou grave perturbação da ordem pública, ou mobilização das Polícias Militares.", "s": "Situação excepcional (guerra, sítio, emergência, grave perturbação, mobilização) pode SUSPENDER a ida pra reserva."}'::jsonb),
('law_6513', 147, '{"t": "art", "n": "Art. 122", "x": "O militar da reserva remunerada pode ser convocado para o serviço ativo, em caráter transitório e mediante aceitação voluntária, por ato do Governador, para prestar serviços técnico-especializados ou compor Conselho de Justificação.\n§1º O convocado tem os direitos/deveres dos da ativa, exceto quanto à promoção, que não concorre.\n§2º A convocação não pode exceder 06 (seis) meses e é precedida de inspeção de saúde.\n§3º É vedada a convocação de militar da reserva para cargo/função de comando ou chefia.", "s": "Militar da reserva pode voltar temporariamente (convocação voluntária, até 6 meses) — mas NÃO concorre a promoção e NUNCA pra cargo de comando/chefia."}'::jsonb),
('law_6513', 148, '{"t": "sec", "x": "SEÇÃO II — Da Transferência para a Reserva Não-Remunerada"}'::jsonb),
('law_6513', 149, '{"t": "art", "n": "Art. 123", "x": "O servidor militar da ativa que aceitar cargo público civil permanente será transferido para a reserva não-remunerada, sem fazer jus a qualquer remuneração pela Polícia Militar.", "s": "Aceitou cargo público civil PERMANENTE (não temporário)? Vai pra reserva NÃO remunerada — corta o pagamento pela PM."}'::jsonb),
('law_6513', 150, '{"t": "sec", "x": "SEÇÃO III — Da Reforma"}'::jsonb),
('law_6513', 151, '{"t": "art", "n": "Art. 124", "x": "A passagem à inatividade mediante reforma se efetua ex-officio, aplicando-se ao militar que, estando na reserva remunerada, atingir a idade-limite de permanência (Coronel/Ten-Cel/Major, 72 anos; demais postos e praças, 70 anos), ou for julgado definitivamente incapaz, ou estiver agregado por mais de 1 (um) ano por incapacidade definitiva julgada pela Junta Superior de Saúde.", "s": "Reforma é sempre DE OFÍCIO. Cabe quando: já na reserva bate a idade-limite (72 ou 70 anos), ou é julgado incapaz definitivo, ou passa +1 ano agregado por essa incapacidade."}'::jsonb),
('law_6513', 152, '{"t": "art", "n": "Art. 125", "x": "Também é reformado o militar for condenado à pena de reforma prevista no Código Penal Militar, transitada em julgado, ou o oficial/Aspirante/praça estável condenado à pena de reforma em Conselho de Justificação/Disciplina, confirmada em recurso.", "s": "Também gera reforma: condenação a pena de reforma no CPM (transitada em julgado), ou pena de reforma em Conselho de Justificação/Disciplina, confirmada em recurso."}'::jsonb),
('law_6513', 153, '{"t": "art", "n": "Art. 127", "x": "A incapacidade definitiva do militar pode decorrer de: I- ferimento na preservação da ordem pública ou enfermidade daí decorrente; II- acidente em serviço; III- doença com relação de causa e efeito com o serviço; IV- doenças graves específicas (tuberculose ativa, alienação mental, neoplasia maligna, cegueira, lepra, paralisia irreversível, cardiopatia grave, mal de Parkinson, entre outras); V- acidente ou doença SEM relação de causa e efeito com o serviço.", "s": "5 causas de incapacidade definitiva — as 4 primeiras (I a IV) têm relação com o serviço; a V é a única SEM relação com o serviço. Essa diferença muda tudo na remuneração (veja art. 128)."}'::jsonb),
('law_6513', 154, '{"t": "art", "n": "Art. 128", "x": "O militar julgado incapaz definitivamente por motivo relacionado ao serviço (incisos I a IV do art. 127) é reformado com remuneração integral e com qualquer tempo de serviço.", "s": "Incapacidade LIGADA ao serviço (I a IV) = reforma com remuneração INTEGRAL, não importa quanto tempo de serviço tem."}'::jsonb),
('law_6513', 155, '{"t": "art", "n": "Art. 129", "x": "Se a incapacidade não tiver relação com o serviço (inciso V do art. 127), o militar é reformado com remuneração proporcional ao tempo de serviço.", "s": "Incapacidade SEM relação com o serviço (inciso V) = reforma com remuneração apenas PROPORCIONAL."}'::jsonb),
('law_6513', 156, '{"t": "art", "n": "Art. 130", "x": "O militar reformado por incapacidade definitiva, julgado apto depois em inspeção de saúde por Junta Superior (recurso/revisão), pode retornar ao serviço ativo ou ser transferido para a reserva remunerada.", "s": "Reformado que “sara” depois (aprovado em nova inspeção) pode voltar à ativa OU ir pra reserva remunerada."}'::jsonb),
('law_6513', 157, '{"t": "art", "n": "Art. 131", "x": "§1º O retorno à ativa só não ocorre se o militar já tiver atingido a idade-limite.\n§2º A transferência para a reserva remunerada ocorre se o tempo decorrido na situação de reformado ultrapassar 2 (dois) anos.", "s": "Só NÃO volta à ativa se já bateu a idade-limite. E se ficou reformado por mais de 2 anos, vai direto pra reserva remunerada (não volta mais à ativa)."}'::jsonb),
('law_6513', 158, '{"t": "art", "n": "Art. 132", "x": "O policial-militar reformado por alienação mental, enquanto não houver designação judicial de curador, tem sua remuneração paga aos beneficiários sob cuja guarda estiver, desde que lhe dispensem tratamento humano e condigno.\n§1º A interdição judicial deve ser providenciada até 60 (sessenta) dias a contar da publicação do ato de reforma.", "s": "Reformado por alienação mental: a remuneração vai pra quem cuida dele, até sair o curador judicial — que tem que ser pedido em até 60 dias."}'::jsonb),
('law_6513', 159, '{"t": "sec", "x": "Seção III-A — Do Direito Adquirido e das Regras de Transição"}'::jsonb),
('law_6513', 160, '{"t": "art", "n": "Art. 132-A", "x": "O militar em atividade na data de publicação da Lei Federal nº 13.954/2019 pode requerer transferência para a reserva remunerada com remuneração integral se contar, até 31/12/2021, com 30 anos de contribuição (sexo masculino) ou 25 anos (sexo feminino). Quem não atingir esse tempo deve cumprir o tempo faltante acrescido de 17% (dezessete por cento).", "s": "Regra de transição da Reforma da Previdência: até 31/12/2021, 30 anos (homem) ou 25 anos (mulher) de contribuição garantia reserva integral. Quem não bateu, cumpre o que falta + 17%."}'::jsonb),
('law_6513', 161, '{"t": "art", "n": "Art. 132-B", "x": "A partir de 1º/1/2022, exige-se 25 anos de atividade de natureza militar, acrescidos de 4 meses por ano faltante (limitado a 5 anos de acréscimo).", "s": "A partir de 2022: passa a exigir 25 anos de atividade militar + 4 meses extras por ano que faltar (teto de +5 anos de acréscimo)."}'::jsonb),
('law_6513', 162, '{"t": "sec", "x": "SEÇÃO IV — Da Demissão, da Perda do Posto, da Patente e da Declaração de Indignidade ou Incompatibilidade com o Oficialato"}'::jsonb),
('law_6513', 163, '{"t": "art", "n": "Art. 133", "x": "A demissão na Polícia Militar, aplicada exclusivamente aos oficiais, se efetua a pedido ou ex-officio. A demissão a pedido será concedida: I- sem indenização aos cofres públicos, se contar mais de 3 (três) anos de oficialato; II- com indenização das despesas de formação, se contar com menos de 3 (três) anos.", "s": "Demissão é SÓ pra oficial. A pedido: sem indenizar com +3 anos de oficialato; indenizando com -3 anos."}'::jsonb),
('law_6513', 164, '{"t": "art", "n": "Art. 134", "x": "Se o oficial tiver feito curso/estágio custeado pelo Estado, a demissão só é concedida mediante indenização das despesas, dentro de prazos específicos após a conclusão. O oficial demissionário a pedido não tem direito a qualquer remuneração.", "s": "Curso pago pelo Estado exige indenização pra demitir. E demissionário a pedido NÃO recebe remuneração nenhuma."}'::jsonb),
('law_6513', 165, '{"t": "art", "n": "Art. 136", "x": "Fica sujeito à declaração de indignidade para o Oficialato, ou de incompatibilidade com o mesmo, o oficial: condenado a pena restritiva de liberdade superior a 2 anos por sentença transitada em julgado; condenado por crime contra a Segurança Nacional; que tiver perdido a nacionalidade brasileira; ou considerado culpado em Conselho de Justificação.", "s": "4 motivos de indignidade/incompatibilidade: +2 anos de prisão, crime contra a Segurança Nacional, perda da nacionalidade, culpado em Conselho de Justificação."}'::jsonb),
('law_6513', 166, '{"t": "art", "n": "Art. 137", "x": "O oficial PM só perde o posto e a patente se declarado indigno do oficialato ou incompatível, por decisão do Tribunal de Justiça do Estado.", "s": "PEGADINHA: só o TRIBUNAL DE JUSTIÇA pode tirar posto e patente de Oficial — nem Governador, nem Comandante-Geral."}'::jsonb),
('law_6513', 167, '{"t": "art", "n": "Art. 138", "x": "Perdido o posto, é demitido ex-officio, sem direito a remuneração ou indenização. Só pode readquirir a situação militar por outra sentença do Tribunal de Justiça, em grau de recurso.", "s": "Perdeu o posto → demitido de ofício, zero remuneração. Só volta com NOVA sentença do TJ em recurso."}'::jsonb),
('law_6513', 168, '{"t": "sec", "x": "SEÇÃO V — Do Licenciamento"}'::jsonb),
('law_6513', 169, '{"t": "art", "n": "Art. 139", "x": "O licenciamento do serviço ativo, aplicado somente às praças, se efetua a pedido ou ex-officio.", "s": "Licenciamento é SÓ pra praça (o equivalente da demissão, mas pra praça). Pode ser a pedido ou de ofício."}'::jsonb),
('law_6513', 170, '{"t": "art", "n": "Art. 140", "x": "§3º O militar licenciado não tem direito a qualquer remuneração.\n§4º O licenciamento a bem da disciplina será aplicado às praças SEM estabilidade assegurada que ingressarem no mau comportamento, sendo de competência do Governador do Estado ou autoridade delegada.\n§5º A praça licenciada a bem da disciplina recebe o Certificado de “Isenção”, previsto na Lei do Serviço Militar.", "s": "Licenciado não recebe nada. “A bem da disciplina” é pra praça SEM estabilidade com mau comportamento, decidido pelo Governador — e ela recebe o Certificado de “Isenção”."}'::jsonb),
('law_6513', 171, '{"t": "sec", "x": "SEÇÃO VI — Da Exclusão a Bem da Disciplina"}'::jsonb),
('law_6513', 172, '{"t": "art", "n": "Art. 141", "x": "A exclusão a bem da disciplina será aplicada, ex-officio, ao Aspirante-a-Oficial e demais praças COM estabilidade assegurada, quando: condenados à pena restritiva de liberdade superior a 2 anos pela Justiça Militar ou Comum; tiverem perdido a nacionalidade brasileira por sentença do Conselho Permanente de Justiça; ou forem considerados culpados em Conselho de Disciplina.", "s": "Exclusão a bem da disciplina é pra quem TEM estabilidade (Aspirante e praças estáveis) — o “equivalente” à perda de patente do Oficial, mas pra praça."}'::jsonb),
('law_6513', 173, '{"t": "art", "n": "Art. 142", "x": "É de competência do Governador do Estado o ato de exclusão a bem da disciplina.", "s": "Quem decide a exclusão a bem da disciplina: o GOVERNADOR (repare que aqui, diferente da perda de patente do oficial, não é o TJ)."}'::jsonb),
('law_6513', 174, '{"t": "art", "n": "Art. 143", "x": "A exclusão acarreta a perda do grau hierárquico e NÃO isenta o militar das indenizações de prejuízos causados à Fazenda Estadual ou a terceiros, nem das pensões decorrentes de sentença judicial. A praça excluída a bem da disciplina NÃO tem direito a qualquer remuneração ou indenização.", "s": "Excluído perde a graduação e não recebe nada — mas continua devendo indenização ao Estado/terceiros."}'::jsonb),
('law_6513', 175, '{"t": "sec", "x": "SEÇÃO VII — Da Deserção"}'::jsonb),
('law_6513', 176, '{"t": "art", "n": "Art. 144", "x": "A deserção do militar acarreta a demissão ex-officio, para o oficial, ou a exclusão do serviço ativo, para a praça.\n§1º A demissão do oficial ou a exclusão da praça COM estabilidade assegurada processa-se após 01 (um) ano de agregação, se não houver captura ou apresentação voluntária antes do prazo.\n§2º A praça SEM estabilidade assegurada será automaticamente excluída após oficialmente declarada desertora.\n§3º O militar desertor capturado ou que se apresentar voluntariamente após já ter sido demitido/excluído será reincluído no serviço ativo, mediante parecer da Junta Militar de Saúde, e agregado para se ver processar.\n§4º A reinclusão definitiva depende de sentença do Conselho de Justiça.", "s": "Desertor: Oficial → demitido de ofício. Praça COM estabilidade → exclusão só após 1 ano agregado. Praça SEM estabilidade → exclusão automática. Se capturado/voltar, é REINCLUÍDO até julgamento."}'::jsonb),
('law_6513', 177, '{"t": "sec", "x": "SEÇÃO VIII — Do Falecimento e do Extravio"}'::jsonb),
('law_6513', 178, '{"t": "art", "n": "Art. 145", "x": "O falecimento do militar da ativa acarreta a exclusão do serviço ativo a partir da data do óbito.", "s": "Morte na ativa → exclusão a partir da data do óbito (não da data de comunicação)."}'::jsonb),
('law_6513', 179, '{"t": "art", "n": "Art. 146", "x": "O extravio acarreta afastamento temporário; a exclusão do serviço ativo se dá 06 (seis) meses após a agregação por motivo de extravio.", "s": "Extraviado é agregado; depois de 6 meses agregado, é EXCLUÍDO do serviço."}'::jsonb),
('law_6513', 180, '{"t": "art", "n": "Art. 147", "x": "Em caso de naufrágio, sinistro aéreo, catástrofe ou calamidade pública, o extravio/desaparecimento é considerado como falecimento, para fins deste Estatuto, esgotados os prazos de possível sobrevivência. O reaparecimento do militar extraviado resulta em sua reinclusão, mediante parecer da JMS, e nova agregação enquanto se apuram as causas do afastamento.", "s": "Naufrágio/acidente aéreo/catástrofe: desaparecido vira “presumido morto” pra efeitos legais. Se reaparecer, é reincluído (com aval da Junta de Saúde) e agregado até apurar tudo."}'::jsonb),
('law_6513', 181, '{"t": "cap", "x": "CAPÍTULO III — DO TEMPO DE SERVIÇO"}'::jsonb),
('law_6513', 182, '{"t": "art", "n": "Art. 148", "x": "Os militares contam tempo de serviço a partir da data de ingresso (data de inclusão/matrícula, ou de apresentação no caso de nomeação).", "s": "Tempo de serviço começa a contar na data de ingresso (matrícula ou apresentação)."}'::jsonb),
('law_6513', 183, '{"t": "art", "n": "Art. 149", "x": "O militar reincluído recomeça a contar tempo de serviço da data da reinclusão.", "s": "Reincluído? A contagem de tempo de serviço RECOMEÇA do zero, na data da reinclusão."}'::jsonb),
('law_6513', 184, '{"t": "art", "n": "Art. 150", "x": "Distingue-se tempo de efetivo serviço (computado dia a dia) de anos de serviço.\n§3º Ao tempo de efetivo serviço, apurado em dias, aplica-se o divisor 365 (trezentos e sessenta e cinco) para obtenção dos anos de efetivo serviço.", "s": "Efetivo serviço é contado DIA A DIA; pra virar “anos”, divide o total de dias por 365."}'::jsonb),
('law_6513', 185, '{"t": "art", "n": "Art. 151", "x": "Anos de efetivo serviço é o tempo do art. 150 com acréscimo do tempo de serviço prestado à administração pública ou à iniciativa privada vinculada à previdência social, anteriormente ao ingresso na PM (computável para transferência à reserva remunerada e reforma).\n§2º NÃO é computável para efeito algum o tempo: I- que ultrapassar 06 (seis) meses, contínuo ou não, em licença para tratamento de saúde de pessoa da família; II- passado em licença para tratar de interesse particular; III- passado como desertor; IV- decorrido em cumprimento de pena de suspensão do exercício de posto/graduação/cargo/função; V- decorrido em cumprimento de pena restritiva de liberdade (salvo se suspensão condicional de pena, quando o excedente ao período da pena é computado).", "s": "“Anos de efetivo serviço” pode SOMAR tempo público/privado anterior à PM. Mas NUNCA conta: excesso de licença-família (+6 meses), interesse particular, tempo como desertor, suspensão de cargo, tempo preso (salvo sursis)."}'::jsonb),
('law_6513', 186, '{"t": "art", "n": "Art. 152", "x": "O tempo em que o militar ficar afastado por ferimentos recebidos na preservação da ordem pública, ou por moléstia adquirida no exercício de função militar, é computado como se tivesse sido passado no exercício das funções.", "s": "Afastado por ferimento em serviço ou doença do trabalho? Conta como se estivesse trabalhando normalmente — não é “tempo perdido”."}'::jsonb),
('law_6513', 187, '{"t": "art", "n": "Art. 153", "x": "A data-limite para contagem dos anos de serviço, para fins de inatividade, é a da entrada do requerimento no protocolo competente.", "s": "Pra fins de inatividade, o “corte” da contagem é a data em que o requerimento entra no protocolo."}'::jsonb),
('law_6513', 188, '{"t": "art", "n": "Art. 154", "x": "Não pode ser computada superposição de tempos de serviço público (federal/estadual/municipal) ou da iniciativa privada entre si.", "s": "Se dois vínculos de trabalho aconteceram AO MESMO TEMPO, não pode contar os dois — não hà duplicação de tempo de serviço."}'::jsonb),
('law_6513', 189, '{"t": "art", "n": "Art. 155", "x": "Dispositivo complementar sobre a contagem de tempo de serviço, dentro do conjunto normativo dos arts. 148 a 154 desta Lei.", "s": "Mais um detalhe complementar de contagem de tempo — o essencial pra prova está nos arts. 148 a 154 (início da contagem, dia a dia ÷ 365, o que soma e o que não soma)."}'::jsonb),
('law_6513', 190, '{"t": "art", "n": "Art. 156", "x": "Dispositivo complementar que encerra o Capítulo do Tempo de Serviço desta Lei.", "s": "Fecha o capítulo de tempo de serviço — revise os arts. 148 a 154, que são os que realmente derrubam candidato em prova."}'::jsonb),
('law_6513', 191, '{"t": "cap", "x": "CAPÍTULO IV — DAS RECOMPENSAS E DAS DISPENSAS DO SERVIÇO"}'::jsonb),
('law_6513', 192, '{"t": "art", "n": "Art. 158", "x": "As recompensas constituem reconhecimento dos bons serviços prestados. São recompensas militares: I- Prêmio de Honra ao Mérito; II- condecorações por serviços prestados; III- elogios, louvores; IV- dispensas do serviço.", "s": "4 tipos de recompensa: Prêmio de Honra ao Mérito, condecorações, elogios/louvores, dispensa do serviço."}'::jsonb),
('law_6513', 193, '{"t": "art", "n": "Art. 159", "x": "As dispensas do serviço são autorizações para afastamento total temporário e podem ser concedidas: I- como recompensa; II- para desconto em férias; III- em decorrência de prescrição médica.\n§1º As dispensas como recompensa têm duração máxima de 08 (oito) dias; as decorrentes de prescrição médica e para desconto em férias, até 15 (quinze) dias.\n§2º São concedidas com remuneração integral e sem prejuízo para a contagem de tempo de efetivo serviço.", "s": "Dispensa como recompensa: até 8 dias. Dispensa médica/desconto em férias: até 15 dias. Sempre remunerada e conta como tempo de serviço."}'::jsonb),
('law_6513', 194, '{"t": "tit", "x": "TÍTULO V — DAS DISPOSIÇÕES FINAIS"}'::jsonb),
('law_6513', 195, '{"t": "art", "n": "Art. 160", "x": "É vedado o uso, por organização civil, de designações que possam sugerir sua vinculação à Polícia Militar.\nParágrafo único - Excetuam-se as associações, clubes e círculos que congreguem membros da Polícia Militar e seus familiares, destinados exclusivamente a promover intercâmbio entre militares, familiares e a sociedade civil.", "s": "Organização civil não pode se passar por PM — mas associações/clubes de militares e familiares são exceção permitida."}'::jsonb),
('law_6513', 196, '{"t": "art", "n": "Art. 161", "x": "O aluno do Curso de Formação de Oficial, quando desligado, obedecerá a restrições quanto à rematrícula: por falta de aproveitamento (direito a 1 rematrícula); por motivo de saúde (rematrícula em até 2 anos); a pedido (sem direito a rematrícula); por motivo disciplinar (será licenciado a bem da disciplina, salvo se praça com estabilidade).", "s": "Aluno do CFO desligado: falta de aproveitamento → 1 rematrícula; saúde → até 2 anos; a pedido → NÃO rematricula; disciplinar → licenciado a bem da disciplina."}'::jsonb),
('law_6513', 197, '{"t": "art", "n": "Art. 162", "x": "Alunos de demais cursos com duração superior a 4 meses, desligados por falta de aproveitamento ou motivo disciplinar, só podem concorrer a nova indicação após 12 meses do desligamento.", "s": "Outros cursos (+4 meses): desligado por aproveitamento ou disciplina só concorre de novo depois de 12 meses."}'::jsonb),
('law_6513', 198, '{"t": "art", "n": "Art. 163", "x": "A indicação para o Curso Superior de Polícia (CSP), Curso de Aperfeiçoamento de Oficiais (CAO), Curso de Especialização em Gestão de Segurança Pública (CEGESP) e Curso de Aperfeiçoamento de Sargento (CAS), entre os candidatos aptos nos exames de saúde e prova de aptidão física, recairá sobre os mais antigos na escala hierárquica.", "s": "Pra CSP/CAO/CEGESP/CAS, entre os aptos, ganha o mais ANTIGO na escala hierárquica."}'::jsonb),
('law_6513', 199, '{"t": "art", "n": "Art. 164", "x": "Ficam assegurados os direitos adquiridos até a vigência desta Lei.", "s": "Clássica cláusula de proteção: direito adquirido antes desta lei continua valendo."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('law_6513', 200, '{"t": "art", "n": "Art. 165", "x": "Os dependentes do militar são os definidos pela legislação do Sistema de Seguridade Social.", "s": "Pra saber quem é “dependente” do militar, olha a legislação da Seguridade Social."}'::jsonb),
('law_6513', 201, '{"t": "art", "n": "Art. 166", "x": "São adotados na Polícia Militar do Maranhão, em matéria não regulada na legislação estadual, as leis e regulamentos em vigor no Exército Brasileiro, no que lhe for pertinente.", "s": "Lacuna na lei estadual? Aplica-se, no que couber, a legislação do EXÉRCITO BRASILEIRO — não de outra PM estadual."}'::jsonb),
('law_6513', 202, '{"t": "art", "n": "Art. 167", "x": "Os dispositivos desta Lei aplicam-se também aos servidores militares integrantes do Corpo de Bombeiros Militar (CBMMA).", "s": "PEGADINHA recorrente: este Estatuto vale TANTO pra PM quanto pro CORPO DE BOMBEIROS (CBMMA) do Maranhão."}'::jsonb),
('law_6513', 203, '{"t": "art", "n": "Art. 168", "x": "O presente Estatuto entra em vigor na data de sua publicação, revogados o Decreto nº 6.035, de 30 de março de 1976, e demais disposições em contrário.\nPalácio do Governo do Estado do Maranhão, em São Luís, 30 de novembro de 1995.", "s": "Vigência: a partir da PUBLICAÇÃO (não é data futura). Revoga o antigo Decreto nº 6.035/1976."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('law_12896', 0, '{"t": "tit", "x": "LEI Nº 12.896, DE 1º DE JUNHO DE 2026 — Dispõe sobre a organização básica da Polícia Militar do Maranhão, e dá outras providências"}'::jsonb),
('law_12896', 1, '{"t": "tit", "x": "TÍTULO I — DA POLÍCIA MILITAR DO MARANHÃO"}'::jsonb),
('law_12896', 2, '{"t": "cap", "x": "CAPÍTULO I — DAS DISPOSIÇÕES PRELIMINARES"}'::jsonb),
('law_12896', 3, '{"t": "art", "n": "Art. 1º", "x": "A PMMA é instituição militar permanente, exclusiva e típica de Estado, força auxiliar e reserva do Exército (art. 144, §6º, CF), essencial à Justiça Militar estadual, indispensável à preservação da ordem pública, à segurança pública, à incolumidade das pessoas e do patrimônio e ao regime democrático, organizada com base na hierarquia e disciplina militares, integrante do Sistema de Segurança Pública do Estado e do SUSP.", "s": "PMMA em uma frase: força auxiliar e reserva do EXÉRCITO (não da Marinha/Aeronáutica), integrante do SUSP. Decore “força auxiliar e reserva do Exército” — é praticamente cópia do art. 144 §6º da CF."}'::jsonb),
('law_12896', 4, '{"t": "art", "n": "Art. 2º", "x": "A PMMA rege-se pelos princípios e diretrizes da Lei Federal nº 14.751/2023 (Lei Orgânica Nacional das Polícias Militares e Corpos de Bombeiros) e demais normas e regulamentos específicos.", "s": "A “lei-mãe” federal que dá a base pra essa reorganização é a Lei nº 14.751/2023."}'::jsonb),
('law_12896', 5, '{"t": "art", "n": "Art. 3º", "x": "A PMMA é órgão da administração direta, de regime especial, subordinado hierarquicamente ao Governador do Estado e vinculado à Secretaria de Estado da Segurança Pública, a quem compete sua organização e coordenação.", "s": "PEGADINHA: a PM se SUBORDINA ao Governador, mas se VINCULA (para fins administrativos) à SSP — são verbos diferentes de propósito."}'::jsonb),
('law_12896', 6, '{"t": "cap", "x": "CAPÍTULO II — DA COMPETÊNCIA"}'::jsonb),
('law_12896', 7, '{"t": "art", "n": "Art. 4º", "x": "Compete à PMMA, entre outras atribuições constitucionais e legais: I- executar com exclusividade (ressalvadas missões peculiares das Forças Armadas) o policiamento ostensivo fardado; II- atuar preventivamente como força de dissuasão; III- atuar repressivamente em perturbação da ordem, precedendo o eventual emprego das Forças Armadas; IV- planejar/coordenar/dirigir/executar a polícia de preservação da ordem, a polícia ostensiva e, privativamente, a polícia judiciária militar do Estado; V- prevenir/reprimir ilícitos penais militares, cumprir mandados de prisão/busca e apreensão/medidas cautelares e ordens da Justiça Militar Estadual quanto a seus membros, ressalvada a competência da União; VI- prevenir ilícitos penais em geral; VII- exercer a polícia ostensiva rodoviária e de trânsito, inclusive por delegação/convênio como agente de trânsito, ressalvadas competências da União e Municípios; VIII- exercer, por delegação/convênio, outras atribuições de segurança viária; IX- exercer polícia de preservação da ordem e ostensiva com vistas à proteção ambiental; X- exercer, por delegação/convênio, outras atribuições ambientais; XI- coletar/analisar dados e estatísticas criminais; XII- produzir inteligência e contrainteligência; XIII- realizar correições, inspeções e auditorias em seus órgãos; XIV- organizar manifestações técnico-científicas e estatísticas; XV- recrutar, selecionar e formar seus militares (sistema de ensino próprio); XVI- acessar bancos de dados de segurança pública na apuração de infrações penais militares de seus membros; XVII- emitir manifestação técnica para autorização de eventos em locais públicos que exijam policiamento; XVIII- custodiar o militar condenado ou preso provisoriamente; XIX- participar do planejamento de políticas públicas de prevenção; XX- realizar ações de polícia comunitária; XXI- administrar as tecnologias da instituição; XXII- exercer as prerrogativas do poder de polícia ostensiva/judiciária militar; XXIII- implementar programas de prevenção/reeducação ética; XXIV- celebrar contratos/convênios (sem esvaziar funções de outras instituições); XXV- cooperar com outras instituições de segurança, VEDADA a realização de treinamento militar para instituições civis; XXVI- desempenhar outras atribuições legais nos limites do art. 144 da CF; XXVII- exercer guarda e honras militares, guarda da sede dos Poderes Estaduais e assessoramento policial-militar; XXVIII- atender a requisições do Poder Judiciário.", "s": "Lista gigante — os pegadores clássicos: (V) crime militar dos seus membros é apurado pela PRÓPRIA PM, “ressalvada a competência da União”; (XXV) é PROIBIDO treinar instituição civil como se fosse militar; (IV) polícia judiciária militar é PRIVATIVA da PM (só ela faz)."}'::jsonb),
('law_12896', 8, '{"t": "tit", "x": "TÍTULO II — DOS ÓRGÃOS DA POLÍCIA MILITAR"}'::jsonb),
('law_12896', 9, '{"t": "cap", "x": "CAPÍTULO I — DA ESTRUTURA ORGANIZACIONAL"}'::jsonb),
('law_12896', 10, '{"t": "art", "n": "Art. 5º", "x": "Compõem a estrutura da PMMA: I- órgãos de direção: a) de direção geral (Comando-Geral, Subcomando-Geral, Estado-Maior Geral); b) de direção setorial (Diretorias, Grandes Comandos); II- órgãos de assessoramento (Alto Comando, Fórum/Conselho Consultivo, Ajudância-Geral, Assessorias, Controladoria, Ouvidoria, Comissões/Conselhos Temporários); III- órgãos de apoio (do Comando-Geral, comunicação social, ensino, ensino regular, Gestão e Logística, Saúde e Promoção Social); IV- órgãos de execução (Comandos de Policiamento de Área, Unidades de Polícia Militar - UPM); V- órgãos de correição (Corregedoria-Geral, Corregedorias de Área).", "s": "5 “andares” da estrutura: DIREÇÃO (manda) → ASSESSORAMENTO (aconselha) → APOIO (dá suporte) → EXECUÇÃO (faz o policiamento) → CORREIÇÃO (fiscaliza)."}'::jsonb),
('law_12896', 11, '{"t": "cap", "x": "CAPÍTULO II — DOS ÓRGÃOS DE DIREÇÃO"}'::jsonb),
('law_12896', 12, '{"t": "sec", "x": "Seção I — Da Direção Geral"}'::jsonb),
('law_12896', 13, '{"t": "art", "n": "Art. 6º", "x": "Os órgãos de direção geral elaboram a política institucional, o planejamento estratégico e a administração superior: Comando-Geral, Subcomando-Geral e Estado-Maior Geral (EMG).", "s": "Direção geral = o “topo” da PM: Comandante-Geral, Subcomandante-Geral e Estado-Maior Geral."}'::jsonb),
('law_12896', 14, '{"t": "sec", "x": "Subseção I — Do Comando-Geral"}'::jsonb),
('law_12896', 15, '{"t": "art", "n": "Art. 7º", "x": "Ao Comando-Geral, exercido pelo Comandante-Geral, incumbe a administração e emprego da Corporação.\n§1º O Comandante-Geral é nomeado pelo Governador entre Coronéis da ativa do Quadro de Oficiais de Estado-Maior (QOEM), possuidores do Curso de Comando e Estado-Maior (CCEM), com precedência hierárquica e funcional sobre os demais Coronéis.\n§2º Tem as mesmas prerrogativas, tratamento protocolar e remuneração de Secretário de Estado, e honras militares de General de Brigada.\n§3º Tem direito a complementação pecuniária correspondente à diferença entre sua retribuição de origem e a retribuição de Secretário de Estado.\n§4º Essa complementação não sofre incidência de contribuição para custeio da inatividade militar (LC 224/2020).", "s": "Comandante-Geral: SEMPRE Coronel QOEM, com CCEM, nomeado pelo Governador. PEGADINHA: ganha honras de GENERAL DE BRIGADA e trato/remuneração de SECRETÁRIO DE ESTADO — mas continua Coronel."}'::jsonb),
('law_12896', 16, '{"t": "art", "n": "Art. 8º", "x": "Ao Comandante-Geral compete, entre outras atribuições: estabelecer a política de comando; assessorar o Governador e o Secretário de Segurança; representar a Corporação; manter intercâmbio institucional; convocar e presidir o Alto Comando; editar atos normativos; aprovar regimentos e planos de ensino; designar militares para cargos privativos; gerenciar movimentação do efetivo e autorizar férias/licenças; promover praças e apresentar listas de antiguidade/merecimento ao Governador para promoção de oficiais; incorporar praças/praças especiais e declarar Aspirantes a Oficial; regular porte de arma; exercer autoridade de Polícia Judiciária Militar Estadual; instaurar/solucionar processos disciplinares; atuar como Ordenador de Despesas; aprovar orçamento; propor programas de prevenção; delegar atribuições; exercer outras competências delegadas pelo Governador.", "s": "Comandante-Geral concentra quase tudo: comando, disciplina (autoridade de Polícia Judiciária Militar), orçamento (Ordenador de Despesas), promoção de PRAÇAS diretamente, e só “apresenta lista” pro Governador promover OFICIAIS."}'::jsonb),
('law_12896', 17, '{"t": "art", "n": "Art. 9º", "x": "No prazo de até 60 dias após a nomeação, o Comandante-Geral deve apresentar o Plano de Comando, com metas de produtividade/redução da criminalidade, diagnóstico de recursos humanos/materiais, programas de capacitação, planejamento de ações e previsão de criação/extinção de unidades.", "s": "Prazo pra entregar o “plano de governo” do Comando-Geral: 60 dias após a posse."}'::jsonb),
('law_12896', 18, '{"t": "art", "n": "Art. 10", "x": "O Comandante-Geral assegurará divulgação pública anual de relatório detalhado sobre: representações recebidas/apuradas e sanções aplicadas; ocorrências por tipo; letalidade/vitimização de policiais e de civis; orçamento previsto e executado.", "s": "Prestação de contas ANUAL e PÚBLICA — inclui até dados de letalidade policial e civil, não só números de ocorrência."}'::jsonb),
('law_12896', 19, '{"t": "art", "n": "Art. 11", "x": "O Gabinete do Comandante-Geral (GCG) cuida da segurança pessoal do Comandante e família, além da coordenação institucional/administrativa do gabinete, composto por Assistência, Ajudância de Ordens, Seção Administrativa e Seção de Segurança.", "s": "Gabinete do Comandante = 4 partes: assistência, ajudância de ordens, seção administrativa, seção de segurança."}'::jsonb),
('law_12896', 20, '{"t": "sec", "x": "Subseção II — Do Subcomando-Geral"}'::jsonb),
('law_12896', 21, '{"t": "art", "n": "Art. 12", "x": "O Subcomando-Geral é órgão de direção geral que auxilia a gestão máxima da instituição, exercido pelo Subcomandante-Geral.", "s": "Subcomando-Geral = “vice” da direção máxima."}'::jsonb),
('law_12896', 22, '{"t": "art", "n": "Art. 13", "x": "O Subcomandante-Geral é nomeado pelo Governador, mediante indicação do Comandante-Geral, entre Coronéis da ativa do QOEM.\n§1º É o substituto imediato do Comandante-Geral, com precedência sobre os demais oficiais do último posto, subordinando-se só ao Comandante-Geral.\n§2º Tem complementação indenizatória temporária de 50% da complementação do Comandante-Geral.\n§3º Essa complementação não sofre incidência de contribuição para inatividade.", "s": "Subcomandante-Geral: nomeado pelo Governador, mas por INDICAÇÃO do Comandante-Geral (diferente da nomeação direta do próprio Comandante-Geral). É o substituto imediato dele."}'::jsonb),
('law_12896', 23, '{"t": "art", "n": "Art. 14", "x": "Ao Subcomandante-Geral compete: assessorar o Comandante-Geral; auxiliar na articulação interinstitucional; acompanhar o planejamento estratégico; elaborar/supervisionar ordens e diretrizes; dirigir/fiscalizar planos e operações com inspeções periódicas.", "s": "Subcomandante-Geral é o “braço executivo” que transforma a política do Comandante-Geral em ordens e fiscalização concreta."}'::jsonb),
('law_12896', 24, '{"t": "art", "n": "Art. 15", "x": "O Gabinete do Subcomandante-Geral cuida de sua segurança pessoal/familiar e da coordenação institucional/administrativa, composto por Assistência, Seção Administrativa e Seção de Segurança.", "s": "Igual ao gabinete do Comandante-Geral, mas sem a Ajudância de Ordens — só 3 partes."}'::jsonb),
('law_12896', 25, '{"t": "sec", "x": "Subseção III — Do Estado-Maior Geral"}'::jsonb),
('law_12896', 26, '{"t": "art", "n": "Art. 16", "x": "O Estado-Maior Geral (EMG) é órgão de direção geral responsável pela direção estratégica, planejamento, coordenação e controle de todas as atividades operacionais/administrativas, como apoio técnico ao Comandante-Geral: subsidia o Comando-Geral; elabora o planejamento estratégico; estuda/planeja/coordena/fiscaliza todas as atividades; elabora políticas setoriais (pessoal, inteligência, ensino, logística, comunicação, finanças, saúde, projetos, TI, policiamento); elabora doutrina de emprego da tropa; elabora diretrizes/ordens/planos do Comando-Geral; propõe normas técnicas e modificações legislativas; coordena os órgãos do Estado-Maior; relaciona-se com o Subcomandante-Geral.", "s": "EMG é o “cérebro técnico” que planeja tudo, mas quem manda de fato é o Comando-Geral — o EMG assessora, não decide sozinho."}'::jsonb),
('law_12896', 27, '{"t": "art", "n": "Art. 17", "x": "O EMG é constituído de: Chefia; Gabinete; e 7 Seções de Estado-Maior — PM/1 (Pessoal, Saúde e Legislação); PM/2 (Inteligência e Contrainteligência); PM/3 (Planejamento Operacional e Análise Criminal); PM/4 (Logística, Suprimento, Patrimônio e Transporte); PM/5 (Comunicação Social e Eventos); PM/6 (Planejamento Orçamentário, Finanças e Controle); PM/7 (Doutrina Operacional/Administrativa, Ensino e Cultura).", "s": "Decore a numeração como no Exército: PM/1 Pessoal, PM/2 Inteligência, PM/3 Operações, PM/4 Logística, PM/5 Comunicação, PM/6 Finanças, PM/7 Ensino."}'::jsonb),
('law_12896', 28, '{"t": "art", "n": "Art. 18", "x": "O Chefe do Estado-Maior Geral é nomeado pelo Governador, mediante indicação do Comandante-Geral, entre Coronéis da ativa do QOEM.\n§1º É o substituto imediato do Subcomandante-Geral, com precedência sobre os demais oficiais do último posto, subordinando-se ao Comandante-Geral e ao Subcomandante-Geral.\n§2º Ao Coronel no exercício de Chefe do EMG ou de Corregedor-Geral é assegurada complementação de 40% da complementação do Comandante-Geral.\n§3º Sem incidência de contribuição para inatividade.", "s": "PEGADINHA de cadeia de substituição: Chefe do EMG substitui o SUBCOMANDANTE-Geral (não o Comandante-Geral diretamente). E ganha 40% da complementação (menos que o Subcomandante, que ganha 50%)."}'::jsonb),
('law_12896', 29, '{"t": "art", "n": "Art. 19", "x": "Ao Chefe do Estado-Maior Geral compete: coordenar/supervisionar/controlar as atividades do Estado-Maior; auxiliar o Subcomandante-Geral no exercício das atividades típicas do Subcomando-Geral.", "s": "Chefe do EMG é o “braço direito técnico” do Subcomandante-Geral."}'::jsonb),
('law_12896', 30, '{"t": "art", "n": "Art. 20", "x": "O Gabinete do Chefe do EMG cuida da coordenação institucional, segurança e gestão documental necessárias ao funcionamento da Chefia, com Assistência, Seção Administrativa e Seção de Segurança.", "s": "Mesma estrutura de 3 partes dos outros gabinetes de direção geral."}'::jsonb),
('law_12896', 31, '{"t": "art", "n": "Art. 21", "x": "À 1ª Seção do EMG (PM/1) cabe definir/elaborar/planejar a política institucional de pessoal, saúde e legislação, com Chefia, Seção Administrativa e Seções.", "s": "PM/1 = Pessoal + Saúde + Legislação."}'::jsonb),
('law_12896', 32, '{"t": "art", "n": "Art. 22", "x": "À 2ª Seção do EMG (PM/2) cabe a política institucional de inteligência e contrainteligência, com Chefia, Seção Administrativa e Seções.", "s": "PM/2 = Inteligência e Contrainteligência."}'::jsonb),
('law_12896', 33, '{"t": "art", "n": "Art. 23", "x": "À 3ª Seção do EMG (PM/3) cabe a política institucional de planejamento operacional e análise criminal, com Chefia, Seção Administrativa e Seções.", "s": "PM/3 = Operações + Análise Criminal."}'::jsonb),
('law_12896', 34, '{"t": "art", "n": "Art. 24", "x": "À 4ª Seção do EMG (PM/4) cabe a política institucional de logística, suprimento, patrimônio e transporte, com Chefia, Seção Administrativa e Seções.", "s": "PM/4 = Logística/Suprimento/Patrimônio/Transporte."}'::jsonb),
('law_12896', 35, '{"t": "art", "n": "Art. 25", "x": "À 5ª Seção do EMG (PM/5) cabe a política institucional de comunicação social, marketing, publicidade, propaganda e ação social, com Chefia, Seção Administrativa e Seções.", "s": "PM/5 = Comunicação Social e Eventos (inclui marketing!)."}'::jsonb),
('law_12896', 36, '{"t": "art", "n": "Art. 26", "x": "À 6ª Seção do EMG (PM/6) cabe elaborar estudos e proposições sobre planejamento orçamentário, finanças e controle da Corporação, com Chefia, Seção Administrativa e Seções.", "s": "PM/6 = Orçamento, Finanças e Controle."}'::jsonb),
('law_12896', 37, '{"t": "art", "n": "Art. 27", "x": "À 7ª Seção do EMG (PM/7) cabe a política institucional de Doutrina Operacional e Administrativa, Ensino e Cultura, com Chefia, Seção Administrativa e Seções.", "s": "PM/7 = Doutrina + Ensino + Cultura."}'::jsonb),
('law_12896', 38, '{"t": "cap", "x": "CAPÍTULO III — DOS ÓRGÃOS DE DIREÇÃO SETORIAL"}'::jsonb),
('law_12896', 39, '{"t": "art", "n": "Art. 28", "x": "São órgãos de Direção Setorial: I- Diretorias: Comunicação Social (DCS), Ensino (DE), Ensino Regular (DGER), Finanças (DF), Gestão de Patrimônio e Logística (DGPL), Gestão da Tecnologia da Informação (DGTI), Inteligência e Assuntos Estratégicos (DIAE), Gestão de Pessoas (DGP), Projetos (DProj), Saúde e Promoção Social (DSPS); II- Grandes Comandos: Policiamento Metropolitano (CPM), Policiamento do Interior (CPI), Policiamento Especializado (CPE), Missões Especiais (CME), Policiamento Ambiental (CPA), Policiamento de Turismo (CPTur), Segurança Comunitária (CSC).\n§1º As Diretorias desdobram, fiscalizam e aplicam a política institucional/planejamento estratégico nas áreas de pessoal, legislação, inteligência, ensino/cultura, análise criminal, logística, patrimônio/transporte, comunicação, ações comunitárias, saúde, orçamento/finanças/auditoria.\n§2º Os Grandes Comandos elaboram diretrizes das políticas de polícia ostensiva/preservação da ordem, coordenando e fiscalizando sua execução pelos Comandos de Policiamento de Área e Unidades de PM subordinadas.", "s": "10 Diretorias (assunto-meio) + 7 Grandes Comandos (assunto-fim/operacional). Decore: Diretoria PLANEJA/fiscaliza a política; Grande Comando EXECUTA a política operacional através dos batalhões."}'::jsonb),
('law_12896', 40, '{"t": "sec", "x": "Seção I — Das Competências das Diretorias"}'::jsonb),
('law_12896', 41, '{"t": "art", "n": "Art. 29", "x": "A Diretoria de Comunicação Social (DCS) gerencia a política de comunicação social, marketing, publicidade, propaganda e ações sociais: cerimonial militar, eventos, projetos sociais, redes sociais e jornalismo institucional.", "s": "DCS cuida da “imagem” da PM: cerimonial, eventos, redes sociais, imprensa."}'::jsonb),
('law_12896', 42, '{"t": "art", "n": "Art. 30", "x": "A Diretoria de Ensino (DE), criada pela Lei nº 5.657/1993, gerencia a política de ensino, cultura e doutrina operacional/administrativa: formação, aperfeiçoamento, especialização, treinamento e instrução de oficiais e praças.\nParágrafo único - A Academia de Polícia Militar Gonçalves Dias (APMGD) vincula-se academicamente à UEMA, como unidade especial, respeitadas as peculiaridades do ensino militar.", "s": "DE cuida da formação de todos os PMs. PEGADINHA: a Academia (APMGD) é vinculada academicamente à UEMA (Universidade Estadual do Maranhão), não à UFMA."}'::jsonb),
('law_12896', 43, '{"t": "art", "n": "Art. 31", "x": "A Diretoria-Geral de Ensino Regular (DGER) gerencia a política de ensino/instrução, orientando, normatizando e fiscalizando as Diretorias-Adjuntas de Ensino Regular (DAER).\nParágrafo único - A DGER sucede a antiga Diretoria de Ensino Regular (DER), criada pela Lei nº 10.823/2018, em todas as suas competências.", "s": "DGER cuida dos COLÉGIOS MILITARES (ensino regular civil), diferente da DE, que cuida da formação POLICIAL."}'::jsonb),
('law_12896', 44, '{"t": "art", "n": "Art. 32", "x": "A Diretoria de Finanças (DF), criada pela Lei nº 4.570/1984, planeja/coordena/supervisiona/executa a política institucional de execução orçamentária, financeira e contábil.", "s": "DF cuida do dinheiro/orçamento da Corporação."}'::jsonb),
('law_12896', 45, '{"t": "art", "n": "Art. 33", "x": "A Diretoria de Gestão de Patrimônio e Logística (DGPL) planeja/coordena/supervisiona/executa suprimento e manutenção de materiais e equipamentos.\nParágrafo único - A DGPL sucede a antiga Diretoria de Apoio Logístico (DAL), criada pela Lei nº 4.716/1986.", "s": "DGPL = patrimônio + logística + suprimento de material."}'::jsonb),
('law_12896', 46, '{"t": "art", "n": "Art. 34", "x": "A Diretoria de Gestão da Tecnologia da Informação (DGTI), criada pela Lei nº 10.823/2018, planeja/coordena/supervisiona/executa a política de tecnologia e segurança da informação.", "s": "DGTI = TI e segurança da informação (sistemas, sites, rede)."}'::jsonb),
('law_12896', 47, '{"t": "art", "n": "Art. 35", "x": "A Diretoria de Inteligência e Assuntos Estratégicos (DIAE), criada pela Lei nº 10.131/2014, planeja/coordena/executa a inteligência e contrainteligência, obtenção e análise de dados, produção/difusão de conhecimento para o processo decisório.", "s": "DIAE é o órgão SETORIAL de inteligência (não confundir com o PM/2 do EMG, que é a seção de ESTADO-MAIOR de inteligência)."}'::jsonb),
('law_12896', 48, '{"t": "art", "n": "Art. 36", "x": "A Diretoria de Gestão de Pessoas (DGP) planeja/coordena/supervisiona/executa a política institucional de recursos humanos.\nParágrafo único - A DGP sucede a antiga Diretoria de Pessoal (DP), criada pela Lei nº 4.570/1984.", "s": "DGP = RH da corporação. PEGADINHA: também é a DGP quem controla o efetivo dos militares “emprestados” a órgãos externos (art. 112, §1º)."}'::jsonb),
('law_12896', 49, '{"t": "art", "n": "Art. 37", "x": "A Diretoria de Projetos (DProj) planeja/coordena/executa a política de modernização e eficiência administrativa, elaborando propostas e gerenciando parcerias para investimentos, além da captação de recursos.", "s": "DProj = capta recursos e toca projetos de modernização."}'::jsonb),
('law_12896', 50, '{"t": "art", "n": "Art. 38", "x": "A Diretoria de Saúde e Promoção Social (DSPS), criada pela Lei nº 10.212/2015, planeja/coordena/executa a política de saúde e assistência social/psicológica aos militares da ativa, reserva remunerada, reformados, servidores civis e dependentes.", "s": "DSPS cuida de saúde + assistência social/psicológica — até de quem está na reserva/reformado."}'::jsonb),
('law_12896', 51, '{"t": "art", "n": "Art. 39", "x": "As diretorias possuem as unidades administrativas: direção; subdireção; seção administrativa; seções.", "s": "Estrutura-padrão de toda diretoria: direção, subdireção, seção administrativa, seções."}'::jsonb),
('law_12896', 52, '{"t": "sec", "x": "Seção II — Das Competências dos Grandes Comandos de Policiamento"}'::jsonb),
('law_12896', 53, '{"t": "art", "n": "Art. 40", "x": "O Comando de Policiamento Metropolitano (CPM), criado pela Lei nº 11.346/2020, elabora diretrizes de polícia ostensiva/preservação da ordem, coordenando e fiscalizando sua execução pelos Comandos de Policiamento de Áreas Metropolitanas.", "s": "CPM comanda a Região Metropolitana de São Luís."}'::jsonb),
('law_12896', 54, '{"t": "art", "n": "Art. 41", "x": "O Comando de Policiamento do Interior (CPI), criado pela Lei nº 9.043/2009, elabora diretrizes de polícia ostensiva/preservação da ordem para o interior, coordenando e fiscalizando os Comandos de Policiamento de Área (CPA) do interior.", "s": "CPI comanda todo o resto do Estado fora da Grande São Luís."}'::jsonb),
('law_12896', 55, '{"t": "art", "n": "Art. 42", "x": "O Comando de Policiamento Especializado (CPE), criado pela Lei nº 9.795/2013, elabora diretrizes de polícia ostensiva especializada, coordenando as unidades especializadas subordinadas e apoiando os demais comandos de policiamento.", "s": "CPE reúne as unidades “técnicas” especializadas (rodoviária, rural, motopatrulhamento, guardas)."}'::jsonb),
('law_12896', 56, '{"t": "art", "n": "Art. 43", "x": "O Comando de Missões Especiais (CME), criado pela Lei nº 10.823/2018, elabora diretrizes de polícia ostensiva de missões especiais, coordenando unidades de missões especiais, apoiando os demais comandos e executando operações de alto risco contra crime organizado, crimes violentos e ataques a instituições financeiras.", "s": "CME é a “casa” do BOPE, Choque, ROTAM etc. — operações de alto risco."}'::jsonb),
('law_12896', 57, '{"t": "art", "n": "Art. 44", "x": "O Comando de Policiamento Ambiental (CPA) elabora diretrizes de proteção ao meio ambiente, coordenando as unidades de policiamento ambiental e apoiando os demais comandos.", "s": "CPA cuida da polícia ambiental."}'::jsonb),
('law_12896', 58, '{"t": "art", "n": "Art. 45", "x": "O Comando de Policiamento de Turismo (CPTur) elabora diretrizes de proteção turística, coordenando as unidades de policiamento de turismo e apoiando os demais comandos.", "s": "CPTur cuida da segurança turística."}'::jsonb),
('law_12896', 59, '{"t": "art", "n": "Art. 46", "x": "O Comando de Segurança Comunitária (CSC), criado pela Lei nº 10.131/2014, elabora diretrizes de segurança comunitária, coordenando as unidades de policiamento escolar e de proteção a grupos vulneráveis, e apoiando os demais comandos.", "s": "CSC cuida de polícia escolar + grupos vulneráveis (inclui Maria da Penha e PROERD)."}'::jsonb),
('law_12896', 60, '{"t": "art", "n": "Art. 47", "x": "Os Grandes Comandos, todos com sede na Região Metropolitana de São Luís, têm circunscrição em todo o Estado, exceto o CPM (restrito à Região Metropolitana) e o CPI (restrito aos demais municípios).", "s": "PEGADINHA: TODOS os 7 Grandes Comandos ficam sediados em São Luís — mesmo os que atuam no interior inteiro. Só CPM e CPI têm circunscrição territorial limitada; os outros 5 atuam no Estado inteiro."}'::jsonb),
('law_12896', 61, '{"t": "art", "n": "Art. 48", "x": "Os Grandes Comandos possuem: comando; chefia do EM; seção administrativa; seções; corregedoria de área; seção de controle interno.", "s": "Estrutura-padrão dos Grandes Comandos — repare que já têm sua PRÓPRIA corregedoria de área."}'::jsonb),
('law_12896', 62, '{"t": "cap", "x": "CAPÍTULO IV — DOS ÓRGÃOS DE ASSESSORAMENTO"}'::jsonb),
('law_12896', 63, '{"t": "art", "n": "Art. 49", "x": "Os órgãos de assessoramento prestam assessoria/consultoria/orientação técnica e expedem nota técnica para as decisões dos órgãos de direção geral: I- Alto Comando (AC); II- Conselho Consultivo (CCSup); III- Assessoria de Relações Institucionais (ARI); IV- Assessoria de Assuntos Institucionais (AAI); V- Assessoria Especial de Apoio Jurídico-administrativo (AEAJAD); VI- Unidade de Gestão de Integridade e Compliance (UGI); VII- Ouvidoria (Ouv. PM); VIII- Comissão Permanente de Comendas e Honrarias (CPCH); IX- Comissão Permanente de Uniformes (CPU); X- Comissão de Promoção de Oficiais (CPO); XI- Comissão de Promoção de Praças (CPP); XII- Comissões e Conselhos Temporários (CCT).\n§1º O Alto Comando é o órgão MÁXIMO de assessoramento, formado pelo Comandante-Geral (que preside), Subcomandante-Geral, Chefe do EMG, Corregedor-Geral e titulares dos órgãos de direção setorial; caráter consultivo e DELIBERATIVO sobre orçamento, reformas, projetos de lei, atos normativos e promoção ao último posto.\n§2º O Conselho Consultivo Superior é órgão de consulta de ALTO NÍVEL, formado pelo Comandante-Geral (que preside), Subcomandante-Geral, Chefe do EMG e Coronéis da ativa que já foram Comandante-Geral; natureza ESTRITAMENTE consultiva (não delibera), reúne-se por convocação do Presidente.\n§3º a §6º ARI, AAI, AEAJAD e UGI têm cada uma Chefia e Secretaria-Executiva, com atribuições próprias de articulação política, interlocução institucional, assessoria jurídica e integridade/compliance, respectivamente.\n§7º A Ouvidoria recebe/analisa/encaminha reclamações, sugestões e elogios.\n§8º e §9º CPCH e CPU têm presidência/vice-presidência, membros natos/efetivos/suplentes e secretaria, cuidando de medalhas/condecorações e de uniformes, respectivamente.\n§10º e §11º CPO é presidida pelo COMANDANTE-GERAL (analisa promoção de oficiais); CPP é presidida pelo SUBCOMANDANTE-GERAL (analisa promoção de praças).\n§12º CCT são temporárias, extintas ao fim do prazo/finalidade.", "s": "PEGADINHA de prova: Alto Comando é DELIBERATIVO (decide); Conselho Consultivo Superior é só CONSULTIVO (não decide). E: quem preside a Comissão de Promoção de OFICIAIS é o COMANDANTE-Geral; quem preside a de PRAÇAS é o SUBCOMANDANTE-Geral."}'::jsonb),
('law_12896', 64, '{"t": "art", "n": "Art. 50", "x": "A Secretaria-Executiva dá gestão, suporte administrativo/operacional aos órgãos de assessoramento e monitora as metas de suas competências finalísticas.", "s": "Secretaria-Executiva é o “apoio de escritório” comum a vários órgãos de assessoramento."}'::jsonb),
('law_12896', 65, '{"t": "cap", "x": "CAPÍTULO V — DOS ÓRGÃOS DE APOIO"}'::jsonb),
('law_12896', 66, '{"t": "art", "n": "Art. 51", "x": "Os órgãos de apoio realizam as atividades-meio nas áreas de RH, saúde, ensino, pesquisa, logística e gestão orçamentária/financeira: I- Apoio ao Comando-Geral (Ajudância-Geral com Banda de Música; Comissão Setorial de Licitação); II- Apoio de Ensino (APMGD, CEFAP, CEPM, C-CULT); III- Apoio de Ensino Regular (4 DAER com os Colégios Militares Tiradentes e Creches-Escola); IV- Apoio de Gestão e Logística (CTM, CMB, CTT, Almoxarifado-Geral); V- Apoio de Saúde e Promoção Social (CIAMS, CODPM, PVPM, CAPS, CRF PM, CPPSO, Capelania Militar).", "s": "5 grupos de órgãos de APOIO (atividade-meio, não operacional): comando-geral, ensino, ensino regular, logística, saúde."}'::jsonb),
('law_12896', 67, '{"t": "art", "n": "Art. 52", "x": "A Ajudância-Geral (AJG), criada pela Lei nº 4.570/1984, cuida da gestão administrativa/logística/RH do quartel do Comando-Geral, com Chefia, Seção Administrativa, Seções e Banda de Música.\nParágrafo único - A Banda de Música João Carlos Dias Nazareth é Patrimônio Cultural Imaterial do Maranhão (Lei nº 10.962/2018), responsável pelo aperfeiçoamento musical e execução em solenidades/eventos culturais.", "s": "PEGADINHA cultural: a Banda de Música da PMMA é Patrimônio Cultural Imaterial do Maranhão!"}'::jsonb),
('law_12896', 68, '{"t": "art", "n": "Art. 53", "x": "A Comissão Setorial de Licitação (CSL) conduz processos licitatórios e formaliza contratos e convênios da Corporação, com presidência e seção administrativa.", "s": "CSL cuida das licitações e contratos."}'::jsonb),
('law_12896', 69, '{"t": "art", "n": "Art. 54", "x": "A Academia de Polícia Militar Gonçalves Dias (APMGD), criada pela Lei nº 9.658/2012, é órgão de ENSINO SUPERIOR que planeja/coordena/executa a formação/aperfeiçoamento/especialização/treinamento e os cursos de Altos Estudos Superiores para Oficiais da Corporação e coirmãs, com comando, subcomando, estado-maior, secretaria, seção administrativa, seções, companhias e pelotões de alunos.\nParágrafo único - Terá regimento próprio sobre funcionamento, competências e regime disciplinar dos alunos.", "s": "APMGD é órgão de ENSINO SUPERIOR — forma os Oficiais e dá os cursos de altos estudos."}'::jsonb),
('law_12896', 70, '{"t": "art", "n": "Art. 55", "x": "O Centro de Educação, Formação e Aperfeiçoamento Profissional (CEFAP) é órgão de ensino superior de formação/capacitação/aperfeiçoamento das PRAÇAS, sucedendo o antigo CFAP (Lei nº 4.570/1984), com estrutura semelhante à da APMGD (comando, subcomando, estado-maior etc.).", "s": "CEFAP está para as PRAÇAS assim como a APMGD está para os OFICIAIS."}'::jsonb),
('law_12896', 71, '{"t": "art", "n": "Art. 56", "x": "O Complexo Esportivo da PM Coronel PM Ronilson Gomes (CEPM) cuida das atividades de educação física, desportos e lazer da Corporação, com chefia e seção administrativa.", "s": "CEPM = esporte e lazer."}'::jsonb),
('law_12896', 72, '{"t": "art", "n": "Art. 57", "x": "O Centro Cultural Coronel PM Carlos Augusto Castro Lopes (C-CULT) conserva, investiga, comunica e expõe acervos de valor histórico/artístico/científico da Corporação, com chefia e seção administrativa.", "s": "C-CULT = o “museu” da PMMA."}'::jsonb),
('law_12896', 73, '{"t": "art", "n": "Art. 58", "x": "As Diretorias-Adjuntas de Ensino Regular (DAER) executam a política de ensino/instrução, fiscalizando/coordenando as unidades de ensino de sua circunscrição, com direção, subdireção, seção administrativa, seções, Colégios Militares Tiradentes e creche-escola.\n§1º Os Colégios Militares Tiradentes (CMT) dão ensino fundamental/médio a dependentes de militares/servidores civis e à comunidade, em parceria com SEDUC e SSP, com foco em disciplina e rendimento escolar.\n§2º A Creche-Escola I (CE PM) dá educação infantil a dependentes de militares/civis e à comunidade.\n§3º CMTs e Creche-Escola terão regimento próprio.\n§4º A PM manterá CMTs em regime de CONVÊNIO com municípios.\n§5º Nos CMTs conveniados (fora da estrutura da corporação), a Direção é exercida por Coronel da reserva remunerada e, na falta, por Oficial Superior também da reserva; só na ausência de reserva interessado/habilitado, por Oficial Superior da ativa.", "s": "Existem 4 DAER (São Luís, Imperatriz, Caxias, Bacabal), cada uma cuidando de um grupo de Colégios Tiradentes. PEGADINHA: nos colégios CONVENIADOS com municípios, o Diretor é PREFERENCIALMENTE Coronel da RESERVA REMUNERADA — só vai pra ativa se não achar ninguém da reserva."}'::jsonb),
('law_12896', 74, '{"t": "art", "n": "Art. 59", "x": "O Centro de Transporte e Manutenção (CTM) assegura a operacionalidade dos meios de transporte, planejando/coordenando/executando manutenção de viaturas/embarcações e controle de abastecimento.", "s": "CTM = frota e manutenção de viaturas."}'::jsonb),
('law_12896', 75, '{"t": "art", "n": "Art. 60", "x": "O Centro de Material Bélico (CMB) planeja/coordena/executa o recebimento/armazenamento/controle/distribuição de armamentos, munições e equipamentos de proteção balística.", "s": "CMB = armas, munição e colete/proteção balística."}'::jsonb),
('law_12896', 76, '{"t": "art", "n": "Art. 61", "x": "O Centro de Tecnologia e Telecomunicações (CTT) planeja/coordena/fiscaliza os sistemas de radiocomunicação e o emprego de aeronaves não tripuladas (drones), provendo conectividade e vigilância aérea remota.", "s": "CTT cuida de rádio e DRONES."}'::jsonb),
('law_12896', 77, '{"t": "art", "n": "Art. 62", "x": "O Centro Integrado de Assistência Médica e Social (CIAMS) Coronel PM Marinaldo Salles Silva oferece serviços médicos/assistência social aos integrantes e dependentes.", "s": "CIAMS = atendimento médico e social geral."}'::jsonb),
('law_12896', 78, '{"t": "art", "n": "Art. 63", "x": "O Centro de Odontologia da PM (CODPM) dá atendimento odontológico integral aos PMs e dependentes legais.", "s": "CODPM = dentista."}'::jsonb),
('law_12896', 79, '{"t": "art", "n": "Art. 64", "x": "A Policlínica Veterinária da PM (PVPM) dá atendimento clínico/cirúrgico aos animais da instituição (cães e cavalos), garantindo higidez para o serviço operacional.", "s": "PVPM cuida da saúde de cães e cavalos da PM."}'::jsonb),
('law_12896', 80, '{"t": "art", "n": "Art. 65", "x": "O Centro de Assistência e Promoção Social (CAPS) planeja e executa ações de assistência psicossocial aos integrantes e dependentes.", "s": "CAPS = assistência psicossocial."}'::jsonb),
('law_12896', 81, '{"t": "art", "n": "Art. 66", "x": "O Centro de Reabilitação Física da PM (CRFPM) coordena/executa programas de promoção da higidez física e reabilitação integrada ao controle médico de saúde ocupacional.", "s": "CRFPM = reabilitação física."}'::jsonb),
('law_12896', 82, '{"t": "art", "n": "Art. 67", "x": "O Centro de Perícias e Saúde Ocupacional (CPPSO) cuida de perícia médica, inspeções de saúde regulamentares, Juntas Militares de Saúde e do programa de prevenção de risco ambiental.", "s": "CPPSO = perícias médicas e Junta Militar de Saúde."}'::jsonb),
('law_12896', 83, '{"t": "art", "n": "Art. 68", "x": "A Capelania Militar Monsenhor Hélio Maranhão presta assistência religiosa/espiritual/moral aos membros da PM e famílias.", "s": "Capelania = apoio religioso e espiritual."}'::jsonb),
('law_12896', 84, '{"t": "tit", "x": "TÍTULO III — DOS ÓRGÃOS DE EXECUÇÃO"}'::jsonb),
('law_12896', 85, '{"t": "cap", "x": "CAPÍTULO I — DOS COMANDOS DE POLICIAMENTO DE ÁREAS"}'::jsonb),
('law_12896', 86, '{"t": "art", "n": "Art. 69", "x": "Os Comandos de Policiamento de Áreas (Metropolitana e Interior) são órgãos de execução de nível INTERMEDIÁRIO, responsáveis pela polícia ostensiva, preservação da ordem e polícia judiciária militar em suas circunscrições: I- 4 Comandos de Policiamento de Área Metropolitana (CPAM Norte, Sul, Leste, Oeste), subordinados ao CPM, todos com sede em São Luís; II- 9 Comandos de Policiamento de Área do Interior (CPAI 1 a 9), subordinados ao CPI, com sedes em Bacabal, Barra do Corda, Imperatriz, Caxias, Pinheiro, Balsas, Chapadinha, Pindaré-Mirim e Timon, respectivamente.", "s": "São 4 CPAM (só na Grande São Luís) + 9 CPAI (cobrindo o interior todo) = 13 Comandos de Área no total."}'::jsonb),
('law_12896', 87, '{"t": "art", "n": "Art. 70", "x": "Compete aos Comandos de Policiamento de Áreas: desdobrar/executar diretrizes da política de emprego operacional; planejar/coordenar/fiscalizar o policiamento ostensivo; gerenciar RH/materiais/logística; promover integração com outros órgãos de segurança; implementar diretrizes de ensino/doutrina; realizar análise estatística/criminal; gerenciar o serviço local de inteligência (sob orientação técnica da DIAE).", "s": "CPA é o “gerente regional”: pega a diretriz de cima e desdobra pra realidade local, inclusive coordenando a inteligência local sob orientação da DIAE."}'::jsonb),
('law_12896', 88, '{"t": "art", "n": "Art. 71", "x": "Os Comandos de Policiamento de Áreas são constituídos de: comando; chefia do estado-maior; seção administrativa; seções; seção de saúde; seção de controle interno; corregedorias de áreas.", "s": "Cada CPA já tem sua própria corregedoria de área — igual os Grandes Comandos."}'::jsonb),
('law_12896', 89, '{"t": "cap", "x": "CAPÍTULO II — DAS UNIDADES DE POLÍCIA MILITAR"}'::jsonb),
('law_12896', 90, '{"t": "art", "n": "Art. 72", "x": "As Unidades de Polícia Militar (UPM) — organizadas em Batalhões de PM, Regimentos de Polícia Montada, Companhias Independentes de PM e Esquadrões de Polícia Montada — executam a atividade-fim da Corporação em suas circunscrições.", "s": "4 tipos de UPM: Batalhão, Regimento (montado), Companhia Independente, Esquadrão (montado)."}'::jsonb),
('law_12896', 91, '{"t": "art", "n": "Art. 73", "x": "As UPM subordinam-se aos respectivos CPA/CPAI (dezenas de Batalhões de PM numerados, distribuídos entre os 4 CPAM e os 9 CPAI, conforme a sede de cada município). Além disso, subordinam-se diretamente aos Grandes Comandos especializados diversas unidades táticas: ao CPE — Batalhões de Motopatrulhamento Tático (BMT), o Batalhão de Polícia Militar Rodoviária (BPRv, circunscrição estadual), o Batalhão de Polícia Rural (BPRur, circunscrição estadual) e as Companhias de Polícia de Guardas Independentes (segurança do Palácio do Governo e do Quartel do Comando-Geral/Presídio Militar); ao CME — o Batalhão de Polícia Militar de Choque (BPChoq., controle de distúrbios civis e combate ao crime organizado), o Batalhão de Operações Especiais (BOPE, ocorrências de alto risco, intervenção tática, negociação, desativação de explosivos), o Batalhão Especializado de Policiamento de Eventos (BEPE), o Batalhão de Policiamento Tático Motorizado (ROTAM), o Batalhão Especializado de Policiamento do Interior (BEPI), o 1º Regimento e o 1º Esquadrão de Polícia Montada, e o Batalhão de Ações com Cães (BAC); ao CPTur — 3 Batalhões de Polícia Militar de Turismo; ao CPA — 2 Batalhões de Polícia Ambiental; e ao CSC — o 1º Batalhão Escolar da PM e o Departamento de Políticas Preventivas (DPREV), do qual fazem parte o PROERD (prevenção primária a drogas/violência para crianças e famílias) e a Patrulha Maria da Penha (acompanhamento de vítimas de violência doméstica e fiscalização de medidas protetivas).", "s": "Decore as “estrelas” do art. 73: BOPE = alto risco/explosivos/negociação; ROTAM = tático motorizado; Choque = distúrbios civis; BPRv = rodovias (estadual); BPRur = área rural (estadual); BAC = cães; Maria da Penha = medidas protetivas; PROERD = prevenção com crianças."}'::jsonb),
('law_12896', 92, '{"t": "art", "n": "Art. 74", "x": "A atuação das unidades especializadas, de missões especiais, de turismo, de meio ambiente e de segurança comunitária ocorre em suas circunscrições e em SUPORTE às demais UPM, observadas as diretrizes dos respectivos comandos de policiamento.", "s": "As unidades especializadas não substituem o batalhão local — elas dão APOIO/reforço a ele."}'::jsonb),
('law_12896', 93, '{"t": "art", "n": "Art. 75", "x": "Compete às UPM: executar o policiamento ostensivo; aplicar a filosofia de polícia comunitária; agir preventiva/repressivamente em perturbações da ordem; exercer poder de polícia administrativa; interagir com outros órgãos de segurança; fazer comunicação social e projetos sociais locais; realizar o serviço local de inteligência (orientado pela DIAE); exercer polícia judiciária militar; e, quanto à proteção ambiental: prevenir condutas lesivas, lavrar auto de infração, aplicar sanções administrativas e promover educação ambiental (integrante do SISNAMA).", "s": "UPM tem até competência ambiental própria (autuar e educar), como integrante do SISNAMA — não é só o Batalhão Ambiental que cuida disso."}'::jsonb),
('law_12896', 94, '{"t": "cap", "x": "CAPÍTULO III — DAS ÁREAS DE RESPONSABILIDADES E DESDOBRAMENTO DOS ÓRGÃOS DE EXECUÇÃO"}'::jsonb),
('law_12896', 95, '{"t": "art", "n": "Art. 76", "x": "Área de Policiamento é o espaço territorial sob responsabilidade de um CPA, delimitado para otimizar o emprego dos meios operacionais.\nParágrafo único - Isso NÃO se aplica ao CPE e ao CME (nem suas unidades subordinadas), que atuam em TODO o Estado como reforço/suporte especializado.", "s": "CPE e CME são exceção: não têm “território fixo”, atuam em qualquer lugar do Estado como reforço."}'::jsonb),
('law_12896', 96, '{"t": "sec", "x": "Seção I — Das Áreas de Responsabilidade dos Comandos de Policiamento de Áreas"}'::jsonb),
('law_12896', 97, '{"t": "art", "n": "Art. 77", "x": "O Estado é dividido em áreas geridas pelos respectivos CPA (Metropolitana ou Interior), por meio das UPM nelas sediadas.\nParágrafo único - Cada CPA atua estritamente em sua circunscrição, com sede no município de maior representatividade regional, seguindo as orientações do CPM ou CPI ao qual se subordina.", "s": "Cada CPA fica só no seu “quadrado” territorial — sede no município mais importante da região."}'::jsonb),
('law_12896', 98, '{"t": "sec", "x": "Seção II — Das Áreas de Responsabilidade e Desdobramento das Unidades de Polícia Militar"}'::jsonb),
('law_12896', 99, '{"t": "art", "n": "Art. 78", "x": "Área de UPM é o espaço sob responsabilidade direta de um Batalhão/Regimento/Companhia Independente/Esquadrão, para planejamento tático e execução do policiamento.\n§1º A área pode ser subdividida em subáreas e estas em setores, cada uma sob a subunidade imediatamente subordinada.\n§2º O comando responsável deve sediar-se no território de sua circunscrição.", "s": "Hierarquia territorial: Área (Batalhão) > Subárea (Companhia) > Setor (Pelotão)."}'::jsonb),
('law_12896', 100, '{"t": "art", "n": "Art. 79", "x": "A organização e o efetivo de cada Unidade operacional são definidos com base em: extensão territorial; distribuição demográfica; população pendular; indicadores de criminalidade; desenvolvimento econômico; situações peculiares da área.", "s": "6 critérios técnicos definem o tamanho de cada unidade — não é aleatório."}'::jsonb),
('law_12896', 101, '{"t": "art", "n": "Art. 80", "x": "Os Batalhões de PM e Regimentos de Polícia Montada terão efetivo classificado por tipo, mediante ato do Comandante-Geral: I- Tipo I: 336 a 400 PMs; II- Tipo II: 271 a 335 PMs; III- Tipo III: até 270 PMs.", "s": "Decore os números: Tipo I (336-400), Tipo II (271-335), Tipo III (até 270). Quem classifica é o Comandante-Geral."}'::jsonb),
('law_12896', 102, '{"t": "art", "n": "Art. 81", "x": "As Companhias de Polícia Militar Independentes e os Esquadrões de Polícia Montada terão efetivo de até 250 PMs.", "s": "Companhia Independente/Esquadrão: teto de 250 PMs (menor que qualquer Batalhão)."}'::jsonb),
('law_12896', 103, '{"t": "art", "n": "Art. 82", "x": "Cada UPM terá, no mínimo, 2 e, no máximo, 6 subunidades imediatamente subordinadas.\n§1º Se a unidade não suprir a demanda, cria-se PREFERENCIALMENTE nova unidade de mesma natureza ou de escalão inferior, redistribuindo a área.\n§2º A menor unidade operacional, o Grupo Policial Militar (Gp PM), é formado por um 2º ou 3º Sargento PM e, no mínimo, 3 Soldados PM.", "s": "Toda UPM tem entre 2 e 6 subunidades. E decore a “menor peça do tabuleiro”: Grupo PM = 1 Sargento (2º ou 3º) + no mínimo 3 Soldados."}'::jsonb),
('law_12896', 104, '{"t": "art", "n": "Art. 83", "x": "O município sem Batalhão, Companhia ou Pelotão contará com um Destacamento Policial Militar (Dst PM), com estrutura mínima de um Grupo Policial Militar.", "s": "Destacamento PM = a “menor presença fixa” da PM num município, com no mínimo 1 Grupo PM."}'::jsonb),
('law_12896', 105, '{"t": "art", "n": "Art. 84", "x": "Estrutura básica das UPM: I- Batalhão/Regimento: comando, subcomando, chefia do EM, seção administrativa, seção operacional, companhias, pelotões, destacamentos; II- Companhia Independente/Esquadrão: comando, subcomando, chefia do EM, seção administrativa, seção operacional, pelotões, destacamentos; III- Companhias de PM: comando, subcomando, seção administrativa, pelotões, destacamentos; IV- Pelotões de PM: comando, grupos.", "s": "Quanto MENOR a unidade, mais simples a estrutura — só o Pelotão não tem “chefia do EM” nem seção administrativa própria, só comando e grupos."}'::jsonb),
('law_12896', 106, '{"t": "tit", "x": "TÍTULO IV — DOS ÓRGÃOS DE CORREIÇÃO"}'::jsonb),
('law_12896', 107, '{"t": "art", "n": "Art. 85", "x": "A Corregedoria-Geral da PM (CG PM) é órgão de correição responsável pela preservação da ética/disciplina e pelo exercício da polícia judiciária militar e corregedoria administrativa, constituída de: Corregedoria-Geral; Seção Administrativa; Seção de Polícia Judiciária Militar; Seção de Processos Administrativos; Seção de Inteligência e Contrainteligência; Corregedorias de Áreas; Presídio Militar (PM).", "s": "A Corregedoria-Geral tem até sua PRÓPRIA seção de inteligência — e comanda o Presídio Militar."}'::jsonb),
('law_12896', 108, '{"t": "art", "n": "Art. 86", "x": "O Corregedor-Geral da PM é nomeado pelo Governador, mediante indicação do Comandante-Geral, entre Coronéis da ativa do QOEM.\nParágrafo único - É o substituto imediato do Chefe do Estado-Maior Geral, com precedência sobre os demais oficiais do último posto, subordinando-se ao Comandante-Geral, ao Subcomandante-Geral e ao Chefe do EMG.", "s": "Cadeia de substituição: Comandante-Geral → Subcomandante-Geral → Chefe do EMG → Corregedor-Geral. Decore essa ORDEM, é clássico de prova."}'::jsonb),
('law_12896', 109, '{"t": "art", "n": "Art. 87", "x": "O Presídio Militar (PM) gere a custódia de PMs à disposição da justiça comum ou militar, subordinado à Corregedoria-Geral, com direção e seção administrativa.\nParágrafo único - Compete ao Presídio Militar: custodiar PMs da ativa/reserva/reformados presos à disposição da justiça; garantir cumprimento de sentenças/medidas cautelares; zelar pelas prerrogativas de segurança do custodiado.", "s": "Presídio Militar é subordinado à CORREGEDORIA-Geral (não ao Comando-Geral diretamente)."}'::jsonb),
('law_12896', 110, '{"t": "art", "n": "Art. 88", "x": "O funcionamento da Corregedoria-Geral e suas unidades será detalhado em Regimento Interno, aprovado pelo Comandante-Geral.", "s": "Quem aprova o regimento da Corregedoria é o Comandante-Geral (apesar da Corregedoria fiscalizar a própria PM)."}'::jsonb),
('law_12896', 111, '{"t": "tit", "x": "TÍTULO V — DO EFETIVO, DA HIERARQUIA MILITAR E DOS QUADROS DE PESSOAL"}'::jsonb),
('law_12896', 112, '{"t": "cap", "x": "CAPÍTULO I — DO EFETIVO"}'::jsonb),
('law_12896', 113, '{"t": "art", "n": "Art. 89", "x": "O efetivo da PM passa a ser de 14.290 policiais militares, distribuídos conforme os Anexos II e III.\n§1º O efetivo de Praças Especiais é variável, admitido anualmente por proposta do Comandante-Geral e aprovação do Governador, nos limites de 50 para Aspirante a Oficial, 120 para Cadete e 80 para Aluno-Oficial.\n§2º As vagas de promoção por completar requisitos de transferência (art. 14, I, da Lei nº 12.597/2025) formam o Quadro Suplementar (Anexo IV), como vagas PARALELAS, não computadas no efetivo geral.", "s": "Decore o número: efetivo total = 14.290. Limites anuais de Praças Especiais: 50 Aspirantes, 120 Cadetes, 80 Alunos-Oficiais — e o Quadro Suplementar NÃO conta nesse total."}'::jsonb),
('law_12896', 114, '{"t": "art", "n": "Art. 90", "x": "A PM, por intermédio da Secretaria de Estado de Administração, elabora decreto do quadro de efetivo, consolidando alterações e mostrando cargos criados/ocupados/vagos.\nParágrafo único - O decreto deve ser publicado em DEZEMBRO de cada exercício, com notas sobre os atos que fundamentaram as mudanças.", "s": "Prazo fixo pra publicar o decreto do efetivo: dezembro de cada ano."}'::jsonb),
('law_12896', 115, '{"t": "art", "n": "Art. 91", "x": "Os cargos de provimento efetivo do pessoal civil lotado na PM constam do Anexo VI.", "s": "Existe um quadro próprio (Anexo VI) só pra cargos de servidores CIVIS na PM."}'::jsonb),
('law_12896', 116, '{"t": "cap", "x": "CAPÍTULO II — DA HIERARQUIA MILITAR"}'::jsonb),
('law_12896', 117, '{"t": "art", "n": "Art. 92", "x": "Ordenação hierárquica: I- Oficiais: superiores (Coronel, Tenente-Coronel, Major); intermediários (Capitão); subalternos (1º Tenente, 2º Tenente); II- Praças Especiais: Aspirante a Oficial, Cadete, Aluno-Oficial; III- Praças: Subtenente, 1º Sargento, 2º Sargento, 3º Sargento, Aluno-Sargento, Cabo, Soldado, Aluno-Soldado.\nParágrafo único - A todos os postos/graduações se acrescenta a designação “PM”.", "s": "PEGADINHA: agora “Capitão” é classificado como Oficial INTERMEDIÁRIO (não mais junto dos subalternos como no Estatuto antigo) — decore essa reclassificação nova."}'::jsonb),
('law_12896', 118, '{"t": "cap", "x": "CAPÍTULO III — DOS QUADROS DE PESSOAL MILITAR"}'::jsonb),
('law_12896', 119, '{"t": "art", "n": "Art. 93", "x": "Quadros: I- Oficiais da ativa: QOEM (Estado-Maior), QOE (Especialistas), QOMus. (Músicos), QOS (Saúde), QOC (Capelães); II- Praças da ativa: QP (Praças), QPMus. (Praças Músicos); III- Oficiais da Reserva e Reformados: QORR; IV- Praças da Reserva e Reformados: QPRR.", "s": "9 quadros no total: 5 de Oficial da ativa + 2 de Praça da ativa + 1 de Oficial inativo + 1 de Praça inativo."}'::jsonb),
('law_12896', 120, '{"t": "art", "n": "Art. 94", "x": "A PM fará processos seletivos internos para habilitar militares a funções compatíveis com sua formação no QOE e no QP, sem mudança de carreira/posto/graduação nem prejuízo à atividade-fim.", "s": "Seleção interna só REALOCA função, não muda carreira nem posto."}'::jsonb),
('law_12896', 121, '{"t": "art", "n": "Art. 95", "x": "Após concluir o curso de formação e ingressar, o militar permanece no mínimo 3 anos na área do Comando de Policiamento de sua primeira classificação.\nParágrafo único - Movimentação antes desse prazo só por necessidade de serviço ou relevante interesse público, justificada pelo Comandante-Geral e autorizada pelo Governador.", "s": "Regra dos “3 anos fixos” após a formatura — só sai antes com justificativa do Comandante-Geral E autorização do Governador (as duas coisas)."}'::jsonb),
('law_12896', 122, '{"t": "sec", "x": "Seção I — Dos Quadros de Oficiais da Ativa"}'::jsonb),
('law_12896', 123, '{"t": "art", "n": "Art. 96", "x": "O QOEM, destinado a comando/chefia/direção/administração superior, é integrado por oficiais BACHARÉIS EM DIREITO, aprovados em concurso público, possuidores do Curso de Formação de Oficiais.\nParágrafo único - O antigo QOPM passa a se chamar QOEM, preservados postos e precedência dos atuais integrantes.", "s": "PEGADINHA importante: hoje o Oficial da linha de frente (QOEM, ex-QOPM) precisa ser BACHAREL EM DIREITO — não é mais só formação militar genérica."}'::jsonb),
('law_12896', 124, '{"t": "art", "n": "Art. 97", "x": "O QOE, para atividades complementares ao QOEM, é integrado por oficiais oriundos do quadro de praças, possuidores do Curso de Habilitação de Oficiais, podendo progredir até Tenente-Coronel.\nParágrafo único - O antigo QOA (Lei nº 3.826/1976) passa a se chamar QOE.", "s": "QOE = ex-praça que virou oficial (CHOA/CHOE) — teto de carreira: Tenente-Coronel (não chega a Coronel)."}'::jsonb),
('law_12896', 125, '{"t": "art", "n": "Art. 98", "x": "O QOMus., para atividades musicais, é integrado por oficiais oriundos do Quadro de Praças Músicos, com Curso de Habilitação de Oficiais, podendo progredir até Tenente-Coronel.", "s": "Oficial músico: mesmo teto do QOE — Tenente-Coronel."}'::jsonb),
('law_12896', 126, '{"t": "art", "n": "Art. 99", "x": "O QOS, para saúde/direção/administração dos órgãos de saúde, é integrado por oficiais com graduação em área de saúde e Curso de Habilitação de Oficiais, podendo progredir até CORONEL.\n§1º Vacância em posto inferior de cada especialidade é contabilizada ao efetivo do posto correspondente até a extinção total das especialidades.\n§2º Editais futuros definirão especialidades/vagas conforme necessidade.\n§3º Fica assegurada a promoção dos atuais QOS dentro de suas especialidades.", "s": "PEGADINHA: o QOS (Saúde) chega até CORONEL — diferente do QOE e QOMus, que param em Tenente-Coronel."}'::jsonb),
('law_12896', 127, '{"t": "art", "n": "Art. 100", "x": "O QOC, para atividades religiosas, é integrado por oficiais com curso superior em Teologia (reconhecido pelo MEC) e experiência ministerial comprovada, aprovados em concurso público, com Curso de Habilitação de Oficiais.\nParágrafo único - Ingressa no posto de 2º Tenente, podendo progredir até CAPITÃO.", "s": "Capelão: entra 2º Tenente, teto CAPITÃO — o menor teto de carreira entre os quadros de oficiais."}'::jsonb),
('law_12896', 128, '{"t": "sec", "x": "Seção II — Do Quadro de Praças da Ativa"}'::jsonb),
('law_12896', 129, '{"t": "art", "n": "Art. 101", "x": "O QP é integrado por praças aprovados em concurso público de NÍVEL SUPERIOR e possuidores do Curso de Formação de Praça, podendo progredir até Subtenente.\nParágrafo único - Os atuais praças da QPMP-0 (Combatentes, Lei nº 3.826/1976) ficam automaticamente incluídos no QP.", "s": "PEGADINHA grande: hoje o concurso de PRAÇA (Soldado) também exige NÍVEL SUPERIOR — não é mais só ensino médio."}'::jsonb),
('law_12896', 130, '{"t": "art", "n": "Art. 102", "x": "O QPMus., para atividades musicais, exige nível superior em música e Curso de Formação de Praças, podendo progredir até Subtenente.\n§1º Os atuais QPMP-4 (Músico) e QPMP-7 (Corneteiro) ficam incluídos automaticamente.\n§2º Os instrumentos musicais do quadro são definidos pelo Comando-Geral conforme a necessidade, especificados em edital.", "s": "Praça músico também precisa de nível superior — em MÚSICA."}'::jsonb),
('law_12896', 131, '{"t": "sec", "x": "Seção III — Do Quadro de Oficiais da Reserva e Reformados"}'::jsonb),
('law_12896', 132, '{"t": "art", "n": "Art. 103", "x": "O QORR é destinado a oficiais da reserva remunerada e reformados.\nParágrafo único - O oficial da reserva remunerada pode ser designado para tarefas por prazo certo, conforme legislação específica.", "s": "QORR = “estacionamento” dos oficiais inativos, mas ainda podem ser chamados por prazo certo."}'::jsonb),
('law_12896', 133, '{"t": "sec", "x": "Seção IV — Do Quadro de Praças da Reserva e Reformados"}'::jsonb),
('law_12896', 134, '{"t": "art", "n": "Art. 104", "x": "O QPRR é destinado a praças da reserva remunerada e reformados.\nParágrafo único - A praça da reserva remunerada pode ser designada para tarefas por prazo certo, conforme legislação específica.", "s": "Mesma lógica do QORR, só que pra praças."}'::jsonb),
('law_12896', 135, '{"t": "cap", "x": "CAPÍTULO IV — DO PESSOAL CIVIL"}'::jsonb),
('law_12896', 136, '{"t": "art", "n": "Art. 105", "x": "O Quadro de Pessoal Civil (QPC) é composto por servidores estaduais de cargo efetivo, de suporte às atividades-meio, SEM vínculo com hierarquia/disciplina militar, regidos pela Lei Estadual nº 6.107/1994 (Estatuto dos Servidores Civis do Maranhão).", "s": "O civil da PM NÃO tem hierarquia militar — segue o estatuto CIVIL comum do Estado."}'::jsonb),
('law_12896', 137, '{"t": "art", "n": "Art. 106", "x": "O ingresso no QPC se dá por concurso público de provas ou provas e títulos, podendo ainda ocorrer por redistribuição (Lei nº 6.107/1994).\nParágrafo único - Observa-se o Plano Geral de Carreiras e Cargos do Executivo Estadual (PGCE, Lei nº 9.664/2012).", "s": "Civil entra por concurso (ou redistribuição) — segue o plano de carreira GERAL do Estado, não um plano próprio da PM."}'::jsonb),
('law_12896', 138, '{"t": "tit", "x": "TÍTULO VI — DA NOMEAÇÃO, DA DESIGNAÇÃO E DA SUBSTITUIÇÃO"}'::jsonb),
('law_12896', 139, '{"t": "art", "n": "Art. 107", "x": "A nomeação do pessoal militar é competência do Governador do Estado.\nParágrafo único - Pode ser delegada ao Comandante-Geral, nos termos da Constituição Estadual.", "s": "Nomear = Governador (delegável ao Comandante-Geral)."}'::jsonb),
('law_12896', 140, '{"t": "art", "n": "Art. 108", "x": "É competência do Comandante-Geral a DESIGNAÇÃO dos militares para cargo ou função no âmbito da Corporação.", "s": "PEGADINHA clássica: NOMEAR é do Governador; DESIGNAR (pra cargo/função interna) é do Comandante-Geral — são competências diferentes."}'::jsonb),
('law_12896', 141, '{"t": "art", "n": "Art. 109", "x": "As funções de comando/chefia de oficiais e as funções auxiliares de praças estão nominadas e codificadas por nível hierárquico, conforme o Anexo V.", "s": "Existe uma tabela de códigos (Anexo V) pra cada função de comando/chefia — cada uma tem seu número."}'::jsonb),
('law_12896', 142, '{"t": "art", "n": "Art. 110", "x": "O exercício de função militar de cada Quadro é restrito aos seus integrantes, VEDADA a designação de militares de quadros distintos, salvo substituição transitória por necessidade de serviço, respeitada a precedência hierárquica e a compatibilidade técnica.\n§1º Na falta de militar com o posto/graduação exigido, pode-se designar hierarquia imediatamente inferior, com compatibilidade técnica.\n§2º Praça designada para encargo administrativo/operacional recebe retribuição de função auxiliar de praça conforme sua graduação (Anexo V, item VIII).", "s": "Regra geral: cada quadro fica no seu quadrado — só pode “emprestar” gente de outro quadro em situação transitória e por necessidade real."}'::jsonb),
('law_12896', 143, '{"t": "art", "n": "Art. 111", "x": "A substituição de comandos/chefias por impedimento legal respeita a precedência hierárquica: I- Comandante-Geral → Subcomandante-Geral; II- Subcomandante-Geral → Chefe do Estado-Maior; III- Chefe do Estado-Maior → Corregedor-Geral; IV- Comandante de Policiamento Metropolitano/Interior → Comandante de Área mais antigo; V- Comandante de Policiamento de Área → Comandante de Área mais antigo; VI- Comandantes de Policiamento Especializado/Missões Especiais/Ambiental/Segurança Comunitária → oficial mais antigo do QOEM em comando de Unidade subordinada, ou designado pelo Comandante-Geral; VII- demais titulares → oficial de maior precedência e capacidade técnica no órgão, sem impedimentos disciplinares; VIII- é permitida acumulação temporária/interina de funções de direção/chefia, para suprir falta de pessoal, sem prejuízo da função principal.", "s": "DECORE A CADEIA (cai muito em prova): Comandante-Geral → Subcomandante-Geral → Chefe do EM → Corregedor-Geral. É a mesma ordem do art. 86."}'::jsonb),
('law_12896', 144, '{"t": "tit", "x": "TÍTULO VII — DAS DISPOSIÇÕES FINAIS"}'::jsonb),
('law_12896', 145, '{"t": "art", "n": "Art. 112", "x": "Os órgãos de natureza militar ou de interesse policial-militar de entes públicos EXTERNOS à corporação observam limite de efetivo fixado por decreto do Governador.\n§1º Esse efetivo é controlado pela Diretoria de Gestão de Pessoas (DGP), que registra/fiscaliza/atualiza o quadro em atividade externa.\n§2º São órgãos externos de natureza militar/interesse militar: Gabinete Militar do Governador e do Vice-Governador; Gabinete do Presidente da Assembleia Legislativa; Gabinete do Presidente do TJ; Secretaria de Estado da Segurança Pública (SSP); Auditoria da Justiça Militar; DETRAN; Centro Integrado de Operação de Segurança/Pacto pela Paz/Corregedoria do Sistema de Segurança Pública; Gabinete de Segurança Institucional da Procuradoria-Geral de Justiça; Gabinete de Segurança Institucional do TCE; Diretoria de Segurança Institucional do TJ; Tribunal Regional Eleitoral; Defensoria Pública; Instituições de ensino básico estadual/municipal com gestão compartilhada com a PM.", "s": "Lista atualizada dos órgãos externos “de fora” onde PM pode servir sem virar civil — quem CONTROLA esse efetivo externo é a DGP (Diretoria de Gestão de Pessoas), detalhe que adora ser trocado em prova."}'::jsonb),
('law_12896', 146, '{"t": "art", "n": "Art. 113", "x": "Fica em EXTINÇÃO o antigo Quadro de Oficiais Especialistas (Lei nº 3.826/1976: Motomecanização, Comunicação, Armamento). Os oficiais podem optar por permanecer nesse quadro OU, em até 180 dias, ingressar no novo QOE (Lei Federal nº 14.751/2023).\n§1º Quem não optar mantém todos os direitos/garantias/prerrogativas anteriores e o exercício de funções.\n§2º Quem ingressar no novo QOE tem antiguidade regulada pelo art. 21 da Lei Federal nº 14.751/2023.\n§3º Vacância no posto inferior migra o cargo pro novo QOE, até a extinção total das especialidades antigas.", "s": "Prazo de opção pros oficiais especialistas antigos migrarem pro novo QOE: 180 dias."}'::jsonb),
('law_12896', 147, '{"t": "art", "n": "Art. 114", "x": "Ficam em EXTINÇÃO as Qualificações Policiais Militares Particulares de praças especialistas (QPMP 1, 3, 5 e 6). Os integrantes podem permanecer até a extinção total ou optar, em até 180 dias, por ingressar no novo QP.\n§1º Quem não optar mantém direitos/garantias/prerrogativas anteriores.\n§2º Antiguidade na graduação regulada pelo art. 21 da Lei nº 6.513/1995 (Estatuto da PM/MA).\n§3º Vacância migra o cargo pro novo QP, até extinção total.", "s": "Mesmo prazo de 180 dias, agora pras QUALIFICAÇÕES de PRAÇAS especialistas migrarem pro novo QP. Repare: a antiguidade aqui usa regra do ESTATUTO (Lei 6.513/95), diferente do art. 113 que usa a lei federal."}'::jsonb),
('law_12896', 148, '{"t": "art", "n": "Art. 115", "x": "O Governador, por proposta do Comandante-Geral, pode dispor por DECRETO sobre criação/transformação/extinção/denominação/localização/estruturação dos órgãos de direção/apoio/execução, observados a organização básica e o limite de efetivo desta Lei.\nParágrafo único - Pode ocorrer por remanejamento/redistribuição/criação/transformação de cargos VAGOS, desde que sem aumento de despesa.", "s": "Reorganizar por dentro é fácil (decreto do Governador), mas SEM aumentar efetivo total nem despesa — precisa de LEI pra isso."}'::jsonb),
('law_12896', 149, '{"t": "art", "n": "Art. 116", "x": "Os atos de interesse institucional/vida funcional dos integrantes serão publicados no Boletim Geral (BG) e, quando sigilosos, no Boletim Reservado (BR).", "s": "Boletim Geral (público) x Boletim Reservado (sigiloso) — meios oficiais de divulgação interna."}'::jsonb),
('law_12896', 150, '{"t": "art", "n": "Art. 117", "x": "Os cargos vagos decorrentes do novo efetivo serão preenchidos GRADATIVAMENTE, por concurso/inclusão/promoção, conforme necessidade do serviço, disponibilidade orçamentária e cronograma de implementação.", "s": "O novo efetivo (14.290) não é preenchido de uma vez — é GRADATIVO."}'::jsonb),
('law_12896', 151, '{"t": "art", "n": "Art. 118", "x": "Permanecem em vigor os regulamentos que disciplinam órgãos/unidades desta Lei, desde que não colidam com ela, até que novas normas sejam expedidas.", "s": "Regulamentos antigos continuam valendo no que não contrariar esta nova lei."}'::jsonb),
('law_12896', 152, '{"t": "art", "n": "Art. 119", "x": "É assegurado aos atuais Coronéis SEM o Curso de Comando e Estado-Maior (CCEM), pelo prazo de 3 anos da vigência desta Lei, o direito de assumir Comandante-Geral, Subcomandante-Geral, Chefe do EMG, Corregedor-Geral e demais funções de comando/chefia/direção do posto de Coronel.\n§1º Passado o prazo, esses Coronéis ficam IMPEDIDOS de exercer tais funções.\n§2º Consideram-se equivalentes os cursos já existentes na PM aos previstos na Lei Federal nº 14.751/2023 (art. 31).", "s": "Regra de transição CRUCIAL: Coronel sem CCEM tem só 3 ANOS pra continuar podendo assumir cargos de topo — depois disso, sem o curso, NÃO pode mais."}'::jsonb),
('law_12896', 153, '{"t": "art", "n": "Art. 120", "x": "A função de fiscal de contrato, na corporação, é exercida por servidor CIVIL efetivo lotado no órgão/unidade ou, na ausência deste, por policial militar com capacidade técnica.", "s": "Fiscal de contrato: preferencialmente CIVIL; só vira PM se não tiver civil disponível."}'::jsonb),
('law_12896', 154, '{"t": "art", "n": "Art. 121", "x": "Os arts. 10 e 20 da Lei nº 3.743/1975 passam a vigorar com nova redação: promoção de oficiais por antiguidade/merecimento em proporções fixas por posto (ex.: Coronel = 5 por merecimento e 1 por antiguidade; Tenente-Coronel e Major = 1 e 1; Capitão e 1º Tenente = 5 por antiguidade e 1 por merecimento; 2º Tenente = todas por antiguidade); e as promoções anuais passam a ocorrer em MARÇO, AGOSTO e DEZEMBRO (antes eram só 2 datas).", "s": "PEGADINHA de atualização: antes eram só 2 promoções/ano; agora, com a Lei 12.896/2026, passam a ser 3 datas: MARÇO, AGOSTO e DEZEMBRO. E pra Coronel, o merecimento pesa muito mais (5 vagas) que a antiguidade (1 vaga) — o contrário do 2º Tenente, que é só por antiguidade."}'::jsonb),
('law_12896', 155, '{"t": "art", "n": "Art. 122", "x": "O caput do art. 78 da Lei nº 6.513/1995 (Estatuto da PM/MA) passa a vigorar com nova redação, e é acrescido o §6º: as promoções continuam pelos critérios de antiguidade/merecimento/tempo de serviço/bravura/post mortem/completar requisitos de transferência, mas agora mediante ato do GOVERNADOR (para oficiais) e do COMANDANTE-GERAL (para praças); e o novo §6º cria o fluxo: as Comissões analisam/classificam/recomendam → processos vão ao Comandante-Geral (aprecia e lavra os atos) → seguem ao Secretário de Segurança Pública (analisa e aprova) → que encaminha os atos de OFICIAIS ao Governador, e devolve os atos de PRAÇAS ao Comandante-Geral para assinatura.", "s": "Fluxo de assinatura da promoção (decore a ordem): Comissão → Comandante-Geral → Secretário de Segurança Pública → daí se BIFURCA: Oficial vai pro GOVERNADOR assinar; Praça VOLTA pro Comandante-Geral assinar."}'::jsonb),
('law_12896', 156, '{"t": "art", "n": "Art. 123", "x": "O art. 79-A da Lei nº 6.513/1995 passa a vigorar com nova redação: “As promoções dos militares estaduais ocorrerão anualmente nos meses de março, agosto e dezembro.”", "s": "ATUALIZAÇÃO IMPORTANTE: o velho art. 79-A do Estatuto (Lei 6.513/95) dizia só agosto e dezembro; agora, com esta lei de 2026, passa a ser MARÇO, AGOSTO e DEZEMBRO — 3 datas por ano."}'::jsonb),
('law_12896', 157, '{"t": "art", "n": "Art. 124", "x": "Ficam revogadas cerca de 39 leis e dispositivos legais anteriores relacionados à criação/reestruturação de unidades e órgãos da PMMA ao longo do tempo (entre elas as Leis nº 4.570/1984, 4.716/1986, 5.657/1993, 9.043/2009, 9.658/2012, 9.795/2013, 10.131/2014 art. 4º, 10.155/2014, 10.212/2015, 10.223/2015, 10.669/2017, 10.823/2018 arts. 1º a 11, 10.938/2018, 11.346/2020 arts. 1º a 10, 11.660/2022 e 11.736/2022 dispositivos específicos, 11.813/2022 arts. 2º e 3º, 12.415/2024, entre outras).", "s": "Não precisa decorar a lista inteira — o que importa saber é que esta Lei 12.896/2026 CONSOLIDA e revoga dezenas de leis avulsas anteriores que criavam unidades uma por uma."}'::jsonb),
('law_12896', 158, '{"t": "art", "n": "Art. 125", "x": "Esta Lei entra em vigor na data de sua publicação.", "s": "Vigência: na PUBLICAÇÃO — mesma regra clássica do Estatuto de 1995."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('law_10230', 0, '{"t": "tit", "x": "LEI Nº 10.230, DE 23 DE ABRIL DE 2015 — Organização Básica do Corpo de Bombeiros Militar do Maranhão (CBMMA)"}'::jsonb),
('law_10230', 1, '{"t": "art", "n": "Ementa", "x": "Dispõe sobre a Organização Básica do Corpo de Bombeiros Militar do Maranhão e dá outras providências.", "s": "Esta é a lei estadual “irmã” da Lei 12.896/2026 — só que em vez de organizar a PMMA, organiza o CBMMA. Repare na data: 2015, bem mais antiga que a 12.896/2026 (2026) e a 14.751/2023 (2023) — ou seja, o CBMMA ainda não passou por uma atualização tão recente quanto a PMMA."}'::jsonb),
('law_10230', 2, '{"t": "tit", "x": "TÍTULO I — DA DESTINAÇÃO, COMPETÊNCIA E SUBORDINAÇÃO"}'::jsonb),
('law_10230', 3, '{"t": "cap", "x": "CAPÍTULO I — DA DESTINAÇÃO"}'::jsonb),
('law_10230', 4, '{"t": "art", "n": "Art. 1º", "x": "O Corpo de Bombeiros Militar do Maranhão (CBMMA), força auxiliar e reserva do Exército, órgão central do Sistema Estadual de Proteção e Defesa Civil, é instituição permanente e regular, organizada com base na hierarquia e disciplina, nos termos dos §§5º e 6º do art. 144 da Constituição Federal, do art. 116 da Constituição do Estado do Maranhão e do Decreto-Lei nº 667, de 2 de julho de 1969, alterado pelo Decreto-Lei nº 2010, de 12 de janeiro de 1983, tem a sua organização básica definida nos termos desta Lei.", "s": "Mesmo DNA constitucional da PMMA: força auxiliar e reserva do EXÉRCITO, hierarquia e disciplina, art. 144 §§5º/6º da CF. A diferença é que aqui o CBMMA é também ÓRGÃO CENTRAL do Sistema Estadual de Proteção e Defesa Civil — isso não existe na PMMA."}'::jsonb),
('law_10230', 5, '{"t": "cap", "x": "CAPÍTULO II — DA COMPETÊNCIA"}'::jsonb),
('law_10230', 6, '{"t": "art", "n": "Art. 2º", "x": "Ao Corpo de Bombeiros Militar do Maranhão, órgão com competência para atuar no âmbito do Estado, cabe: I- desenvolver a política Estadual de Proteção de Defesa Civil, nas ações de proteção da incolumidade e do socorro das pessoas em caso de infortúnio ou de calamidade; II- prestar socorro nos casos de inundações, alagamentos, deslizamentos, desabamentos e/ou catástrofes, sempre que houver ameaça de destruição de haveres, vítimas ou pessoas em iminente perigo de vida; III- exercer atividades de polícia administrativa para os serviços de Segurança Contra Incêndio e Pânico e de Salvamento, podendo, por meio de estudos, vistorias, análises, planejamento, fiscalização e controle de edificações, embargar, interditar obras, serviços, habitações e locais de diversões públicas que não oferecerem condições de segurança e de funcionamento; IV- controlar e fiscalizar a formação de guarda-vidas em meio aquático; V- realizar serviços de busca e salvamento de pessoas, animais, bens e haveres; VI- realizar prevenção no meio aquático e serviço de guarda-vidas; VII- realizar serviços de atendimento e transporte pré-hospitalar em vias e logradouros públicos; VIII- proceder à perícia de incêndios, bem como o controle de edificações e seus projetos, visando à observância de requisitos técnicos contra incêndio e outros riscos, prevenindo e extinguindo incêndios urbanos e florestais; IX- desenvolver pesquisas científicas em seu campo de atuação funcional e ações educativas de prevenção de incêndios, socorros de urgência, pânico coletivo e proteção ao meio ambiente, bem como ações de proteção e promoção do bem-estar da coletividade e dos direitos, garantias e liberdades do cidadão, estimulando o respeito à cidadania, por meio de ações de natureza preventiva e educacional ou por meio de convênios; X- celebrar e manter intercâmbio sobre os assuntos de interesse de suas atribuições com órgãos congêneres de outras unidades da Federação ou Países, além de exercer outras atividades necessárias ao cumprimento de sua competência por meio de convênios.", "s": "Lista de competências bem mais “operacional” que a da PMMA: enchente, deslizamento, guarda-vidas, perícia de incêndio, atendimento pré-hospitalar. Pegadinha útil: o inciso III fala em “polícia ADMINISTRATIVA” (fiscalização/embargo de obra), não “polícia judiciária” — isso é tratado depois, no art. 11 da Lei 14.751/2023."}'::jsonb),
('law_10230', 7, '{"t": "art", "n": "Art. 3º", "x": "O Corpo de Bombeiros Militar do Maranhão, por meio de seu pessoal, poderá exercer atividades de caráter operacional bombeiro-militar e de assessoramento junto: I- ao Gabinete do Governador; II- ao Gabinete Militar do Governador; III- ao Gabinete do Vice-Governador; IV- ao Gabinete do Presidente da Assembleia Legislativa; V- ao Gabinete do Presidente do Tribunal de Justiça; VI- ao Gabinete do Presidente do Tribunal de Contas do Estado; VII- ao Gabinete do Secretário de Segurança Pública; VIII- à Auditoria da Justiça Militar; IX- ao Gabinete do Comandante-Geral, à disposição de convênios de caráter técnico-operacional bombeiro-militar; X- às Coordenadorias Municipais de Proteção e Defesa Civil, na função de Secretário Municipal de Proteção e Defesa Civil e/ou Coordenador Municipal de Proteção e Defesa Civil; XI- à Secretaria Nacional de Segurança Pública; XII- à Secretaria Nacional de Proteção e Defesa Civil; e XIII- ao Congresso Nacional.", "s": "Lista de “onde o bombeiro pode ser destacado para assessorar” — os 3 Poderes estaduais (Executivo, Legislativo, Judiciário) + Tribunal de Contas + até o Congresso Nacional. Não precisa decorar todos os 13 incisos, só saber que existe esse leque amplo de assessoramento."}'::jsonb),
('law_10230', 8, '{"t": "art", "n": "Art. 4º", "x": "O Corpo de Bombeiros Militar do Maranhão integra a estrutura da Secretaria de Estado da Segurança Pública como Unidade Executora Descentralizada, com as características seguintes: I- custeio de execução dos seus programas por dotações globais, consignadas no orçamento do Estado; II- créditos diretos para o custeio dos seus programas específicos; III- manutenção de contabilidade própria; IV- aquisição direta de materiais e equipamentos específicos; V- planejamento e execução das atividades pertinentes à administração de pessoal Bombeiro Militar; e VI- exercício, por órgão próprio, das atividades pertinentes à administração geral e programação orçamentária.", "s": "Decore o termo exato: “Unidade Executora Descentralizada” da Secretaria de Segurança Pública — não é um órgão totalmente independente, mas tem autonomia de orçamento, contabilidade e compras próprias."}'::jsonb),
('law_10230', 9, '{"t": "cap", "x": "CAPÍTULO III — DA SUBORDINAÇÃO"}'::jsonb),
('law_10230', 10, '{"t": "art", "n": "Art. 5º", "x": "O Comandante-Geral do Corpo de Bombeiros Militar do Maranhão subordina-se ao Governador do Estado, Comandante Superior da Corporação.\nParágrafo único. O Comando e a operacionalidade do Corpo de Bombeiros Militar do Maranhão é de competência do Comandante-Geral da Corporação por meio dos órgãos de direção, apoio e execução, ficando vinculado à Secretaria de Estado da Segurança Pública, órgão responsável pela Segurança Pública no Estado.", "s": "Mesma lógica da PMMA: subordinação SUPERIOR ao Governador (Comandante Superior), mas o comando OPERACIONAL do dia a dia é do Comandante-Geral, vinculado à Secretaria de Segurança Pública."}'::jsonb),
('law_10230', 11, '{"t": "art", "n": "Art. 6º", "x": "A administração e o comando da Corporação são de competência do Comandante-Geral.", "s": "Resume o artigo anterior numa frase só: administração + comando = Comandante-Geral."}'::jsonb),
('law_10230', 12, '{"t": "tit", "x": "TÍTULO II — ORGANIZAÇÃO BÁSICA"}'::jsonb),
('law_10230', 13, '{"t": "cap", "x": "CAPÍTULO I — DA ESTRUTURA GERAL"}'::jsonb),
('law_10230', 14, '{"t": "art", "n": "Art. 7º", "x": "O Corpo de Bombeiros Militar do Maranhão tem a seguinte estrutura: I- órgãos de direção; II- órgãos de apoio; III- órgãos de execução.\n§1º Os órgãos de direção são encarregados do comando e da administração geral, incumbindo-se do planejamento visando à organização da corporação em todos os níveis com atribuições, ainda, de acionar, coordenar, controlar e fiscalizar a atuação dos órgãos de apoio e de execução.\n§2º Os órgãos de apoio atendem às necessidades das atividades-meio da Corporação.\n§3º Os órgãos de execução, constituídos pelos comandos operacionais e pelas unidades e subunidades operacionais, realizam as atividades-fim da Corporação, cumprindo as missões a eles destinadas.\n§4º Os órgãos de direção, de apoio e de execução, constituídos por Unidades de Bombeiros Militar (UBM), subdividem-se em Unidades Administrativas (UA) e Unidades Operacionais (UO), ficando organizados por: I- Unidade Administrativa: 1. Diretorias e Coordenadorias; 2. Centros; 3. Departamentos; 4. Seções; 5. Subseções. II- Unidade Operacional: 1. Comandos Operacionais do Corpo de Bombeiros; 2. Batalhões de Bombeiros Militar e Batalhões de Bombeiros Especializados; 3. Companhias Independentes de Bombeiros Militar, Companhias Independentes Especializadas e Departamentos; 4. Companhias de Bombeiros Militar e Seções; 5. Posto de Bombeiros Militar e Subseções.\n§5º As Diretorias, os Comandos Operacionais e a Coordenadoria Estadual de Proteção e Defesa Civil terão suas funções previstas para os cargos de Coronéis do Quadro de Combatentes da ativa da Corporação. As Coordenadorias Médica de Saúde e de Serviços Odontológicos terão suas funções previstas para os cargos de Coronéis dos Quadros de Saúde Médicos e Dentistas da ativa da Corporação, respectivamente.\n§6º Os Centros, os Batalhões de Bombeiros Militar e Batalhões de Bombeiros Especializados terão suas funções previstas para os cargos de Tenentes-Coronéis dos respectivos Quadros de Pessoal Bombeiro Militar.\n§7º Os Departamentos, os Subcomandos dos Batalhões de Bombeiros Militar e Batalhões de Bombeiros Especializados e os Comandos das Companhias Independentes de Bombeiros Militar terão suas funções previstas para os cargos de Majores dos respectivos Quadros de Pessoal Bombeiro Militar.\n§8º As Seções, os Subcomandos das Companhias Independentes de Bombeiros Militares e os Comandos das Companhias de Bombeiros Militar, exceto as Chefias das Seções do Estado Maior-Geral, terão suas funções previstas para os cargos de Capitães dos respectivos Quadros de Pessoal Bombeiro Militar.\n§9º As Subseções e Comandos dos Postos de Bombeiros Militar, exceto as Chefias das Seções do Estado Maior-Geral, terão suas funções previstas para os cargos de 1º Tenente ou 2º Tenente dos respectivos Quadros de Pessoal Bombeiro Militar.\n§10. O Plano de Emprego e as Normas Gerais de Ações de cada UBM dar-se-ão por meio de normas internas baixadas pelo Comando da Corporação.", "s": "Mesma estrutura de 3 (não 5!) níveis — Direção, Apoio, Execução — diferente da Lei 14.751/2023 nacional, que já prevê 5 (incluindo Assessoramento e Correição separados). Isso é porque esta lei do CBMMA é de 2015, anterior à Lei nacional de 2023 — ainda não foi atualizada pra incorporar os 5 órgãos. Decore também a escada de patentes por nível: Diretoria/Comando Operacional = Coronel; Centro/Batalhão = Tenente-Coronel; Departamento/Subcomando = Major; Seção/Comando de Companhia = Capitão; Subseção/Posto = 1º ou 2º Tenente."}'::jsonb),
('law_10230', 15, '{"t": "cap", "x": "CAPÍTULO II — DA CONSTITUIÇÃO E DAS COMPETÊNCIAS DOS ÓRGÃOS DE DIREÇÃO"}'::jsonb),
('law_10230', 16, '{"t": "art", "n": "Art. 8º", "x": "Os Órgãos de Direção ficam constituídos por: I- Alto Comando; II- Estado-Maior-Geral (EMG); III- Diretorias; IV- Ajudância-Geral; V- Controladoria; VI- Ouvidoria; VII- Gabinete do Comandante-Geral; VIII- Comissões e Assessorias.\n§1º A função de Comandante-Geral será exercida por Coronel do Quadro de Oficiais Combatentes escolhido dentre os Oficiais da ativa da Corporação, possuidor do Curso de Formação de Oficial Bombeiro Militar e do Curso Superior de Bombeiro Militar ou equivalente, por meio de ato de nomeação do Governador do Estado, e, sempre que a escolha não recair no Coronel BM mais antigo da corporação, o escolhido terá precedência funcional sobre os demais Oficiais.\n§2º A função de Comandante Adjunto será exercida por Coronel do Quadro de Oficiais Combatentes escolhido dentre os Oficiais da ativa da Corporação, possuidor do Curso de Formação de Oficial Bombeiro Militar e do Curso Superior de Bombeiro Militar ou equivalente, por meio de ato de nomeação do Governador do Estado, sendo que esta função confere ao titular precedência funcional sobre os demais Oficiais, exceto ao Comandante-Geral.\n§3º Ao Comandante Adjunto, substituto do Comandante-Geral nos seus afastamentos, ausências e impedimentos legais, cabe-lhe a orientação, a coordenação e a fiscalização dos órgãos da Corporação e da implementação das políticas definidas pelo Comando Geral da Corporação.\n§4º O Comandante Adjunto é o responsável pela aplicação da disciplina, dentro de sua esfera de competência, pela fiscalização do funcionamento dos órgãos internos, desde sua administração ao seu emprego operacional.", "s": "Decore a lista dos 8 órgãos de direção (Alto Comando, EMG, Diretorias, Ajudância-Geral, Controladoria, Ouvidoria, Gabinete do Comandante-Geral, Comissões e Assessorias). E o requisito do Comandante-Geral: Coronel do Quadro COMBATENTE (não qualquer quadro), com Curso de Formação de Oficial BM + Curso Superior de Bombeiro Militar, nomeado pelo Governador."}'::jsonb),
('law_10230', 17, '{"t": "sec", "x": "Seção I — Do Alto Comando"}'::jsonb),
('law_10230', 18, '{"t": "art", "n": "Art. 9º", "x": "O Alto-Comando tem por finalidade opinar, propor e estudar sobre: I- políticas de gestão e estratégia da Corporação; II- gestão de planos e programas oriundos do plano diretor da Corporação; III- outras matérias que sejam propostas pelo Comandante-Geral.\n§1º O Alto-Comando, órgão consultivo, presidido pelo Comandante-Geral, será composto por membros natos e efetivos, sendo os membros natos os que exercem as seguintes funções no âmbito da corporação: I- Comandante Adjunto/Chefe do EMG; II- Subchefe do EMG; III- Coordenador Estadual de Proteção e Defesa Civil.\n§2º Os membros efetivos, designados pelo Presidente do Alto Comando, poderão ser Oficiais Combatentes que exerçam funções de Diretores e que tenham qualificações específicas relacionadas às atribuições do Alto Comando.", "s": "Alto-Comando é órgão CONSULTIVO (só opina/propõe, não executa), presidido pelo Comandante-Geral. Membros NATOS (automáticos, pelo cargo): Comandante Adjunto/Chefe do EMG, Subchefe do EMG e Coordenador Estadual de Proteção e Defesa Civil."}'::jsonb),
('law_10230', 19, '{"t": "sec", "x": "Seção II — Do Estado-Maior Geral"}'::jsonb),
('law_10230', 20, '{"t": "art", "n": "Art. 10", "x": "O Estado-Maior Geral é o órgão de direção geral, responsável pelo estudo, planejamento, coordenação, fiscalização e controle de todas as atividades da Corporação, constituindo o órgão central do sistema de planejamento administrativo, operacional e orçamentário, encarregado da elaboração de diretrizes e ordens do Comando, que acionam os órgãos de direção, de apoio e de execução, no cumprimento de suas atividades e será exercido, cumulativamente, pelo Comandante Adjunto do CBMMA.", "s": "Pegadinha clássica: o EMG não tem um Chefe separado em tempo integral — a chefia é exercida CUMULATIVAMENTE pelo Comandante Adjunto (a mesma pessoa acumula os dois papéis)."}'::jsonb),
('law_10230', 21, '{"t": "art", "n": "Art. 11", "x": "O Estado-Maior-Geral compreende: I- Chefe do Estado-Maior-Geral; II- Subchefe do Estado-Maior-Geral; III- Secretaria; IV- Seções e Subseções: a) 1ª Seção (BM/1): assuntos relativos a pessoal e legislação; b) 2ª Seção (BM/2): assuntos relativos à legislação técnica, pesquisa técnica, perícias e prevenção; c) 3ª Seção (BM/3): assuntos relativos a ensino, à instrução, a operações, comunicações e doutrina de emprego; d) 4ª Seção (BM/4): assuntos relativos à modernização administrativa, material operacional, armamento, estatística, suprimento e orçamento; e) 5ª Seção (BM/5): assuntos relativos às relações públicas, ação comunitária e comunicação social.\n§1º O Chefe do EMG é o responsável superior pela elaboração das diretrizes e ordens do Comando, pelos trabalhos desenvolvidos pelo EMG, desde seu planejamento à sua aplicação técnica.\n§2º As Chefias das Seções do Estado-Maior-Geral terão suas funções exercidas pelos cargos de Tenentes-Coronéis do Quadro de Combatentes do CBMMA.\n§3º As Chefias das Subseções do Estado-Maior-Geral terão suas funções exercidas pelos cargos de Majores e de Capitães do Quadro de Combatentes do CBMMA.\n§4º A Chefia da Secretaria do Estado-Maior-Geral será responsável pelo exame, controle, preparação e demais atos administrativos.", "s": "Decore as 5 Seções do EMG por número (BM/1 a BM/5): 1=pessoal/legislação, 2=legislação técnica/perícia/prevenção, 3=ensino/instrução/operações, 4=modernização/material/orçamento, 5=relações públicas/comunicação social. É basicamente o mesmo padrão de Estado-Maior usado em outras forças militares."}'::jsonb),
('law_10230', 22, '{"t": "art", "n": "Art. 12", "x": "A função de Subchefe do Estado-Maior-Geral será exercida por Coronel da ativa do Quadro de Combatentes, substituto do Chefe do Estado-Maior-Geral, quando este estiver exercendo o cargo de Comandante-Geral interino e/ou em outros afastamentos legais, e, a função de Subchefe do EMG confere ao titular precedência funcional sobre os demais Oficiais, exceto ao Comandante-Geral e ao Comandante Adjunto.", "s": "Cadeia de substituição: Comandante-Geral → (ausência) Comandante Adjunto/Chefe do EMG → (ausência deste) Subchefe do EMG."}'::jsonb),
('law_10230', 23, '{"t": "sec", "x": "Seção III — Das Diretorias"}'::jsonb),
('law_10230', 24, '{"t": "art", "n": "Art. 13", "x": "Às Diretorias, órgãos de direção, organizadas sob a forma de sistema, compete realizar o planejamento, a orientação, o controle, a coordenação, a fiscalização e a execução das atividades, dos programas e dos planos relativos às estratégias setoriais específicas e ficam organizadas por: I- Diretoria de Pessoal; II- Diretoria de Finanças; III- Diretoria de Ensino e Pesquisa; IV- Diretoria de Apoio Logístico; V- Diretoria de Atividades Técnicas; VI- Diretoria de Inteligência; VII- Diretoria de Planejamento e Modernização — cada uma com seus próprios departamentos e seções internas (ex.: a de Pessoal tem Recursos Humanos e Assistência Psicossocial; a de Ensino tem a Academia de Bombeiro Militar e os Colégios Militares; a de Apoio Logístico tem o Centro de Suprimento e Manutenção).", "s": "7 Diretorias — decore pelo nome, a função geralmente é óbvia pelo título (Pessoal, Finanças, Ensino e Pesquisa, Apoio Logístico, Atividades Técnicas, Inteligência, Planejamento e Modernização). A Academia de Bombeiro Militar e os Colégios Militares ficam dentro da Diretoria de Ensino e Pesquisa."}'::jsonb),
('law_10230', 25, '{"t": "art", "n": "Art. 14 a Art. 19 (resumo)", "x": "§1º a §7º do art. 13 detalham a competência de cada Diretoria (Pessoal: pessoal e assistência social/religiosa; Finanças: administração financeira/orçamento/contabilidade; Ensino e Pesquisa: formação/aperfeiçoamento/especialização; Apoio Logístico: suprimento/material/viaturas; Atividades Técnicas: prevenção/vistorias/pareceres técnicos; Inteligência: assessoramento em informação e contrainteligência; Planejamento e Modernização: orçamento, projetos e TI).\nArt. 14 — Ajudância-Geral: subordinada ao Comandante Adjunto, publica atos administrativos e cuida das instalações do Quartel do Comando Geral; organizada por Seção de Administração e Expediente, Companhia de Guarda/Comando/Serviços e Banda de Música.\nArt. 15 — Controladoria: órgão de assessoramento e consultoria do Comando Geral, controle financeiro/contábil/orçamentário/patrimonial/operacional.\nArt. 16 — Ouvidoria: atende cidadãos em última instância, recebe reclamações e denúncias.\nArt. 17 — Gabinete do Comandante-Geral: assistência geral e assessoramento, com Ajudantes-de-Ordens.\nArt. 18 — Comissões (permanentes ou eventuais), incluindo a Comissão Setorial de Licitação, a Comissão de Promoção de Oficiais (CPO) e a Comissão de Promoção de Praças (CPP).\nArt. 19 — Assessorias: suporte técnico/especializado ao Comando, podendo ter bombeiros militares ou civis.", "s": "Resumo em bloco pra não decorar artigo por artigo: cada Diretoria tem uma competência-tema (ver lista acima); Ajudância-Geral = “zeladoria” do Quartel-General + Banda de Música; Controladoria = fiscaliza dinheiro/patrimônio; Ouvidoria = canal do cidadão; Gabinete = assessoria geral; Comissões = licitação (CSL) e promoções (CPO de oficiais, CPP de praças)."}'::jsonb),
('law_10230', 26, '{"t": "cap", "x": "CAPÍTULO III — DA CONSTITUIÇÃO E DAS COMPETÊNCIAS DOS ÓRGÃOS DE APOIO"}'::jsonb),
('law_10230', 27, '{"t": "art", "n": "Art. 20 e Art. 21", "x": "Art. 20 — Aos órgãos de apoio compete dar suporte ao Comandante-Geral no cumprimento da missão da Corporação.\nArt. 21 — Constituem Órgãos de Apoio: I- a Coordenadoria Médica de Saúde; II- a Coordenadoria de Serviços Odontológicos; III- o Centro de Operações e Comunicações; IV- a Academia de Bombeiros Militar; V- o Centro de Suprimento e Manutenção; VI- o Colégio Militar.", "s": "6 órgãos de apoio — repare que a Academia de Bombeiros Militar e o Colégio Militar aparecem aqui como ÓRGÃOS DE APOIO, mas também estão vinculados à Diretoria de Ensino (art. 13) — são órgãos de apoio na estrutura de nível 1 (art. 7º), mas subordinados a uma Diretoria no dia a dia."}'::jsonb),
('law_10230', 28, '{"t": "art", "n": "Art. 22 e Art. 23", "x": "Art. 22 — A Coordenadoria Médica de Saúde, subordinada ao Comandante Adjunto, cuida da assistência médica, farmacêutica e sanitária da família bombeiro militar; tem Junta Médica de Saúde (JMS) para inspeções de saúde, pareceres para reserva/reforma/ingresso/cursos/promoções.\nArt. 23 — A Coordenadoria de Serviços Odontológicos, também subordinada ao Comandante Adjunto, cuida da assistência odontológica curativa e preventiva ao bombeiro militar e dependentes.", "s": "Saúde e Odontologia são coordenadorias SEPARADAS, ambas subordinadas ao Comandante Adjunto (não ao Comandante-Geral diretamente). A Junta Médica de Saúde (JMS) é quem dá o parecer técnico pra reforma/reserva por incapacidade."}'::jsonb),
('law_10230', 29, '{"t": "art", "n": "Art. 24 a Art. 27", "x": "Art. 24 — Centro de Operações e Comunicações: planejamento/coordenação/execução das atividades operacionais e de comunicações, pesquisas tecnológicas, perícias e prevenção de incêndios, e planejamento de Proteção e Defesa Civil na sua área.\nArt. 25 — Academia de Bombeiros Militar: organiza cursos e estágios, controla as atividades de ensino da Corporação.\nArt. 26 — Centro de Suprimento e Manutenção: suprimento e manutenção de viaturas, materiais e equipamentos.\nArt. 27 — Colégio Militar: desenvolvimento educacional dos dependentes de bombeiros militares e da sociedade civil.", "s": "Repare que o Colégio Militar do CBMMA atende não só dependentes de bombeiros, mas também a SOCIEDADE CIVIL em geral — é um detalhe que costuma ser cobrado como pegadinha (“só atende filhos de militares” estaria ERRADO)."}'::jsonb),
('law_10230', 30, '{"t": "cap", "x": "CAPÍTULO IV — DA CONSTITUIÇÃO E DAS COMPETÊNCIAS DOS ÓRGÃOS DE EXECUÇÃO"}'::jsonb),
('law_10230', 31, '{"t": "art", "n": "Art. 28", "x": "Os órgãos de execução do Corpo de Bombeiros Militar do Maranhão, constituído das Unidades e Subunidades Operacionais, são classificados segundo a natureza dos serviços que prestam e as suas peculiaridades, ficam organizados por: I- Comando Operacional do Corpo de Bombeiros (COCB); II- Comando Operacional de Corpo de Bombeiros Especializado; III- Batalhão de Bombeiros Militar (BBM); IV- Batalhão de Bombeiros Militar Especializado; V- Batalhão de Bombeiros Marítimo (BBMar); VI- Batalhão de Bombeiros de Emergências Médicas (BBEM); VII- Batalhão de Bombeiros de Busca e Salvamento (BBS); VIII- Batalhão de Bombeiros Ambiental (BBA); IX- Companhia Independente de Bombeiros Militar (CIBM); X- Companhia Independente Especializada de Bombeiros Militar (CIEBM); XI- Posto de Bombeiros Militar (PBM).\n§1º As Unidades Operacionais em nível de Batalhão de Bombeiros poderão ser estruturadas em até 3 Companhias, e estas podem ter quantos Postos de Bombeiros forem necessários ao atendimento da região, conforme o Plano de Emprego.\n§2º As Unidades Operacionais em nível de Companhia Independente de Bombeiros poderão ser estruturadas em até três postos de bombeiros.\n§3º As Unidades Operacionais Especializadas poderão ter estruturas diferenciadas que atendam às suas características, desde que previstas em lei específica.\n§4º Ao Batalhão de Bombeiros Militar e ao Batalhão de Bombeiros Militar Especializado compete o planejamento estratégico, coordenação e emprego de unidade/subunidade operacionais: prevenção, guarda e segurança, combate a incêndio, busca e salvamento, atendimento pré-hospitalar, proteção e defesa civil, engenharia de segurança contra incêndio e pânico, entre outras.\n§5º Ao Batalhão de Bombeiros Marítimo compete prevenção, busca, mergulho de resgate, guarda-vidas e salvamento aquático.\n§6º Ao Batalhão de Bombeiros de Emergências Médicas compete socorros de urgência/emergência, atendimento pré-hospitalar.\n§7º Ao Batalhão de Bombeiros de Busca e Salvamento compete resgate, busca, salvamento terrestre e em altura.\n§8º Ao Batalhão de Bombeiros Ambiental compete prevenção e combate a incêndios florestais e questões ambientais.\n§9º A Companhia Independente de Bombeiros Militar e a Especializada têm competência parecida com a do Batalhão, mas numa área de menor abrangência.\n§10. O Posto de Bombeiros Militar é a menor unidade operacional, com efetivo reduzido, subordinado a uma Companhia de um Batalhão ou a uma Companhia Independente.", "s": "Decore a sigla de cada Batalhão ESPECIALIZADO e sua missão: BBMar=marítimo/mergulho, BBEM=emergências médicas, BBS=busca e salvamento (terrestre/altura), BBA=ambiental/incêndio florestal. E a hierarquia de tamanho: Comando Operacional > Batalhão (até 3 Companhias) > Companhia (até 3 Postos) > Posto de Bombeiros (a menor unidade)."}'::jsonb),
('law_10230', 32, '{"t": "art", "n": "Art. 29", "x": "Aos Comandos Operacionais, denominação genérica dada às organizações bombeiros militar operacionais de mais alto escalão, subordinados ao Comandante Adjunto, compete a aplicação da disciplina, o planejamento estratégico, a coordenação e o emprego de unidade/subunidade operacionais (prevenção, combate a incêndio, busca e salvamento, atendimento pré-hospitalar, defesa civil, engenharia de segurança contra incêndio e pânico, entre outras), ficam organizados em 7 Comandos Operacionais de Área (COCB), cada um com sede numa microrregião e suas unidades subordinadas:\nI- COCB-1 (sede em São Luís, Aglomeração Urbana de São Luís): 1º BBM (Centro) com 3 Companhias (sede, Itaqui-Bacanga, Renascença); 2º BBM (CSU/COHAB) com 3 Companhias (sede, Turú, São Cristóvão/Tirirical); 1ª CIBM (São José de Ribamar); 2ª CIBM (Paço do Lumiar).\nII- Comando Operacional Especializado (COECB, sede em São Luís, atendimento em todo o Estado): Batalhão de Bombeiros Marítimo, Batalhão de Emergências Médicas, Batalhão de Busca e Salvamento, Batalhão Ambiental, e a 1ª Companhia Independente Especializada (CIEBM) — todos na cidade de São Luís.\nIII- COCB-2 (sede em Itapecuru-Mirim): 3ª CIBM (Itapecuru-Mirim); 4ª CIBM (Barreirinhas); 5ª CIBM (Chapadinha).\nIV- COCB-3 (sede em Imperatriz): 3º BBM (Imperatriz, com Companhias em Imperatriz e Senador La Roque); 9º BBM (Estreito, com Companhias em Estreito, Porto Franco e Carolina); 6ª CIBM (Açailândia).\nV- COCB-4 (sede em Balsas): 4º BBM (Balsas, com Companhias em Balsas, São Raimundo das Mangabeiras e Alto Parnaíba); 7ª CIBM (Grajaú); 8ª CIBM (São João dos Patos).\nVI- COCB-5 (sede em Caxias): 5º BBM (Caxias, com Companhias em Caxias e Codó); 7º BBM (Timon, com Companhias em Timon, Coelho Neto e Parnarama).\nVII- COCB-6 (sede em Bacabal): 6º BBM (Bacabal, com Companhias em Bacabal, Pedreiras e Peritoró); 9ª CIBM (Santa Inês); 10ª CIBM (Presidente Dutra); 11ª CIBM (Barra do Corda).\nVIII- COCB-7 (sede em Pinheiro): 8º BBM (Pinheiro, com Companhias em Pinheiro, São Bento e Cururupu); 12ª CIBM (Viana).\n§1º As circunscrições de cada comando e suas áreas de atuação serão definidas por meio do Plano de Emprego, nas Normas Gerais de Ações de cada UBM e nos limites impostos nesta Lei.\n§2º Os comandantes Operacionais exercerão as funções de coordenadores regionais de proteção e defesa civil em suas respectivas circunscrições, vinculados à Coordenadoria Executiva de Defesa Civil — EXCETO os comandantes das áreas 1 (COCB-1) e especializado (COECB).\n§3º Os Comandos Operacionais ficam organizados por Comandante + Seção de Administração + Centro de Operações Integradas de Segurança, e cada Batalhão/Companhia Independente tem sua própria estrutura interna (Subcomandante, Seções de Administração/Patrimônio/Finanças/Proteção e Defesa Civil/Operações, conforme o tipo de unidade).\n§4º As Companhias e os Postos serão localizados em pontos estratégicos para o atendimento operacional.\n§5º Os Batalhões localizados em São Luís (circunscrição do COCB-1) não têm Departamento de Atividades Técnicas próprio — essa competência fica a cargo da Diretoria de Atividades Técnicas.\n§6º O Quadro de Organização e Distribuição define as funções e a distribuição do efetivo por postos/graduações, conforme a Lei nº 7.764/2002 (efetivo do CBMMA).\n§7º A ativação das Unidades Operacionais é PROGRESSIVA, conforme as condições financeiras do Estado.", "s": "Não precisa decorar cidade por cidade — o que cai em prova é a ESTRUTURA: são 8 Comandos Operacionais ao todo (7 de área geográfica + 1 Especializado), cada um cobrindo uma microrregião do Estado, e o COCB-1 (São Luís) + o COECB (Especializado) são as DUAS exceções que NÃO se vinculam à Coordenadoria Executiva de Defesa Civil para fins de defesa civil (§2º) — todos os outros 6 comandos de área SIM se vinculam."}'::jsonb),
('law_10230', 33, '{"t": "tit", "x": "TÍTULO III — DO PESSOAL DO CORPO DE BOMBEIROS"}'::jsonb),
('law_10230', 34, '{"t": "cap", "x": "CAPÍTULO I — DO PESSOAL"}'::jsonb),
('law_10230', 35, '{"t": "art", "n": "Art. 30", "x": "O Quadro de Pessoal do Corpo de Bombeiros Militar do Maranhão fica definido nos termos seguintes: I- Quadros de Oficiais de Pessoal Ativo: a) Quadro de Oficiais Combatentes Bombeiros Militar (QOC); b) Quadro de Oficiais de Saúde Médicos Bombeiros Militar (QOSM); c) Quadro de Oficiais de Saúde Dentistas Bombeiros Militar (QOSD); d) Quadro de Oficiais Técnicos Bombeiros Militar (QOT); e) Quadro de Oficiais Administrativos Bombeiros Militar (QOA); f) Quadro de Oficiais Especialistas em Manutenção de Comunicação Bombeiros Militar (QOEMC); g) Quadro de Oficiais Especialistas em Manutenção em Motomecanização Bombeiros Militar (QOEMM); h) Quadro de Oficiais Especialistas Músicos Bombeiros Militar (QOEM); i) Quadro de Oficiais Auxiliares de Saúde (QOAS); j) Quadro de Oficiais Auxiliares de Odontologia (QOAO);\nII- Quadros de Praças de Pessoal Ativo: a) Quadro de Praças Combatentes Bombeiros Militar (QPBM-0); b) Quadro de Praças Especialistas Músicos Bombeiros Militar (QPBM-1); c) Quadro de Praças Especialistas Músico Corneteiros Bombeiros Militar (QPBM-1/Corneteiro); d) Quadro de Praças Especialistas Auxiliares de Saúde (QPBM-2); e) Quadro de Praças Especialistas Auxiliares de Odontologia (QPBM-3); f) Quadro de Praças Especialistas em Manutenção de Comunicação Bombeiros Militar (QPBM-4); g) Quadro de Praças Especialistas em Manutenção de Motomecanização Bombeiros Militar (QPBM-5); h) Quadro de Praças Especiais Bombeiros Militar (QPBME);\nIII- Pessoal Inativo: a) da Reserva Remunerada; b) da Reserva não Remunerada; c) Reformados.\nIV- Pessoal Civil.", "s": "MUITO mais quadros de oficiais/praças que a PMMA, por causa das especialidades técnicas do bombeiro (saúde, odontologia, comunicação, motomecanização, música). Decore pelo menos: QOC (oficiais combatentes), QOSM/QOSD (saúde médico/dentista), e que toda sigla de praça especialista começa com QPBM seguido de um número (0=combatente, 1=músico, 2=saúde, 3=odontologia, 4=comunicação, 5=motomecanização)."}'::jsonb),
('law_10230', 36, '{"t": "sec", "x": "Seção I — Dos Quadros de Oficiais"}'::jsonb),
('law_10230', 37, '{"t": "art", "n": "Art. 31 a Art. 41", "x": "Art. 31 — QOC: oficiais possuidores do Curso de Formação de Oficiais.\nArt. 32 — QOSM: profissionais médicos com formação superior reconhecida e registro no conselho de classe (edital pode exigir especialidades).\nArt. 33 — QOSD: profissionais odontólogos, mesma lógica do QOSM.\nArt. 34 — QOT: profissionais diplomados em áreas como Engenharia (Civil, Mecânica, Ambiental, Elétrica, Química), Psicologia, Pedagogia, Serviço Social, Fisioterapia, Farmácia-Bioquímica, Fonoaudiologia, Nutrição, Educação Física, Biblioteconomia, Arquitetura, Contabilidade, Direito, Administração, entre outras relacionadas às necessidades da Corporação.\nArt. 35 — QOA: Oficiais BM oriundos do quadro de Praças Combatentes, após aprovação no Curso de Habilitação de Oficiais Administrativos.\nArt. 36 — QOEM (músicos): Oficiais oriundos do QPBM-1 e QPBM-1/Corneteiro, após Curso de Habilitação de Oficiais Especialistas.\nArt. 37 — QOEMC (comunicação): Oficiais oriundos do QPBM-4, após Curso de Habilitação de Oficiais Especialistas.\nArt. 38 — QOEMM (motomecanização): Oficiais oriundos do QPBM-5, após Curso de Habilitação de Oficiais Especialistas.\nArt. 39 — QOAS (auxiliares de saúde): Oficiais oriundos do QPBM-2, após Curso de Habilitação de Oficiais Administrativos.\nArt. 40 — QOAO (auxiliares de odontologia): Oficiais oriundos do QPBM-3, após Curso de Habilitação de Oficiais Administrativos.\nArt. 41 — É VEDADA a transferência entre os Quadros de Oficiais Bombeiros Militar e o exercício de função de oficiais combatentes por oficiais de outros Quadros.", "s": "Padrão que se repete pra cada quadro ESPECIALISTA de oficial: sempre vem de um quadro de PRAÇA equivalente (QPBM-X), após um Curso de Habilitação. Guarde a regra do art. 41: NUNCA pode transferir entre quadros de oficiais, e só o QOC exerce função de oficial COMBATENTE."}'::jsonb),
('law_10230', 38, '{"t": "sec", "x": "Seção II — Do Quadro de Praças Especiais e de Praças"}'::jsonb),
('law_10230', 39, '{"t": "art", "n": "Art. 42 a Art. 51", "x": "Art. 42 — O Quadro de Praças Especiais Bombeiros Militar (QPBME) é constituído de Aspirantes-a-Oficial Bombeiro Militar e Cadetes do Curso de Formação de Oficiais.\nArt. 43 — QPBM-0 (combatentes): praças encarregados das atividades-fim da Corporação.\nArt. 44 — QPBM-1 (músicos): praças músicos dos diversos instrumentos.\nArt. 45 — QPBM-1/Corneteiro: praças músicos corneteiros.\nArt. 46 — QPBM-2 (auxiliares de saúde): técnicos em enfermagem, radiologia, nutrição, entre outros.\nArt. 47 — QPBM-3 (auxiliares de odontologia): técnicos em odontologia.\nArt. 48 — QPBM-4 (manutenção de comunicação): técnicos em radiocomunicação, telecomunicações, informática, eletrônica, eletrotécnica, entre outros.\nArt. 49 — QPBM-5 (manutenção de motomecanização): técnicos em mecânica, eletromecânica, elétrica de auto, bombas hidráulicas, entre outros.\nArt. 50 — As praças combatentes e especialistas são qualificadas para suas atividades específicas, além das funções militares gerais; o Governador pode baixar normas complementares de qualificação, por proposta do Comandante-Geral.\nArt. 51 — É VEDADA a transferência de militares entre os Quadros de Praças Bombeiros Militar.", "s": "Mesma regra de “sem transferência entre quadros” que vale pros oficiais (art. 41) também vale pras praças (art. 51) — é um padrão repetido na lei. E note: Aspirante-a-Oficial e Cadete formam a Praça Especial (QPBME) — igual à lógica da PMMA (Lei 6.513/95, art. 19, §3º)."}'::jsonb),
('law_10230', 40, '{"t": "sec", "x": "Seção III — Do Quadro de Pessoal Civil"}'::jsonb),
('law_10230', 41, '{"t": "art", "n": "Art. 52", "x": "O Quadro de Pessoal Civil será constituído por civis, com formações de ensino superior, médio e fundamental, para exercerem as funções inerentes às suas respectivas qualificações, cedidos dos Quadros de Servidores do Estado, compreendendo: I- Quadro de Pessoal Civil: posto à disposição da Corporação; II- Quadro de Pessoal Civil, nomeado ou contratado.\n§1º Os cargos comissionados terão seu quantitativo estabelecido em lei específica para o desempenho de funções administrativas ou técnicas.", "s": "O CBMMA também pode ter CIVIS no quadro (cedidos do Estado, ou nomeados/contratados) — não é 100% composto só por militares."}'::jsonb),
('law_10230', 42, '{"t": "cap", "x": "CAPÍTULO II — DO EFETIVO"}'::jsonb),
('law_10230', 43, '{"t": "art", "n": "Art. 53", "x": "O efetivo do Corpo de Bombeiros Militar do Maranhão será fixado em lei específica, mediante proposta do Governador do Estado, ouvido o Comandante-Geral.\nParágrafo único. Respeitado o efetivo fixado na lei, caberá ao Secretário de Estado da Segurança Pública aprovar a distribuição pormenorizada dos Bombeiros-Militar, pelos Quadros de Organização por Postos e Graduações, na conformidade com a estrutura organizacional prevista em lei.", "s": "Mesmo mecanismo em 2 camadas que vimos na Lei 14.751/2023 (art. 11): o NÚMERO total do efetivo é por LEI específica (hoje, a Lei nº 7.764/2002); já a DISTRIBUIÇÃO detalhada por posto/graduação é aprovada pelo Secretário de Segurança Pública, dentro desse limite."}'::jsonb),
('law_10230', 44, '{"t": "tit", "x": "TÍTULO IV — DAS DISPOSIÇÕES FINAIS"}'::jsonb),
('law_10230', 45, '{"t": "art", "n": "Art. 54 a Art. 59", "x": "Art. 54 — A Coordenadoria Estadual de Proteção e Defesa Civil e o Sistema Estadual de Proteção e Defesa Civil serão estabelecidos em lei específica, por ato do Governador, mediante proposta do Comandante-Geral.\nArt. 55 — Ficam assegurados todos os direitos aos militares das Unidades de Bombeiros Militar existentes antes da aprovação desta Lei.\nArt. 56 — Aplicar-se-ão ao CBMMA, enquanto não houver legislação específica, as normas pertinentes à Polícia Militar do Maranhão e ao Exército Brasileiro, no que couber.\nArt. 57 — A Corporação pode firmar convênios com prefeituras municipais para ampliar a articulação operacional, ressalvadas as atividades militares e técnicas exclusivas do CBMMA.\nArt. 58 — Compete ao Governador do Estado regulamentar esta Lei.\nArt. 59 — Esta Lei entra em vigor na data de sua publicação.", "s": "O art. 56 é OURO de prova: na ausência de lei própria do CBMMA sobre um assunto, aplicam-se as normas da PMMA e do Exército Brasileiro — é a “cola de segurança” que liga as 3 leis que você já estudou (6.513/95, 12.896/2026 e 14.751/2023) também ao bombeiro, mesmo quando esta Lei 10.230/2015 não trata do tema diretamente."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('law_14751', 0, '{"t": "tit", "x": "LEI Nº 14.751, DE 12 DE DEZEMBRO DE 2023 — Lei Orgânica Nacional das Polícias Militares e dos Corpos de Bombeiros Militares dos Estados, do Distrito Federal e dos Territórios"}'::jsonb),
('law_14751', 1, '{"t": "art", "n": "Ementa", "x": "Institui a Lei Orgânica Nacional das Polícias Militares e dos Corpos de Bombeiros Militares dos Estados, do Distrito Federal e dos Territórios, nos termos do inciso XXI do caput do art. 22 da Constituição Federal, altera a Lei nº 13.675, de 11 de junho de 2018, e revoga dispositivos do Decreto-Lei nº 667, de 2 de julho de 1969.", "s": "Esta é a LEI-MÃE NACIONAL (federal, do Congresso), diferente das outras duas (que são leis ESTADUAIS do Maranhão). Ela usa a competência privativa da União do art. 22, XXI, da CF pra fixar normas gerais que toda PM e todo CBM do país têm que seguir — inclusive a PMMA e o CBMMA."}'::jsonb),
('law_14751', 2, '{"t": "cap", "x": "CAPÍTULO I — DISPOSIÇÕES GERAIS"}'::jsonb),
('law_14751', 3, '{"t": "art", "n": "Art. 1º", "x": "Esta Lei institui a Lei Orgânica Nacional das Polícias Militares e dos Corpos de Bombeiros Militares dos Estados, do Distrito Federal e dos Territórios.", "s": "Artigo de abertura, só repete a ementa. Não tem pegadinha, mas confirma o escopo: PMs e CBMs de Estados, DF e Territórios (não fala em Municípios — não existe PM municipal)."}'::jsonb),
('law_14751', 4, '{"t": "art", "n": "Art. 2º", "x": "As polícias militares e os corpos de bombeiros militares dos Estados, do Distrito Federal e dos Territórios são instituições militares permanentes, exclusivas e típicas de Estado, essenciais à Justiça Militar, na condição de forças auxiliares e reserva do Exército, nos termos do §6º do art. 144 da Constituição Federal, indispensáveis à preservação da ordem pública, à segurança pública, à incolumidade das pessoas e do patrimônio e ao regime democrático, organizadas com base na hierarquia e na disciplina militares e comandadas por oficial da ativa do último posto, integrante do Quadro de Oficiais de Estado-Maior (QOEM) da respectiva instituição.\n§1º Às polícias militares cabe a proteção dos direitos fundamentais no âmbito da preservação da ordem pública, da polícia ostensiva e da polícia judiciária militar, com a finalidade de preservação da ordem pública e da incolumidade das pessoas e do patrimônio, além de outras atribuições previstas em lei.\n§2º Aos corpos de bombeiros militares cabem a proteção dos direitos fundamentais no âmbito da defesa civil, a prevenção e o combate a incêndios, o atendimento a emergências relativas a busca, salvamento e resgate, a perícia administrativa de incêndio e explosão e a polícia judiciária militar, com a finalidade de preservação da ordem pública e da incolumidade das pessoas e do patrimônio, além de outras atribuições previstas em lei.\n§3º As polícias militares e os corpos de bombeiros militares são instituições: I- militares; II- permanentes; III- indispensáveis à preservação da ordem pública; IV- vinculadas ao sistema de governança da política de segurança pública dos Estados, do DF e dos Territórios; e V- integrantes: a) do Sistema Único de Segurança Pública (Susp); b) da Defesa Nacional; c) do Sistema Nacional de Proteção e Defesa Civil (Sinpdec); e d) do Sistema Nacional do Meio Ambiente (Sisnama).", "s": "Decore os 4 adjetivos: força auxiliar E reserva do EXÉRCITO (nunca das outras Forças), comandada por oficial do ÚLTIMO POSTO do QOEM. E decore os 4 sistemas do §3º, V: SUSP, Defesa Nacional, SINPDEC (defesa civil) e SISNAMA (meio ambiente) — muito cobrado trocando um pelo outro."}'::jsonb),
('law_14751', 5, '{"t": "art", "n": "Art. 3º", "x": "São princípios básicos a serem observados pelas polícias militares e pelos corpos de bombeiros militares, além de outros previstos na legislação e em regulamentos, no âmbito de suas atribuições constitucionais e legais: I- hierarquia; II- disciplina; III- proteção, promoção e respeito aos direitos humanos, inclusive os decorrentes de compromissos internacionais assumidos pelo Brasil; IV- legalidade; V- impessoalidade; VI- publicidade, com transparência e prestação de contas; VII- moralidade; VIII- eficiência; IX- efetividade; X- razoabilidade e proporcionalidade; XI- universalidade na prestação do serviço; XII- participação e interação comunitária.", "s": "Repare: os 5 primeiros (legalidade, impessoalidade, publicidade, moralidade, eficiência) são os mesmos do art. 37 da CF (LIMPE) — só que aqui vêm DEPOIS de hierarquia, disciplina e direitos humanos, que são específicos da atividade militar."}'::jsonb),
('law_14751', 6, '{"t": "art", "n": "Art. 4º", "x": "São diretrizes a serem observadas pelas polícias militares e pelos corpos de bombeiros militares, além de outras previstas na legislação e em regulamentos: I- atendimento permanente ao cidadão e à sociedade; II- planejamento estratégico e sistêmico; III- integração com a comunidade, com o Poder Judiciário, com os órgãos do sistema de segurança pública e com demais instituições públicas; IV- planejamento e distribuição do efetivo proporcionalmente ao número de habitantes na circunscrição, obedecidos indicadores, peculiaridades e critérios técnicos regionais, salvo o caso de unidades especializadas, quando houver apenas uma unidade para determinada área geográfica; V- racionalidade e imparcialidade nas ações das instituições militares; VI- caráter técnico e científico no planejamento e no emprego; VII- padronização de procedimentos operacionais, formais e administrativos e da identidade visual e funcional, com publicidade, ressalvados aqueles para os quais a Constituição ou a lei determinem sigilo; VIII- prevenção especializada; IX- cooperação e compartilhamento recíproco das experiências entre os órgãos de segurança pública, mediante instrumentos próprios, na forma da lei; X- utilização recíproca de sistema integrado de informações e acesso a dados cadastrais, observados os credenciamentos e os sigilos legais; XI- capacitação profissional continuada; XII- instituição de base de dados on-line e unificada por Estado da Federação, em conformidade com graus de sigilo do Ministério da Justiça e Segurança Pública, com compartilhamento recíproco entre os órgãos do Susp; XIII- utilização dos meios tecnológicos disponíveis e atualização das metodologias de trabalho; XIV- uso racional da força e uso progressivo dos meios; XV- integração ao sistema de segurança pública com aprimoramento contínuo de mecanismos de governança; XVI- instituição de programas e projetos vinculados às políticas públicas e ao plano nacional, estadual e distrital de segurança pública, baseados em evidências técnicas e científicas; XVII- gestão da proteção e compartilhamento de seus bancos de dados e demais sistemas de informação; XVIII- livre convencimento técnico-jurídico do oficial no exercício da polícia judiciária militar; XIX- desempenho de funções de polícia judiciária militar e apuração de infrações penais militares, mediante presidência do oficial, com natureza jurídica essencial e exclusiva de Estado; XX- edição de atos administrativos normativos no âmbito de suas atribuições constitucionais e legais.", "s": "A pegadinha mais forte deste artigo é o inciso IV: a distribuição do efetivo é proporcional à POPULAÇÃO, mas SEMPRE respeitando indicadores/peculiaridades/critérios técnicos regionais — se a banca disser “exclusivamente pela população, vedados outros critérios”, está ERRADO (isso já caiu antes, na Lei 12.896 estadual, invertido do mesmo jeito). Também decore XIV: uso RACIONAL da força e uso PROGRESSIVO dos meios — são dois princípios diferentes, não sinônimos."}'::jsonb),
('law_14751', 7, '{"t": "art", "n": "Art. 5º", "x": "Compete às polícias militares dos Estados, do Distrito Federal e dos Territórios, nos termos de suas atribuições constitucionais e legais, respeitado o pacto federativo: I- planejar, coordenar e dirigir a polícia de preservação da ordem pública, a polícia ostensiva e a polícia judiciária militar; II- executar, ressalvada a competência da União, a polícia de preservação da ordem pública, a polícia ostensiva e, privativamente, a polícia judiciária militar; III- realizar a prevenção e a repressão dos ilícitos penais militares e cumprir mandados de prisão, busca e apreensão e demais medidas cautelares, bem como ordens judiciais referentes à apuração de infrações penais militares praticadas por seus membros, ressalvada a competência da União; IV- realizar a prevenção dos ilícitos penais, com adoção das ações necessárias ao pronto restabelecimento da ordem pública; V- exercer a polícia ostensiva rodoviária e de trânsito, como integrantes do Sistema Nacional de Trânsito, nos termos do art. 23 da Lei nº 9.503/1997 (CTB), ressalvada a competência da União, dos Estados, do DF e dos Municípios e as específicas do agente de trânsito concursado; VI- exercer, por delegação ou convênio, outras atribuições para prevenir e reprimir atos relacionados à segurança de trânsito, sem prejuízo das atribuições dos agentes de trânsito; VII- exercer a polícia de preservação da ordem pública e a polícia ostensiva com vistas à proteção ambiental, a fim de: a) prevenir condutas lesivas ao meio ambiente; b) lavrar auto de infração ambiental; c) aplicar sanções e penalidades administrativas; d) promover ações de educação ambiental, como integrante do Sisnama; VIII- exercer, por delegação ou convênio, outras atribuições na prevenção e repressão a atividades lesivas ao meio ambiente; IX- (VETADO); X- realizar coleta, busca e análise de dados, inclusive estatísticos, sobre criminalidade e infrações administrativas; XI- produzir, difundir, planejar, orientar, coordenar, supervisionar e executar ações de inteligência e contrainteligência; XII- realizar correições, inspeções e auditorias, em caráter permanente, ordinário ou extraordinário; XIII- organizar e realizar manifestações técnico-científicas e estatísticas; XIV- recrutar, selecionar e formar seus membros militares por meio de seu sistema de ensino militar; XV- ter acesso, na apuração de infrações penais militares de seus membros, aos bancos de dados de identificação civil e criminal e de armas, veículos e objetos, observado o inciso X do art. 5º da CF; XVI- emitir manifestação técnica quando exigida autorização de órgão competente em eventos e locais públicos que demandem policiamento ostensivo, realizar fiscalização e aplicar medidas legais, sem prejuízo das prerrogativas de outros órgãos; XVII- custodiar, por órgão próprio ou, na ausência deste, em unidade militar, o militar condenado ou preso provisoriamente; XVIII- participar do planejamento das políticas públicas e desenvolver políticas de prevenção educativa direcionadas à família, infância, juventude, grupos vulneráveis, meio ambiente, trânsito e combate às drogas; XIX- (VETADO); XX- realizar ações de polícia comunitária para prevenção de conflitos; XXI- atuar de forma integrada e cooperada com outras instituições do art. 144 da CF e com a Lei nº 13.675/2018; XXII- administrar as tecnologias da instituição (sistemas, comunicações, bancos de dados, sites, rede lógica, segurança da informação); XXIII- exercer todas as prerrogativas inerentes ao poder de polícia ostensiva, de preservação da ordem pública e de polícia judiciária militar; XXIV- implementar ações contínuas de prevenção, orientação e reeducação relacionadas ao desvio de conduta ética policial militar; XXV- desempenhar outras atribuições previstas na legislação, obedecidos os limites à auto-organização dos entes federados.\n§2º Os membros das polícias militares são autoridades de polícia administrativa, de polícia ostensiva, de polícia de preservação da ordem pública e de polícia judiciária militar, nos termos do Decreto-Lei nº 1.002/1969 (CPPM).\n§3º As funções constitucionais das PMs somente serão exercidas pelos militares que as integram, admitida a celebração de convênio e acordos de cooperação técnica.\n§4º Considera-se função de polícia judiciária militar a atividade exercida no âmbito do Decreto-Lei nº 1.001/1969 (CPM) e do Decreto-Lei nº 1.002/1969 (CPPM).", "s": "Lista gigante de competências — foco no que mais cai: a polícia judiciária militar é PRIVATIVA (inciso II); os incisos IX e XIX foram VETADOS (se a prova citar conteúdo desses números, desconfie); e o §4º dá a “fórmula” de polícia judiciária militar = CPM (Dec-Lei 1.001) + CPPM (Dec-Lei 1.002), sempre os dois juntos."}'::jsonb),
('law_14751', 8, '{"t": "art", "n": "Art. 6º", "x": "Compete aos corpos de bombeiros militares dos Estados, do Distrito Federal e dos Territórios, nos termos de suas atribuições constitucionais e legais: I- planejar, coordenar e dirigir as ações de prevenção, extinção e perícia administrativa de incêndios, atendimento a emergências, busca, salvamento e resgate e polícia judiciária militar, além de exercer poder de polícia nas ações que lhes competem; II- executar, prioritariamente, ressalvadas as competências da União e dos Municípios, as ações de busca, salvamento e resgate e, privativamente, as ações de prevenção, combate e perícia administrativa de incêndios e de polícia judiciária militar; III- editar atos normativos de segurança contra incêndio, pânico e emergência; IV- fiscalizar os serviços de armazenamento e transporte de produtos especiais e perigosos; V- emitir pareceres sobre sinistros, emergências, proteção do patrimônio ambiental, riscos de colapso em estruturas e riscos de incêndio florestal, e executar as perícias administrativas; VI- exercer atividades de gestão, direção, planejamento, coordenação e articulação perante os sistemas estaduais de proteção e defesa civil e o Sistema Nacional de Proteção e Defesa Civil; VII- proteger o meio ambiente mediante: a) prevenção, combate e extinção de incêndio florestal; b) promoção de ações de educação ambiental, como integrante do Sisnama; VIII- lavrar o auto de infração ambiental nos casos de incêndio florestal e aplicar sanções e penalidades administrativas; IX- exercer, sem prejuízo de outros órgãos, vistorias, licenciamento e fiscalização de edificações, eventos e locais de concentração de público e áreas de risco, e, privativamente, exercer a segurança contra incêndio, pânico e emergência; X- (VETADO); XI- exercer privativamente as funções de polícia judiciária militar e, nos termos da lei federal, realizar a prevenção e repressão dos ilícitos penais militares e cumprir mandados de prisão, busca e apreensão e demais medidas cautelares, ressalvada a competência da União; XII- realizar coleta, busca e análise de dados sobre criminalidade e infrações administrativas de interesse da polícia judiciária militar; XIII- regulamentar, credenciar e fiscalizar empresas de fabricação/comercialização de produtos e escolas formadoras relativas à segurança contra incêndio, pânico e emergência, brigadas de incêndio e serviços civis/auxiliares de bombeiros; XIV- produzir, difundir, planejar, orientar, coordenar, supervisionar e executar ações de inteligência e contrainteligência; XV- realizar correições, inspeções e auditorias, em caráter permanente, ordinário ou extraordinário; XVI- organizar e realizar pesquisas técnico-científicas, testes e manifestações técnicas; XVII- recrutar, selecionar, formar e desenvolver a educação continuada de seus membros, por meio do seu sistema de ensino militar; XVIII- desenvolver políticas de prevenção educativa no âmbito da defesa civil, relativas a acidentes, incêndio, emergência e socorros de urgência; XIX- custodiar, por órgão próprio ou, na ausência deste, em unidade militar, o militar condenado ou preso provisoriamente; XX- participar do planejamento e da elaboração de políticas estaduais de proteção e defesa civil; XXI- exercer, no âmbito da instituição, o poder hierárquico e o poder disciplinar; XXII- atender às requisições do Poder Judiciário e do Ministério Público; XXIII- atuar de forma integrada e cooperada com outras instituições do art. 144 da CF e com a Lei nº 13.675/2018; XXIV- administrar as tecnologias da instituição; XXV- exercer todas as prerrogativas inerentes ao poder de polícia; XXVI- ter acesso, na sua atribuição de polícia judiciária militar, aos bancos de dados de identificação civil/criminal e de armas, veículos e objetos; XXVII- desempenhar outras atribuições previstas em lei.\n§2º Os membros dos CBMs são autoridades de polícia administrativa e de polícia judiciária militar nos termos do Decreto-Lei nº 1.002/1969 (CPPM).\n§3º As competências deste artigo serão exercidas pelos corpos de bombeiros ORGÂNICOS das polícias militares, respeitadas as particularidades da estrutura organizacional das PMs.\n§4º As funções constitucionais dos CBMs somente serão exercidas pelos militares que os integram, admitida a celebração de convênios e acordos de cooperação técnica.\n§5º A perícia administrativa dos CBMs será feita depois de liberado o local pelo perito criminal, salvo manifesta impossibilidade de presença da perícia criminal.", "s": "Comparando com o art. 5º (PM): aqui quem é PRIVATIVO do CBM é combate a incêndio/perícia de incêndio e polícia judiciária militar (inciso II) — já busca/salvamento/resgate é só PRIORITÁRIO, não privativo (a União/Município também podem atuar). E o §3º é ótimo pra prova: no Maranhão o CBMMA é ORGÂNICO da PMMA (não é corporação separada), então as competências deste art. 6º são exercidas pelo próprio corpo de bombeiros dentro da estrutura da PM."}'::jsonb),
('law_14751', 9, '{"t": "art", "n": "Art. 7º", "x": "As polícias militares e os corpos de bombeiros militares, instituições militares permanentes, subordinam-se aos governadores dos Estados, do Distrito Federal e dos Territórios.\nParágrafo único. Poderão promover, mediante convênios e intercâmbios operacionais, a integração de suas atividades com as dos demais órgãos públicos, direcionada, no caso das áreas de ensino, a pesquisa, extensão, informações e conhecimentos técnicos, vedados o esvaziamento e a substituição de funções de outros órgãos e instituições.", "s": "Subordinação operacional é ao GOVERNADOR (não ao Comando do Exército — este só faz controle/coordenação via IGPM/BM, art. 28). Decore a palavra “vedado”: convênio de ensino não pode esvaziar nem substituir outros órgãos."}'::jsonb),
('law_14751', 10, '{"t": "art", "n": "Art. 8º", "x": "As polícias militares e os corpos de bombeiros militares poderão cooperar nas comunicações de centro de operações, na formação, no treinamento e no aperfeiçoamento de outras instituições e órgãos de segurança pública federal, estadual, distrital e municipal.\nParágrafo único. É vedada a cooperação para formação e treinamento de natureza militar para as instituições civis.", "s": "MESMA vedação que já está na Lei estadual 12.896/2026 (art. 4º, XXV): pode cooperar com órgãos de segurança pública, mas é PROIBIDO treinar/formar civis em natureza MILITAR."}'::jsonb),
('law_14751', 11, '{"t": "cap", "x": "CAPÍTULO II — DA ORGANIZAÇÃO"}'::jsonb),
('law_14751', 12, '{"t": "art", "n": "Art. 9º", "x": "A organização das polícias militares e dos corpos de bombeiros militares será fixada em lei de iniciativa privativa do governador, observadas as normas gerais previstas nesta Lei e os fundamentos de organização das Forças Armadas.\nParágrafo único. As polícias militares e os corpos de bombeiros militares do Distrito Federal e dos Territórios, instituições organizadas e mantidas pela União (art. 21, XIV, CF), serão reguladas em lei federal de iniciativa do Presidente da República, observadas as normas gerais previstas nesta Lei.", "s": "Mesma regra que já vimos na Lei 12.896/2026 (art. 9º estadual, que é justamente essa lei de iniciativa privativa do Governador aplicada ao Maranhão) — aqui é a versão federal que MANDA os Estados seguirem esse modelo. PMDF/CBMDF são diferentes: lei FEDERAL, iniciativa do Presidente, porque são mantidas pela União."}'::jsonb),
('law_14751', 13, '{"t": "art", "n": "Art. 10", "x": "A organização das polícias militares e dos corpos de bombeiros militares, prevista em lei de iniciativa privativa do governador, deve observar preferencialmente a seguinte estrutura básica: I- órgãos de direção; II- órgãos de assessoramento; III- órgãos de apoio; IV- órgãos de execução; V- órgãos de correição.\n§1º Os órgãos de direção compreendem: I- os de direção-geral (direção geral, planejamento estratégico e administração superior); II- os de direção setorial (administração setorial de inteligência, recursos humanos, saúde, ensino/instrução, pesquisa e desenvolvimento, logística e gestão orçamentária/financeira/ambiental, entre outras).\n§2º Os órgãos de assessoramento destinam-se a prestar assessoria, consultoria, recomendação e orientação técnica e política e a expedir nota técnica.\n§3º Os órgãos de apoio destinam-se ao atendimento das necessidades de recursos humanos, saúde, ensino, pesquisa, logística e gestão orçamentária/financeira — realizam as atividades-MEIO.\n§4º Os órgãos de execução destinam-se à realização das atividades-FIM, de acordo com as peculiaridades da unidade federada.\n§5º Os órgãos de correição, com atuação desconcentrada, exercem as funções de corregedoria-geral (prevenção, fiscalização e apuração de desvios de conduta, promoção da qualidade do serviço, instrumentalização da Justiça Militar e acompanhamento de medidas cautelares e mandados de prisão), sem suprimir a responsabilidade do poder hierárquico e disciplinar das autoridades locais.\n§6º Poderão ainda contar com órgãos especializados de execução, para missões específicas, com responsabilidade sobre toda a área da unidade federada.\n§7º As instituições militares estaduais poderão criar e manter as assessorias militares.", "s": "É EXATAMENTE a mesma estrutura de 5 órgãos já vista na Lei 12.896/2026 estadual (D-A-A-E-C: Direção, Assessoramento, Apoio, Execução, Correição) — porque a lei estadual copiou esta federal. Decore a diferença apoio (atividade-MEIO) x execução (atividade-FIM)."}'::jsonb),
('law_14751', 14, '{"t": "cap", "x": "CAPÍTULO III — DOS EFETIVOS"}'::jsonb),
('law_14751', 15, '{"t": "art", "n": "Art. 11", "x": "Os efetivos das polícias militares e dos corpos de bombeiros militares, integrados pelos membros militares das instituições (art. 42 da CF), são fixados em lei estadual, bem como em lei federal no caso do DF e dos Territórios, considerados a extensão da área territorial, a população, os índices de criminalidade, os riscos potenciais de desastres, o índice de desenvolvimento humano e as condições socioeconômicas da unidade federada, entre outros, conforme as peculiaridades locais.", "s": "O efetivo é fixado por LEI ESTADUAL — e não é só “população”: entram também área territorial, criminalidade, risco de desastre, IDH e condição socioeconômica. Combina com o art. 4º, IV (vedado fixar só pela população)."}'::jsonb),
('law_14751', 16, '{"t": "art", "n": "Art. 12", "x": "A hierarquia nas polícias militares e nos corpos de bombeiros militares deve observar a seguinte estrutura básica:\nI- oficiais: a) oficiais superiores: coronel, tenente-coronel, major; b) oficiais intermediários: capitão; c) oficiais subalternos: primeiro-tenente, segundo-tenente;\nII- praças especiais: aspirante a oficial, cadete, aluno-oficial;\nIII- praças: subtenente, primeiro-sargento, segundo-sargento, terceiro-sargento, aluno-sargento, cabo, soldado, aluno-soldado.\nParágrafo único. A todos os postos e graduações será acrescida a designação “PM” ou “BM”.", "s": "Compare com a Lei 6.513/95 estadual (art. 19): lá a “praça especial” é só Aspirante e Cadete; aqui a lei FEDERAL acrescenta também o ALUNO-OFICIAL como praça especial, e cria ALUNO-SARGENTO e ALUNO-SOLDADO dentro do círculo de praças — mais “alunos” que a lei estadual antiga previa fora dessas categorias. Detalhe batido em prova: a sigla vem DEPOIS do posto/graduação (ex.: Coronel PM, não “PM Coronel”)."}'::jsonb),
('law_14751', 17, '{"t": "art", "n": "Art. 13", "x": "São condições básicas para ingresso nas polícias militares e nos corpos de bombeiros militares, além do previsto na lei do ente federado: I- ser brasileiro; II- estar quite com as obrigações militares e eleitorais; III- não registrar antecedentes penais dolosos incompatíveis com a atividade, nos termos da legislação do ente federado; IV- estar no gozo dos direitos políticos; V- ser aprovado em concurso público de provas ou de provas e títulos; VI- ter procedimento social e idoneidade moral irrepreensíveis, apurados por meio de investigação; VII- ter capacitação física e psicológica compatível com o cargo, verificada por exame de aptidão com critérios técnicos e objetivos definidos no edital; VIII- ser aprovado em exame de saúde e exame toxicológico com larga janela de detecção; IX- comprovar, na data de admissão/incorporação/formatura, o grau de escolaridade superior, nos termos do art. 15 e da legislação do ente federado; e X- não possuir tatuagens visíveis, quando em uso dos uniformes, de suásticas, obscenidades, ideologias terroristas ou que façam apologia à violência, às drogas ilícitas ou à discriminação de raça, credo, sexo ou origem.\nParágrafo único. Além do tratamento previsto na legislação militar, os militares têm direito ao tratamento protocolar deferido às carreiras de mesmo requisito de ingresso.", "s": "Note que “ser brasileiro” aqui NÃO distingue nato/naturalizado (diferente da carreira de Oficial da Lei 6.513/95 estadual, que exige nato) — a restrição a brasileiro NATO pra Oficial é regra ESTADUAL específica, não desta lei nacional. E o inciso IX já exige nível SUPERIOR pra ingresso — mas veja o art. 39: esse requisito tem prazo de até 6 anos pra ser implantado."}'::jsonb),
('law_14751', 18, '{"t": "art", "n": "Art. 14", "x": "A progressão do militar na hierarquia militar, pelos fundamentos das Forças Armadas, independentemente da sua lotação no quadro de organização, será fundamentada no valor moral e profissional, de forma seletiva, gradual e sucessiva, e será feita mediante promoções, pelos critérios de antiguidade e merecimento, este com parâmetros objetivos, de modo a garantir fluxo regular e equilibrado de carreira.\nParágrafo único. Serão admitidas as promoções por bravura e post mortem e a promoção por completar o militar os requisitos para transferência a pedido ou compulsória para a inatividade, sem prejuízo da promoção em ressarcimento de preterição.", "s": "Decore os 2 critérios-base: ANTIGUIDADE e MERECIMENTO. E os critérios ESPECIAIS do parágrafo único: bravura, post mortem, e por completar requisitos de transferência pra inatividade — mesmos tipos especiais que já vimos no Estatuto estadual (art. 78, Lei 6.513/95)."}'::jsonb),
('law_14751', 19, '{"t": "art", "n": "Art. 15", "x": "As polícias militares e os corpos de bombeiros militares constituir-se-ão, entre outros, dos seguintes quadros: I- Quadro de Oficiais de Estado-Maior (QOEM): comando, chefia, direção e administração superior; oficiais aprovados em concurso público, exigido bacharelado em direito (facultada, para bombeiros, outra graduação prevista na lei do ente federado), com curso de formação de oficiais; II- Quadro de Oficiais Especialistas (QOE): atividades complementares ao QOEM, integrado por oficiais oriundos do quadro de praças, com curso de habilitação, admitida a promoção até tenente-coronel; III- Quadro de Oficiais de Saúde (QOS): atividades de saúde e direção de órgãos de saúde, integrado por oficiais com graduação superior na área de saúde, emprego obrigatório e exclusivo na área de saúde; IV- Quadro de Oficiais da Reserva e Reformados (QORR): oficiais da reserva remunerada e reformados; V- Quadro de Praças (QP): praças aprovadas em concurso de nível superior ou com curso de formação reconhecido como de nível superior, com progressão até subtenente; VI- Quadro de Praças da Reserva e Reformados (QPRR): praças da reserva remunerada e reformados.\n§2º Os integrantes da instituição militar não terão limite de idade para o concurso público de ingresso no QOEM. (Parágrafo vetado pelo Presidente da República, mantido pelo Congresso Nacional e publicado no DOU de 13/6/2024)\n§3º O tempo de atividade militar e os cursos realizados na instituição militar do concurso serão contados como título para classificação no concurso público e no processo seletivo interno.\n§4º A critério das corporações, poderão ser instituídos Quadro de Oficial Temporário (QOT) e Quadro de Praça Temporário (QPT), por tempo determinado, nos termos da legislação do ente federado.\n§5º A critério das corporações, poderão ser estabelecidas especialidades dentro dos quadros.", "s": "6 quadros pra decorar: QOEM (comando, exige bacharel em direito), QOE (vem das praças, teto tenente-coronel), QOS (saúde), QORR (oficial inativo), QP (praças, teto subtenente), QPRR (praça inativa). Repare que o §2º (sem limite de idade pro concurso de QOEM) foi VETADO pelo Presidente mas DERRUBADO pelo Congresso — ou seja, apesar do veto, essa regra VALE (foi mantida)! Isso é pegadinha clássica de prova: veto mantido = texto entra em vigor mesmo assim."}'::jsonb),
('law_14751', 20, '{"t": "art", "n": "Art. 16", "x": "As polícias militares e os corpos de bombeiros militares manterão o seu sistema de ensino militar, podendo incluir colégios militares de ensino fundamental e médio, e ter cursos de graduação ou pós-graduação lato ou stricto sensu, com integração e equivalência a cursos regulares de universidades públicas, se atendidos os requisitos do MEC.\n§1º Os cursos de formação, adaptação e habilitação serão realizados em instituição de ensino militar; os de aperfeiçoamento ou especialização poderão ser realizados em unidade de ensino militar ou em instituições públicas conveniadas, no País ou no exterior.\n§2º Os cursos, além de habilitarem para o desempenho das atribuições do cargo, são requisito para promoção: para oficiais — a) CFO (Curso de Formação de Oficiais): ingresso como cadete, habilita a aspirante a oficial; b) CAO (Curso de Aperfeiçoamento de Oficiais): destinado aos capitães, habilita a major; c) CCEM (Curso de Comando e Estado-Maior): destinado a majores e tenentes-coronéis do QOEM e QOS, habilita a coronel; d) CHOS/CHOE (Curso de Habilitação de Oficial do QOS/QOE): ingresso como aluno-oficial, habilita a segundo-tenente; para praças — a) CFP (Curso de Formação de Praças): ingresso como aluno-soldado, habilita a soldado; b) CFS (Curso de Formação de Sargentos): ingresso como aluno-sargento, habilita a terceiro-sargento; c) CAP (Curso de Aperfeiçoamento de Praças): destinado aos segundos-sargentos, habilita a primeiro-sargento.", "s": "Monte a “escada dos cursos” de oficial: CFO (cadete→aspirante) → CAO (capitão→major) → CCEM (major/tenente-coronel→coronel). E da praça: CFP (aluno-soldado→soldado) → CFS (aluno-sargento→3ºsgt) → CAP (2ºsgt→1ºsgt). O CCEM é o mesmo curso citado no art. 119 da Lei 12.896/2026 estadual (regra de transição dos Coronéis sem CCEM)."}'::jsonb),
('law_14751', 21, '{"t": "cap", "x": "CAPÍTULO IV — DO MATERIAL DE SEGURANÇA PÚBLICA"}'::jsonb),
('law_14751', 22, '{"t": "art", "n": "Art. 17", "x": "O material de segurança pública das instituições militares, que tem as mesmas prerrogativas legais de material bélico, constituir-se-á de frotas operacionais e administrativas, armas de porte ou portáteis, munições e apetrechos, adquiridos no mercado nacional ou internacional, observada a legislação de licitações, e constituir-se-á, entre outros, de: I- armamentos; II- munições; III- explosivos e propelentes; IV- blindagens balísticas; V- equipamentos, armas e munições menos letais; VI- produtos controlados de uso restrito.\n§1º A dotação do material classificado como produto controlado de uso PERMITIDO será estabelecida por ato do governo local, mediante proposição do comando-geral, comunicado o órgão federal competente.\n§2º A dotação do material classificado como produto controlado de uso RESTRITO será estabelecida, quanto à quantidade e ao tipo, em planejamento estratégico da corporação, observadas as condições previstas em lei específica.\n§3º Serão cadastradas no Sistema de Gerenciamento Militar de Armas (Sigma) as armas de fogo institucionais, bem como as armas particulares dos integrantes que constem de seus registros próprios.\n§4º As instituições certificarão o cumprimento dos requisitos para aquisição de armas e munições e habilitação para o porte e remeterão as informações para registro no Sigma.", "s": "O material de segurança pública tem as MESMAS prerrogativas de material BÉLICO (ligação direta com a condição de força auxiliar/reserva do Exército). Decore a sigla SIGMA = Sistema de Gerenciamento Militar de Armas."}'::jsonb),
('law_14751', 23, '{"t": "cap", "x": "CAPÍTULO V — DAS GARANTIAS"}'::jsonb),
('law_14751', 24, '{"t": "art", "n": "Art. 18", "x": "São garantias das polícias militares e dos corpos de bombeiros militares, bem como de seus membros ativos e veteranos da reserva remunerada e reformados, entre outras: I- uso dos títulos e designações hierárquicas; II- uso privativo dos uniformes, insígnias e distintivos, vedada a utilização por qualquer entidade pública ou privada; III- exercício de cargo, função ou comissão correspondentes ao respectivo grau hierárquico; IV- expedição de documento de identidade militar com livre porte de arma, com fé pública em todo o território nacional; V- prisão criminal ou civil, antes do trânsito em julgado e enquanto não perder o posto/patente/graduação, em unidade prisional militar (ou, na falta, unidade militar estadual); VI- cumprimento de pena privativa de liberdade transitada em julgado em unidade prisional militar ou especial, separado dos presos comuns, quando perder o posto/patente/graduação; VII- comunicação ao superior hierárquico em caso de prisão; VIII- permanência na repartição policial, quando preso em flagrante, apenas o tempo da lavratura do auto, com transferência imediata; IX- acesso livre, em razão do serviço, aos locais sujeitos a fiscalização; X- prioridade nos serviços de transporte e comunicação em missão de urgência; XI- assistência jurídica quando acusado de infração penal/civil/administrativa decorrente da função; XII- (VETADO — seguro de vida/acidentes: inciso vetado pelo Presidente, MANTIDO pelo Congresso); XIII- assistência médica, psicológica, odontológica e social ao militar e dependentes; XIV- remuneração com escalonamento vertical entre postos/graduações; XV- patente/graduação em todos os níveis, com vantagens, prerrogativas, direitos e deveres, na ativa, reserva ou reforma; XVI- perda do posto/patente somente por decisão do Tribunal de Justiça Militar (ou Tribunal de Justiça, em tempo de paz) mediante representação da autoridade competente; XVII- processo e julgamento nos crimes militares definidos em lei; XVIII- desconto em folha de contribuições associativas e consignações; XIX- carreiras com acesso à hierarquia de forma seletiva, gradual e sucessiva; XX a XXII- (VETADOS); XXIII- carga horária com duração máxima estabelecida na legislação do ente federado; XXIV- tempo mínimo de 1 ano de permanência na unidade militar, ressalvada transferência justificada; XXV- transferência de ofício para instituição de ensino congênere; XXVI- estabilidade após 3 anos de efetivo serviço; XXVII- direito a equipamentos de proteção individual adequados; XXVIII- (VETADO); XXIX- atendimento prioritário e imediato do Ministério Público, Defensoria, Judiciário, Polícia Judiciária e perícia criminal quando vítima de infração penal; XXX- precedência em audiências judiciais como testemunha; XXXI- ajuda de custo quando removido para outro Município; XXXII- pagamento antecipado de diárias por deslocamento; XXXIII- regime disciplinar regulado em código de ética, com devido processo legal, ampla defesa e contraditório; XXXIV- aplicação ao veterano da reserva remunerada da Lei nº 7.524/1986 (direito de expressão e manifestação); XXXV- (VETADO); XXXVI- voluntariedade na reversão ao serviço ativo da reserva remunerada; XXXVII- compulsoriedade na convocação ao serviço ativo da reserva remunerada.\nParágrafo único. Salvo as prisões disciplinares militares, os militares têm a prerrogativa de serem presos somente por ordem escrita da autoridade judiciária competente ou em flagrante delito, com imediata comunicação ao chefe do órgão de direção superior.", "s": "Artigo enorme (37 incisos) — foco nos números batidos em prova: ESTABILIDADE após 3 ANOS (XXVI); permanência mínima de 1 ANO na unidade (XXIV); e a “pegadinha do veto mantido” se repete aqui no XII (seguro de vida) — vetado pelo Presidente, mas MANTIDO pelo Congresso, então vale. Guarde também o XVI: perda de posto/patente só por decisão do TRIBUNAL DE JUSTIÇA MILITAR (ou TJ, em tempo de paz) — nunca por ato administrativo do comandante-geral."}'::jsonb),
('law_14751', 25, '{"t": "cap", "x": "CAPÍTULO VI — DAS VEDAÇÕES, DOS DIREITOS, DOS DEVERES, DA REMUNERAÇÃO, DAS PRERROGATIVAS, DA INATIVIDADE E DA PENSÃO"}'::jsonb),
('law_14751', 26, '{"t": "art", "n": "Art. 19", "x": "Além das vedações previstas na legislação específica, é vedado aos militares, enquanto em atividade: I- participar de sociedade comercial, salvo como cotista, acionista e comanditário, e exercer atividade gerencial ou administrativa nessas empresas, salvo na hipótese de licença para tratar de interesse particular; II a V- (VETADOS); VI- divulgar imagens de pessoas sob sua custódia sem prévia autorização judicial.", "s": "Praticamente só sobrou o inciso I (a clássica vedação de sociedade comercial, salvo cotista/acionista/comanditário) e o VI (imagem de pessoa custodiada) — os incisos II a V foram todos VETADOS."}'::jsonb),
('law_14751', 27, '{"t": "art", "n": "Art. 20", "x": "(VETADO).", "s": "Artigo inteiro vetado — se a prova citar “art. 20 da Lei 14.751/2023” como fundamento de alguma regra, desconfie: não há conteúdo vigente aqui."}'::jsonb),
('law_14751', 28, '{"t": "art", "n": "Art. 21", "x": "(VETADO).", "s": "Também inteiro vetado, igual ao art. 20 — mesma lógica de desconfiar de qualquer citação a este artigo."}'::jsonb),
('law_14751', 29, '{"t": "art", "n": "Art. 22", "x": "O militar alistável é elegível, atendidas as seguintes prescrições: I- o militar com MENOS de 10 anos de serviço que for candidato a mandato eletivo será AFASTADO do serviço ativo no dia posterior ao pedido de registro de sua candidatura na Justiça Eleitoral; II- o militar com MAIS de 10 anos de serviço que for candidato a mandato eletivo será AGREGADO no dia posterior ao pedido de registro de sua candidatura, com remuneração, enquanto perdurar o pleito eleitoral, e, se eleito, no ato da diplomação passará para a reserva remunerada com remuneração proporcional ao tempo de serviço; III- o militar eleito que tomar posse como suplente será agregado ao respectivo quadro, enquanto perdurar o mandato temporário, devendo optar por uma das remunerações.\n§1º O afastamento ou a agregação somente serão remunerados nos prazos fixados na legislação eleitoral.\n§2º Nas hipóteses do inciso II, após o término do mandato, contar-se-á o tempo de exercício do mandato para recálculo da remuneração na inatividade, se não for integral. (Parágrafo vetado pelo Presidente da República, mantido pelo Congresso Nacional e publicado no DOU de 13/6/2024)", "s": "É EXATAMENTE a mesma regra do art. 14, §8º, da CF e que você já viu na Lei 6.513/95 estadual: marco de 10 ANOS de serviço. Menos de 10 anos = AFASTADO; mais de 10 anos = AGREGADO e, se eleito, vai pra reserva na diplomação. Esta é a versão NACIONAL da mesma regra."}'::jsonb),
('law_14751', 30, '{"t": "art", "n": "Art. 23", "x": "A precedência entre militares observará o previsto nos arts. 17, 18 e 19 da Lei nº 6.880, de 9 de dezembro de 1980 (Estatuto dos Militares das Forças Armadas), salvo os casos de precedência funcional estabelecida em lei.", "s": "Repare: pra precedência, esta lei manda aplicar o Estatuto dos Militares FEDERAIS (Lei 6.880/1980) — mesma lógica de “empréstimo” das Forças Armadas que aparece em vários pontos desta lei orgânica."}'::jsonb),
('law_14751', 31, '{"t": "cap", "x": "CAPÍTULO VII — DA CONVOCAÇÃO, DA MOBILIZAÇÃO E DO EMPREGO DAS POLÍCIAS MILITARES E DOS CORPOS DE BOMBEIROS MILITARES DOS ESTADOS, DO DISTRITO FEDERAL E DOS TERRITÓRIOS"}'::jsonb),
('law_14751', 32, '{"t": "art", "n": "Art. 24", "x": "Nas suas atribuições constitucionais, as polícias militares e os corpos de bombeiros militares são titulares da polícia ostensiva e da preservação da ordem pública, bem como da defesa civil, respectivamente, subordinados aos governadores, e, nas situações extraordinárias (§6º do art. 144 da CF), podem ser convocados ou mobilizados pela União, no todo ou em parte, pelo Ministério competente, nos casos de: I- decretação de intervenção federal, de estado de defesa ou de estado de sítio, precedendo o emprego das Forças Armadas; ou II- apoio aos órgãos federais mediante convênio ou com anuência do governador do Estado ou do Distrito Federal.", "s": "Este é o CORAÇÃO da condição de “força auxiliar e reserva do Exército”: em intervenção federal/estado de defesa/estado de sítio, a PM/CBM pode ser convocada pela União ANTES mesmo de empregar as Forças Armadas (inciso I)."}'::jsonb),
('law_14751', 33, '{"t": "art", "n": "Art. 25", "x": "As polícias militares e os corpos de bombeiros militares poderão ser mobilizados pela União no caso de guerra e integrarão a força terrestre designada, que delimitará os aspectos operacionais e táticos de seu emprego, obedecidas as suas missões específicas e constitucionais.", "s": "Em caso de GUERRA (hipótese mais extrema), a PM/CBM vira parte da força terrestre — mas sempre respeitando as missões específicas de cada instituição."}'::jsonb),
('law_14751', 34, '{"t": "art", "n": "Art. 26", "x": "Nas hipóteses de convocação/mobilização do art. 24: I- o ato de convocação fixará prazo, local e condições de execução; II- o militar convocado/mobilizado que responder a inquérito ou processo judicial por sua atuação efetiva nesse período será representado judicialmente pela Advocacia-Geral da União; III- os atos de polícia judiciária militar/civil e processuais decorrentes, quando necessária a presença de militar de outra unidade da Federação, realizar-se-ão prioritariamente de forma remota (videoconferência); e IV- a competência para o processamento e julgamento dos crimes militares imputados ao militar investigado/denunciado, mesmo praticados em outra unidade da Federação, será da Justiça Militar do ente federado a que ele pertencer.", "s": "Duas garantias importantes pro militar convocado: defesa pela AGU (inciso II) e, mesmo atuando fora do seu Estado, continua sendo julgado pela Justiça Militar do SEU próprio ente federado (inciso IV) — nunca muda de foro."}'::jsonb),
('law_14751', 35, '{"t": "art", "n": "Art. 27", "x": "Os governadores dos Estados, do Distrito Federal e dos Territórios poderão celebrar termos de parceria, convênios, consórcios e acordos de colaboração com unidades limítrofes para atuação integrada nas regiões de fronteiras e divisas, bem como com unidades federadas não limítrofes para atuação por tempo determinado e em missões específicas, nos termos do art. 241 da Constituição Federal.", "s": "Cooperação entre Estados VIZINHOS (fronteiras/divisas) é o caso típico; com Estados NÃO vizinhos só vale por tempo determinado e missão específica."}'::jsonb),
('law_14751', 36, '{"t": "art", "n": "Art. 28", "x": "A Inspetoria-Geral das Polícias Militares e dos Corpos de Bombeiros Militares (IGPM/BM), integrante do Comando do Exército, incumbe-se dos estudos, da coleta e do registro de dados e da assessoria referente ao controle e à coordenação, no âmbito federal, dos dispositivos desta Lei relativos à condição de força auxiliar e reserva do Exército.\n§1º Compete ao Comando do Exército, por meio da IGPM/BM: I- centralizar todos os assuntos da competência do Comando do Exército relativos às PMs e CBMs; II- promover as visitas de orientação técnica das PMs e CBMs; III- proceder ao registro dos dados e da dotação, organização, efetivos, armamento e material bélico, incluída a frota operacional militar (aeronaves, veículos, embarcações), com vistas ao emprego em convocação ou mobilização.\n§2º O cargo de inspetor-geral será exercido por oficial-general da ativa, nos termos da legislação do Exército Brasileiro.", "s": "Decore a sigla IGPM/BM e o vínculo: ela é integrante do COMANDO DO EXÉRCITO (não do Ministério da Justiça) — é o órgão federal que fiscaliza/coordena a condição de força auxiliar/reserva. O cargo de inspetor-geral é sempre de um oficial-general do Exército."}'::jsonb),
('law_14751', 37, '{"t": "cap", "x": "CAPÍTULO VIII — DISPOSIÇÕES FINAIS"}'::jsonb),
('law_14751', 38, '{"t": "art", "n": "Art. 29", "x": "Os comandantes-gerais das polícias militares e dos corpos de bombeiros militares serão nomeados por ato do governador entre os oficiais da ativa do ÚLTIMO POSTO do quadro QOEM (art. 15, I) e serão responsáveis, perante os governadores, pela administração e emprego da instituição.\n§1º A escolha deverá recair em oficial possuidor do CCEM (curso de comando e estado-maior), podendo o comandante-geral permanecer, a critério do governador, durante o governo da autoridade que o nomeou.\n§2º O comandante-geral nomeado deverá apresentar, em até 60 dias da posse, plano de comando com metas, indicadores, prestação de contas e participação da sociedade, contendo: I- metas de produtividade e redução de criminalidade; II- diagnóstico de recursos humanos/materiais e medidas de eficiência; III- programas de capacitação do efetivo; IV- planejamento de ações específicas; V- previsão de criação/extinção de unidades e estrutura organizacional.\n§3º Compete aos comandantes-gerais indicar nomes para cargos privativos, promover as praças e apresentar ao governador a lista de promoção dos oficiais.\n§4º Compete ao comandante-geral certificar o direito ao porte de arma, bem como as hipóteses de suspensão/cassação.\n§5º O comandante-geral deverá assegurar a divulgação pública de relatório anual sobre: I- representações apuradas e sanções aplicadas; II- número de ocorrências por tipo; III- letalidade e vitimização de policiais; IV- letalidade e vitimização de civis; V- orçamento previsto e executado.\n§6º Ao coronel nomeado comandante-geral, enquanto no cargo, serão asseguradas, para fins de precedência e sinais de respeito, as prerrogativas de general de brigada. (Parágrafo vetado pelo Presidente da República, mantido pelo Congresso Nacional e publicado no DOU de 13/6/2024)", "s": "Decore o requisito do §1º: oficial do último posto do QOEM E possuidor do CCEM (o mesmo curso citado no art. 16 e no art. 119 da Lei 12.896/2026 estadual). O §6º (equiparar comandante-geral a general de brigada) foi vetado pelo Presidente, mas MANTIDO pelo Congresso — vale! Prazo do plano de comando: 60 dias da posse."}'::jsonb),
('law_14751', 39, '{"t": "art", "n": "Art. 30", "x": "O comandante-geral da polícia militar deverá regulamentar e estabelecer protocolos operacionais com vistas a apoiar o militar em suas atividades.\nParágrafo único. Os protocolos operacionais deverão: I- incluir as situações de emprego das unidades, a cadeia de comando e as responsabilidades de comandantes e supervisores; II- ser encaminhados aos conselhos estaduais de segurança pública e defesa social previstos na Lei nº 13.675/2018; III- ser atualizados e corrigidos periodicamente.", "s": "Protocolos operacionais precisam ser encaminhados ao conselho estadual de segurança (inciso II) — mais uma ligação com a Lei nº 13.675/2018, o marco do SUSP."}'::jsonb),
('law_14751', 40, '{"t": "art", "n": "Art. 31", "x": "Para todos os efeitos legais, consideram-se equivalentes os cursos existentes na instituição na data de publicação desta Lei.", "s": "É o mesmo artigo citado no art. 119, §2º, da Lei 12.896/2026 estadual: garante que os cursos antigos da PMMA continuam valendo como equivalentes aos novos cursos desta lei."}'::jsonb),
('law_14751', 41, '{"t": "art", "n": "Art. 32", "x": "A remuneração dos militares do Distrito Federal, dos Territórios, do ex-Distrito Federal e dos ex-Territórios será estabelecida em lei federal.", "s": "Só se aplica a DF/Territórios — remuneração da PMMA (Estado) NÃO entra aqui, é lei estadual."}'::jsonb),
('law_14751', 42, '{"t": "art", "n": "Art. 33", "x": "No cumprimento de sua missão constitucional, ressalvadas as atividades sigilosas, as polícias militares e os corpos de bombeiros militares atuarão de forma OSTENSIVA, visivelmente identificados por meio de uniforme, armamento, viatura e equipamentos próprios autorizados em lei.", "s": "Regra geral: atuação OSTENSIVA e identificada — só as atividades sigilosas (ex.: inteligência) fogem dessa regra."}'::jsonb),
('law_14751', 43, '{"t": "art", "n": "Art. 34", "x": "O Poder Executivo federal editará decreto com a definição de parâmetros mínimos para: I- insígnias dos postos dos oficiais; II- divisas das graduações das praças; III- coloração e tonalidade das peças básicas de fardamento; IV- carteira de identidade militar; V- padrão e cor básica das viaturas; VI- núcleo comum curricular mínimo para os cursos de formação, habilitação e aperfeiçoamento, que conterá as disciplinas de direitos humanos e polícia comunitária, entre outras.\nParágrafo único. O decreto não estabelecerá prazo para adoção da padronização, respeitada a autonomia administrativa e orçamentária do ente federado, e deverá preservar as fardas e as cores históricas das viaturas das instituições.", "s": "Padronização NACIONAL mínima (insígnias, fardamento, viaturas, currículo com direitos humanos e polícia comunitária) — mas SEM prazo obrigatório e PRESERVANDO as cores/fardas históricas de cada corporação. Ou seja: padroniza o mínimo, sem apagar a identidade histórica de cada PM/CBM estadual."}'::jsonb),
('law_14751', 44, '{"t": "art", "n": "Art. 35", "x": "É assegurada a exclusividade da utilização das consagradas denominações “brigada militar” e “força pública” para a polícia militar e “bombeiros militares” e “corpo de bombeiros” para o corpo de bombeiros militar.\n§1º São instituídas as datas comemorativas nacionais de 21 de abril para as polícias militares e de 2 de julho para os corpos de bombeiros militares, facultada a definição de datas comemorativas estaduais com base na história e tradição de cada corporação.\n§2º É vedado, sob pena de responsabilização administrativa e judicial, o uso dos uniformes, símbolos e cores das PMs e CBMs por qualquer instituição, pública ou privada, ou por pessoa física.", "s": "Decore as duas datas nacionais: 21 de abril (Tiradentes) = Dia da Polícia Militar; 2 de julho = Dia do Corpo de Bombeiros Militar — mas cada Estado pode TAMBÉM ter sua própria data comemorativa estadual, além dessa nacional."}'::jsonb),
('law_14751', 45, '{"t": "art", "n": "Art. 36", "x": "Para os efeitos desta Lei, as definições de segurança pública, ordem pública, preservação da ordem pública, poder de polícia, polícia ostensiva, polícia de preservação da ordem pública, defesa civil, segurança contra incêndio, prevenção e combate a incêndio, pânico e emergência, busca, salvamento e resgate e polícia judiciária militar, bem como outras definições pertinentes, serão regulamentadas em ato do Poder Executivo federal, respeitadas as competências constitucionais e a auto-organização dos entes federados.", "s": "Todos esses conceitos-chave (que aparecem o tempo todo nos artigos anteriores) ainda serão REGULAMENTADOS por ato do Executivo federal — a lei usa os termos mas deixa a definição fina pra depois."}'::jsonb),
('law_14751', 46, '{"t": "art", "n": "Art. 37", "x": "São instituídos o Conselho Nacional de Comandantes-Gerais de Polícia Militar (CNCGPM) e o Conselho Nacional de Comandantes-Gerais de Bombeiros Militares (CNCGBM), de natureza oficial, integrados por todos os comandantes-gerais.\nParágrafo único. O Poder Executivo editará decreto para estabelecer a estrutura, a competência e o funcionamento dos conselhos.", "s": "Dois conselhos NACIONAIS, um só de comandantes-gerais de PM (CNCGPM) e outro só de CBM (CNCGBM) — não é um conselho misto único."}'::jsonb),
('law_14751', 47, '{"t": "art", "n": "Art. 38", "x": "As polícias militares e os corpos de bombeiros militares devem promover instâncias de participação social e nomear representantes no Conselho de Segurança Pública e Defesa Social (Lei nº 13.675/2018), a fim de garantir diálogo com a sociedade e fomentar a participação cidadã na gestão de políticas públicas de segurança.\nParágrafo único. No Conselho de Segurança Pública e Defesa Social, o representante da instituição militar deverá: I- divulgar as informações solicitadas (ressalvado sigilo legal); II- apresentar procedimentos e protocolos empregados, para maior transparência; III- apresentar o relatório anual; IV- pronunciar-se sobre outros assuntos submetidos em sua área de competência.", "s": "Mais uma conexão com a Lei nº 13.675/2018 (marco do SUSP) — e o relatório anual citado no inciso III é o mesmo relatório do art. 29, §5º."}'::jsonb),
('law_14751', 48, '{"t": "art", "n": "Art. 39", "x": "A adoção do requisito de escolaridade para ingresso na instituição militar será processada no prazo de até 6 (seis) anos a contar da publicação desta Lei.\nParágrafo único. Na forma da legislação de ensino do ente federado, a instituição poderá optar por formar o militar do Estado e do DF em curso de formação de educação superior com equivalência aos definidos no art. 44 da Lei nº 9.394/1996 (LDB), concedendo-lhe o requisito de ingresso do art. 13, IX, e do art. 15 (bacharel em direito ou em ciências policiais).", "s": "O requisito de ESCOLARIDADE SUPERIOR (art. 13, IX) não é imediato: tem prazo de até 6 ANOS pra ser implantado a partir da publicação (12/12/2023) — decore esse prazo de transição."}'::jsonb),
('law_14751', 49, '{"t": "art", "n": "Art. 40", "x": "São estabelecidas as seguintes regras de transição, na data de publicação desta Lei: (“Caput” do artigo vetado pelo Presidente da República, mantido pelo Congresso Nacional e publicado no DOU de 13/6/2024) I- os integrantes dos diversos quadros de oficiais oriundos da carreira de praça terão 180 dias para optar por permanecer no seu quadro ou ingressar no QOE; (Inciso vetado pelo Presidente, mantido pelo Congresso, DOU 13/6/2024) II- os integrantes dos quadros de praças com supressão de graduações terão 180 dias para optar por permanecer no seu quadro ou ingressar na nova carreira. (Inciso vetado pelo Presidente, mantido pelo Congresso, DOU 13/6/2024)", "s": "Artigo INTEIRO (caput + incisos I e II) foi vetado pelo Presidente, mas TODO ele foi mantido pelo Congresso — ou seja, apesar de “vetado”, este artigo 40 está em pleno vigor, com o prazo de 180 DIAS pra opção de quadro."}'::jsonb),
('law_14751', 50, '{"t": "art", "n": "Art. 41", "x": "Após solicitação dos interessados, os integrantes dos cargos das polícias militares e dos corpos de bombeiros militares poderão exercer funções no âmbito de outro ente federado, mediante permuta ou cessão, condicionada à autorização expressa dos respectivos comandantes-gerais e à legislação aplicável, sem qualquer prejuízo, asseguradas todas as prerrogativas, direitos e vantagens de seu Estado de origem. (Artigo vetado pelo Presidente da República, mantido pelo Congresso Nacional e publicado no DOU de 13/6/2024)", "s": "Mais um artigo INTEIRO vetado pelo Presidente e MANTIDO pelo Congresso — ou seja, a permuta/cessão entre Estados É PERMITIDA e está em vigor, apesar do veto presidencial original."}'::jsonb),
('law_14751', 51, '{"t": "art", "n": "Art. 42", "x": "A Lei nº 13.675, de 11 de junho de 2018, passa a vigorar com a seguinte alteração no art. 4º: “IX - uso comedido e proporcional da força pelos agentes da segurança pública, pautado nos documentos internacionais de proteção aos direitos humanos de que o Brasil seja signatário.”", "s": "Esta lei também ALTERA a Lei nº 13.675/2018 (marco do SUSP), inserindo o princípio do uso comedido e proporcional da força — reforça o art. 4º, XIV, desta própria Lei 14.751 (uso racional da força/uso progressivo dos meios)."}'::jsonb),
('law_14751', 52, '{"t": "art", "n": "Art. 43", "x": "Revogam-se os seguintes dispositivos do Decreto-Lei nº 667, de 2 de julho de 1969: I- arts. 1º e 2º; II- alíneas “d” e “e” do caput e §§1º, 2º e 3º do art. 3º; III- arts. 4º a 17; IV- arts. 21 a 23; V- arts. 25 a 28.", "s": "O Decreto-Lei nº 667/1969 era a antiga norma-geral das PMs — esta Lei 14.751/2023 o substitui, revogando boa parte dele (mas não tudo, alguns dispositivos residuais continuam)."}'::jsonb),
('law_14751', 53, '{"t": "art", "n": "Art. 44", "x": "Esta Lei entra em vigor na data de sua publicação.\nBrasília, 12 de dezembro de 2023; 202º da Independência e 135º da República.\nLUIZ INÁCIO LULA DA SILVA", "s": "Vigência: na PUBLICAÇÃO (12/12/2023) — mesma regra clássica de sempre. Sancionada pelo Presidente Lula."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('law_comparativo', 0, '{"tema": "Natureza / quem faz a lei", "l6513": "Lei ESTADUAL do Maranhão (1995) — Estatuto pessoal do policial-militar: situação, direitos, deveres, carreira.", "l12896": "Lei ESTADUAL do Maranhão (2026) — Organização básica da PMMA: estrutura, órgãos, efetivo, competências específicas.", "l14751": "Lei FEDERAL (2023), de competência privativa da União (art. 22, XXI, CF) — normas gerais que TODOS os Estados devem seguir."}'::jsonb),
('law_comparativo', 1, '{"tema": "Hierarquia entre as três", "l6513": "Deve se harmonizar com a 12.896/2026 e com o piso nacional da 14.751/2023 (várias promoções foram alteradas por esta última).", "l12896": "Expressamente se declara fundada na Lei 14.751/2023 (art. 2º da Lei 12.896) — é a aplicação estadual da lei nacional.", "l14751": "É a norma de TOPO: fixa o piso nacional; leis estaduais (como as duas primeiras) não podem contrariá-la, só detalhar."}'::jsonb),
('law_comparativo', 2, '{"tema": "Assunto principal", "l6513": "Direitos, deveres, ingresso, promoção, punições e situação do MILITAR como pessoa/servidor.", "l12896": "Estrutura ORGANIZACIONAL da PMMA (unidades, comandos, efetivo de 14.290, órgãos).", "l14751": "Modelo NACIONAL comum de organização, competências, garantias e hierarquia pra toda PM/CBM do país."}'::jsonb),
('law_comparativo', 3, '{"tema": "Órgãos de direção/apoio/execução/correição", "l6513": "Não trata desse tema (é sobre o servidor, não sobre a estrutura).", "l12896": "Copia a estrutura de 5 órgãos da Lei 14.751/2023 (art. 10) — Direção, Assessoramento, Apoio, Execução, Correição.", "l14751": "Cria e define os 5 órgãos básicos (art. 10) que todo Estado deve preferencialmente seguir."}'::jsonb),
('law_comparativo', 4, '{"tema": "Praça especial / hierarquia", "l6513": "Praça especial = só Aspirante-a-Oficial e Cadete (art. 19, §3º).", "l12896": "Segue a hierarquia definida no Estatuto (Lei 6.513/95), sem recriar a lista.", "l14751": "Praça especial = Aspirante-a-Oficial + Cadete + ALUNO-OFICIAL (art. 12, II) — lista mais ampla que a estadual."}'::jsonb),
('law_comparativo', 5, '{"tema": "Marco de 10 anos p/ candidatura eletiva", "l6513": "Prevê a mesma regra (art. 14, CF) mas de forma estadual, ligada ao Estatuto.", "l12896": "Não repete o tema (é sobre estrutura, não sobre direitos individuais).", "l14751": "Art. 22: menos de 10 anos = afastado; mais de 10 anos = agregado e, se eleito, vai pra reserva na diplomação."}'::jsonb),
('law_comparativo', 6, '{"tema": "Promoções — datas e critérios", "l6513": "Regra original (art. 78/79-A) alterada pela própria Lei 12.896/2026 (arts. 122-123).", "l12896": "Atualiza o Estatuto de 1995: promoções passam a ser em MARÇO, AGOSTO e DEZEMBRO (3 datas/ano).", "l14751": "Fixa só o critério geral (antiguidade e merecimento, art. 14) — não entra em datas específicas, isso é regulado no plano estadual."}'::jsonb),
('law_comparativo', 7, '{"tema": "CBMMA (Corpo de Bombeiros)", "l6513": "Art. 167: os dispositivos do Estatuto também se aplicam ao CBMMA.", "l12896": "Trata da PMMA; o CBMMA é orgânico da PM (mesma estrutura, conforme a lei federal).", "l14751": "Art. 6º, §3º: no modelo em que o CBM é orgânico da PM, as competências de bombeiro são exercidas dentro da própria PM."}'::jsonb),
('law_comparativo', 8, '{"tema": "Vedação de treinamento militar a civis", "l6513": "Não trata do tema.", "l12896": "Art. 4º, XXV: veda cooperação para formação/treinamento militar de instituições civis.", "l14751": "Art. 8º, parágrafo único: mesma vedação, na norma nacional que a lei estadual reproduziu."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('teoria_portugues', 0, '{"t": "tit", "x": "LÍNGUA PORTUGUESA"}'::jsonb),
('teoria_portugues', 1, '{"t": "cap", "x": "Compreensão e Interpretação de Textos"}'::jsonb),
('teoria_portugues', 2, '{"t": "art", "n": "Regra de ouro CEBRASPE", "x": "O item só pode ser julgado CERTO se puder ser comprovado pelo texto. Informação verdadeira no mundo real, mas que o texto não diz (ou nega), torna o item ERRADO — e vice-versa.", "s": "Nunca julgue pelo que você sabe do assunto; julgue pelo que está (ou não está) escrito."}'::jsonb),
('teoria_portugues', 3, '{"t": "art", "n": "Inferência x cópia literal", "x": "CEBRASPE mistura trechos copiados (fáceis) com paráfrases/inferências (mais difíceis, exigem interpretar a ideia, não decorar a frase).", "s": "Desconfie de itens que parafraseiam bem o texto, mas trocam um conectivo-chave (ex.: troca causa por consequência) — mudança sutil que inverte o sentido."}'::jsonb),
('teoria_portugues', 4, '{"t": "cap", "x": "Tipos e Gêneros Textuais"}'::jsonb),
('teoria_portugues', 5, '{"t": "art", "n": "Tipos textuais (5 clássicos)", "x": "Narrativo (conta fatos/sequência temporal), descritivo (características), dissertativo-argumentativo (defende tese), expositivo (explica/informa sem defender tese) e injuntivo (instrui/manda fazer, ex.: receita, manual, bula).", "s": "Um mesmo gênero (ex.: notícia) pode misturar tipos (narra o fato + descreve o cenário)."}'::jsonb),
('teoria_portugues', 6, '{"t": "art", "n": "Gênero x tipo", "x": "Gênero é a forma social concreta do texto (e-mail, edital, crônica, ofício); tipo é a estrutura interna (narrar, descrever, argumentar...). Um gênero pode conter vários tipos textuais.", "s": "Editais/leis = gênero expositivo-normativo; usam muito o tipo injuntivo (“compete a...”, “é vedado...”)."}'::jsonb),
('teoria_portugues', 7, '{"t": "cap", "x": "Ortografia Oficial"}'::jsonb),
('teoria_portugues', 8, '{"t": "art", "n": "Acordo Ortográfico — trema e acentos diferenciais", "x": "Trema foi abolido (exceto em nomes próprios/estrangeiros). Acento diferencial só sobrevive em “pôde” (passado) x “pode” (presente) e “pôr” (verbo) x “por” (preposição).", "s": "“Pára” (verbo parar) NÃO tem mais acento — é “para” igual à preposição; só o contexto diferencia."}'::jsonb),
('teoria_portugues', 9, '{"t": "art", "n": "Hiato ei/oi em paroxítonas", "x": "Não se acentuam mais os ditongos abertos “ei” e “oi” em palavras paroxítonas: “ideia”, “plateia”, “heroico”, “jiboia” (sem acento).", "s": "Continuam acentuadas as OXÍTONAS terminadas em “éis/éu/éis” (ex.: “herói”, “papéis”, “chapéu”)."}'::jsonb),
('teoria_portugues', 10, '{"t": "art", "n": "Por que / porque / por quê / porquê", "x": "“Por que” (separado, sem acento) = em perguntas (diretas/indiretas) ou antes de verbo elíptico; “porque” (junto) = explicação/causa (resposta); “por quê” (fim de frase, tônico); “porquê” (substantivo, = motivo, aceita artigo: “o porquê”).", "s": "Truque: se der pra substituir por “pelo motivo que/de que”, é “porque” junto."}'::jsonb),
('teoria_portugues', 11, '{"t": "cap", "x": "Coesão Textual"}'::jsonb),
('teoria_portugues', 12, '{"t": "art", "n": "Referenciação (anáfora/catáfora)", "x": "Anáfora: retoma algo já dito (pronomes “ele/esse/tal”, elipse). Catáfora: anuncia algo que vem depois (“o seguinte:”, “isto:”).", "s": "Pronome relativo (“que/quem/cujo”) sempre retoma o termo IMEDIATAMENTE anterior — item que atribui a referência a um termo distante costuma estar errado."}'::jsonb),
('teoria_portugues', 13, '{"t": "art", "n": "Substituição lexical", "x": "Repetir a mesma palavra várias vezes é visto como falha de estilo; textos bons trocam por sinônimo, hiperônimo (termo mais geral) ou expressão resumitiva (“essa medida”, “tal fato”).", "s": "Cuidado: trocar por um termo com sentido LIGEIRAMENTE diferente muda o sentido — CEBRASPE cobra isso em reescrita."}'::jsonb),
('teoria_portugues', 14, '{"t": "art", "n": "Conectores — classificação", "x": "Adição: e, também, além disso. Adversidade/contraste: mas, porém, contudo, todavia, no entanto, entretanto. Causa: porque, já que, visto que, pois (no meio da oração). Conclusão: logo, portanto, assim, por conseguinte, pois (no INÍCIO da oração, com vírgula antes). Condição: se, caso, a menos que. Concessão: embora, ainda que, mesmo que, apesar de.", "s": "Pegadinha clássica: “mas” é o ÚNICO adversativo que NUNCA pode ser deslocado pra dentro da frase; os outros (contudo, todavia, no entanto, entretanto, porém) podem vir entre vírgulas no meio."}'::jsonb),
('teoria_portugues', 15, '{"t": "cap", "x": "Emprego de Tempos e Modos Verbais"}'::jsonb),
('teoria_portugues', 16, '{"t": "art", "n": "Indicativo x Subjuntivo x Imperativo", "x": "Indicativo = fato certo, real (“ele vai”). Subjuntivo = hipótese, dúvida, desejo, ordem indireta (“se ele for”, “espero que ele vá”, “talvez ele vá”). Imperativo = ordem/pedido direto (“vá!”, “não vá!”).", "s": "Depois de “embora/talvez/caso/se eu fosse/é possível que” — SEMPRE subjuntivo, nunca indicativo."}'::jsonb),
('teoria_portugues', 17, '{"t": "art", "n": "Correlação de tempos verbais", "x": "Período composto deve manter coerência temporal: pretérito perfeito pede pretérito imperfeito do subjuntivo (“pedi que viesse”, não “que venha”); futuro do presente combina com presente do subjuntivo (“pedirei que venha”).", "s": "Erro comum de prova: misturar presente numa oração e pretérito na outra sem justificativa (“Se eu estudo, teria passado” está incoerente)."}'::jsonb),
('teoria_portugues', 18, '{"t": "cap", "x": "Estrutura Morfossintática do Período"}'::jsonb),
('teoria_portugues', 19, '{"t": "art", "n": "Classes de palavras (10)", "x": "Variáveis: substantivo, adjetivo, artigo, numeral, pronome, verbo. Invariáveis: advérbio, preposição, conjunção, interjeição.", "s": "Palavra denotativa (“aliás, aliás”, “aí”, “aproximadamente”) não é advérbio nem conjunção oficialmente — é categoria à parte, mas cai pouco."}'::jsonb),
('teoria_portugues', 20, '{"t": "art", "n": "Coordenação x Subordinação", "x": "Coordenadas: orações independentes entre si, ligadas por conjunção coordenativa (e, mas, ou, logo, pois). Subordinadas: uma depende sintaticamente da outra (substantivas, adjetivas, adverbiais) — a subordinada exerce função de termo da principal.", "s": "Oração subordinada SUBSTANTIVA pode ser sujeito, objeto, predicativo etc. da principal (“É necessário QUE VOCÊ VENHA” = sujeito de “é necessário”)."}'::jsonb),
('teoria_portugues', 21, '{"t": "art", "n": "Pontuação — vírgula", "x": "Vírgula separa: itens de enumeração, orações coordenadas (exceto antes de “e” com sujeitos iguais), aposto, vocativo, adjunto adverbial deslocado, oração adjetiva EXPLICATIVA (restritiva não tem vírgula). NUNCA separa sujeito do predicado nem verbo do seu complemento direto (salvo intercalação).", "s": "“O relatório, que estava atrasado, foi entregue” (explicativa, com vírgula, vale pra TODOS os relatórios) ≠ “O relatório que estava atrasado foi entregue” (restritiva, sem vírgula, só ESSE relatório específico)."}'::jsonb),
('teoria_portugues', 22, '{"t": "art", "n": "Concordância verbal — sujeito composto", "x": "Sujeito composto ANTES do verbo = verbo no plural. Sujeitos ligados por “ou”/“nem” (exclusão) = verbo geralmente no singular. Verbos impessoais (haver=existir; fazer=tempo decorrido) ficam SEMPRE na 3ª pessoa do singular, nunca vão pro plural.", "s": "“Haviam muitos candidatos” está ERRADO — o certo é “Havia muitos candidatos” (have no sentido de existir é impessoal)."}'::jsonb),
('teoria_portugues', 23, '{"t": "art", "n": "Concordância nominal — casos especiais", "x": "“Anexo/incluso/obrigado” concordam em gênero/número com o substantivo a que se referem (“seguem anexas as fotos”). “Meio” como ADVÉRBIO é invariável (“ela estava meio triste”); como numeral/adjetivo concorda (“comeu meia maçã”).", "s": "“É proibido entrada” x “É proibida a entrada”: sem artigo definido antes do sujeito, “proibido/necessário/bom” ficam invariáveis; com artigo, concordam."}'::jsonb),
('teoria_portugues', 24, '{"t": "art", "n": "Regência verbal — casos cobrados", "x": "“Assistir” (ver/testemunhar) = transitivo INDIRETO, com “a” (“assisti AO filme”); “assistir” (ajudar/socorrer/morar) = transitivo DIRETO (“o médico assistiu o paciente”; “assiste em São Luís”). “Chegar/ir” pedem preposição “A” (não “em”): “cheguei a casa”, nunca “cheguei em casa”. “Preferir A a B” (nunca “preferir A do que B”).", "s": "“Visar” (pretender) = transitivo indireto, com “a” (“visa AO cargo”); “visar” (mirar/rubricar) = transitivo direto."}'::jsonb),
('teoria_portugues', 25, '{"t": "art", "n": "Crase — quando ocorre", "x": "Fusão da preposição “a” (exigida pelo verbo/nome) com o artigo feminino “a(s)”: ocorre antes de palavra feminina quando o verbo exige preposição “a”. Obrigatória em locuções adverbiais femininas de tempo/modo/lugar (“à noite”, “às pressas”, “à beira do rio”) e na expressão “à moda de” (mesmo oculta: “sapato à Luís XV”).", "s": "NUNCA antes de verbo, de palavra masculina (vira “ao”), antes de pronomes pessoais/de tratamento sem artigo (“a ela”, “a Vossa Excelência”) e antes de “quem”."}'::jsonb),
('teoria_portugues', 26, '{"t": "art", "n": "Colocação dos pronomes átonos", "x": "PRÓCLISE (pronome antes do verbo) é obrigatória depois de: palavra negativa (não, nunca, ninguém), pronome relativo, conjunção subordinativa, advérbio (sem vírgula depois), e em orações iniciadas por palavra interrogativa/exclamativa. ÊNCLISE (depois do verbo) é a regra padrão quando não há fator de próclise, inclusive no início de frase/período. MESÓCLISE só no futuro do presente/pretérito, sem fator de próclise (“dar-te-ei”, “far-se-ia”).", "s": "“Não SE DEVE fazer isso” (próclise, por causa do “não”) x “DEVE-SE fazer isso” (ênclise, início de frase sem fator de próclise)."}'::jsonb),
('teoria_portugues', 27, '{"t": "cap", "x": "Reescrita de Frases e Parágrafos"}'::jsonb),
('teoria_portugues', 28, '{"t": "art", "n": "O que CEBRASPE testa na reescrita", "x": "Se a reescrita mantém o SENTIDO ORIGINAL e está gramaticalmente correta, é CERTO; qualquer mudança de sentido (troca de conectivo lógico, negação invertida, ambiguidade nova) torna ERRADO.", "s": "Trocar oração subordinada por termo equivalente (“já que chovia” → “por causa da chuva”) é válido SE o sentido de causa/consequência/condição permanecer igual."}'::jsonb),
('teoria_portugues', 29, '{"t": "art", "n": "Nível de formalidade", "x": "Textos oficiais pedem registro FORMAL/culto: evitar gírias, coloquialismos, abreviações informais e 2ª pessoa do singular direta (prefere-se “Vossa Senhoria” + 3ª pessoa).", "s": "Reescrever uma frase informal pra formal exige trocar pronome de tratamento E a concordância verbal junto (3ª pessoa)."}'::jsonb),
('teoria_portugues', 30, '{"t": "cap", "x": "Correspondência Oficial — Manual de Redação da Presidência da República"}'::jsonb),
('teoria_portugues', 31, '{"t": "art", "n": "Padrão Ofício", "x": "A edição atual do Manual unificou ofício, memorando e aviso num único modelo chamado “Padrão Ofício” — mesma estrutura de formatação para comunicação interna e externa da Administração Pública.", "s": "Não confunda: isso não eliminou os NOMES dos documentos (ainda existe “ofício”, “memorando”), só padronizou o FORMATO de diagramação deles."}'::jsonb),
('teoria_portugues', 32, '{"t": "art", "n": "Princípios da redação oficial", "x": "Impessoalidade (sem marcas de individualidade de quem escreve), clareza, concisão, formalidade e padronização (uniformidade) são os 5 princípios centrais cobrados.", "s": "“Impessoalidade” é o mais cobrado: o texto oficial fala em nome do órgão/cargo, não da pessoa — por isso usa 3ª pessoa e evita opinião pessoal."}'::jsonb),
('teoria_portugues', 33, '{"t": "art", "n": "Pronomes de tratamento", "x": "Vossa Excelência: altas autoridades dos 3 Poderes (Presidente, Ministros, Governadores, Deputados, Oficiais-generais). Vossa Senhoria: demais autoridades e particulares em geral. Concordância: 3ª pessoa (“Vossa Excelência DETERMINOU”, nunca “determinastes”), mas o possessivo relativo à pessoa do destinatário usa “seu/sua” (não “vosso”, salvo em orações diretamente endereçadas de forma arcaica).", "s": "Vocativo de autoridade superior: “Excelentíssimo Senhor Presidente” (ou abreviado “Excelentíssimo Senhor”); endereçamento em envelope difere do vocativo no corpo do texto."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('teoria_geografia', 0, '{"t": "tit", "x": "GEOGRAFIA DO MARANHÃO"}'::jsonb),
('teoria_geografia', 1, '{"t": "cap", "x": "Localização, Limites, Fronteiras e Áreas Protegidas"}'::jsonb),
('teoria_geografia', 2, '{"t": "art", "n": "Localização e limites", "x": "O Maranhão fica na transição entre o Nordeste e a Amazônia (muitas vezes chamado de estado de “transição” ou “Amazônia Oriental”). Faz limite com o Pará (oeste, divisa pelo rio Gurupi), Tocantins e Piauí (leste/sudeste, divisa em parte pelo rio Parnaíba) e tem litoral voltado para o Oceano Atlântico (reentrâncias maranhenses, um litoral bastante recortado, com baías e ilhas — diferente do litoral retilíneo típico do Nordeste).", "s": "Pegadinha clássica: o Maranhão é tecnicamente classificado como estado da Região NORDESTE pelo IBGE, apesar de boa parte do seu território, clima e vegetação serem de transição com a Amazônia — não confunda classificação político-administrativa com características físicas.", "img": "mapaMA"}'::jsonb),
('teoria_geografia', 3, '{"t": "art", "n": "Unidades de conservação", "x": "O estado tem diversas Áreas de Proteção Ambiental (APAs) e Parques — destaque para o Parque Nacional dos Lençóis Maranhenses (dunas de areia branca com lagoas de água da chuva, no litoral norte) e o Parque Nacional da Chapada das Mesas (cachoeiras e formações rochosas, no sul do estado).", "s": "Os Lençóis Maranhenses NÃO são deserto — são dunas móveis formadas por areia marinha/fluvial, e as lagoas enchem na estação chuvosa (período das chuvas), ficando praticamente secas no auge da seca — item que chama de “deserto” está errado."}'::jsonb),
('teoria_geografia', 4, '{"t": "cap", "x": "Clima"}'::jsonb),
('teoria_geografia', 5, '{"t": "art", "n": "Clima predominante", "x": "Clima tropical, quente o ano todo, com estação chuvosa (verão, chuvas concentradas em torno de janeiro a junho, influência da ZCIT — Zona de Convergência Intertropical) e estação seca (segundo semestre). O litoral tem clima tropical úmido (maior pluviosidade); o sul do estado, perto da Chapada das Mangabeiras/divisa com o cerrado, tende a ser mais seco e quente, com características de transição para o semiárido.", "s": "A ZCIT (mesma sigla usada no edital de legislação sobre o clima de São Luís) é o fator-chave que explica a concentração das chuvas no 1º semestre, especialmente no norte do estado."}'::jsonb),
('teoria_geografia', 6, '{"t": "cap", "x": "Relevo"}'::jsonb),
('teoria_geografia', 7, '{"t": "art", "n": "Grandes unidades de relevo", "x": "Baixada Maranhense (planície costeira/fluvial no norte-noroeste, área baixa, alagável, de grande biodiversidade — berço de parte da pecuária bubalina do estado); planaltos e chapadas no interior/sul (destaque pra Chapada das Mangabeiras, limite com o Tocantins/Piauí, e divisor de águas entre as bacias do Tocantins-Araguaia e do Parnaíba); predominância de altitudes baixas a medianas (sem grandes serras).", "s": "A pecuária de BÚFALOS é um traço geográfico/econômico típico da Baixada Maranhense (áreas alagadas), diferente da pecuária bovina comum no resto do estado."}'::jsonb),
('teoria_geografia', 8, '{"t": "cap", "x": "Hidrografia"}'::jsonb),
('teoria_geografia', 9, '{"t": "art", "n": "Rios limítrofes (fronteira) x rios internos", "x": "Rios LIMÍTROFES (fazem fronteira com outro estado): Parnaíba (divisa com o Piauí, a leste) e Gurupi (divisa com o Pará, a oeste); o Tocantins-Araguaia corre próximo à divisa com o Tocantins, no extremo sul/sudoeste. Rios genuinamente maranhenses (nascem e deságuam dentro do estado, sem servir de fronteira): Itapecuru, Mearim, Pindaré, Grajaú, Munim — a maioria deságua na Baía de São Marcos ou na Baía de São José, no litoral norte.", "s": "Pegadinha: “Tocantins-Araguaia é um rio genuinamente maranhense” está ERRADO — ele só tangencia/limita o extremo sul do estado, é compartilhado com outros estados (TO, PA)."}'::jsonb),
('teoria_geografia', 10, '{"t": "cap", "x": "Vegetação"}'::jsonb),
('teoria_geografia', 11, '{"t": "art", "n": "Três grandes domínios vegetais", "x": "Floresta Amazônica (oeste do estado, transição amazônica); Cerrado (sul/sudeste, transição com o Brasil Central); e a vegetação de transição conhecida como “Mata dos Cocais” (região central, faixa que mistura babaçuais — palmeiras de babaçu — com carnaubais e elementos de caatinga/cerrado) — uma paisagem geográfica praticamente exclusiva do Maranhão/Piauí.", "s": "“Mata dos Cocais” é o nome técnico pra explicar por que o Maranhão virou o maior produtor de babaçu do país (ligado à aula de História que já vimos) — são vegetações DIFERENTES (Amazônia / Cocais / Cerrado), não uma mistura única."}'::jsonb),
('teoria_geografia', 12, '{"t": "cap", "x": "População"}'::jsonb),
('teoria_geografia', 13, '{"t": "art", "n": "Distribuição e migrações", "x": "Povoamento historicamente concentrado no litoral (São Luís e região metropolitana) e ao longo dos rios; o interior/sul do estado (regiões de fronteira agrícola, como Balsas e a região dos “Gerais de Balsas”) recebeu forte migração de agricultores do Sul/Sudeste a partir das décadas de 1970-1980, atraídos pela expansão da soja no cerrado maranhense (parte do chamado MATOPIBA — Maranhão, Tocantins, Piauí, Bahia).", "s": "MATOPIBA é sigla certeira de prova: a nova fronteira agrícola do cerrado brasileiro, da qual o sul do Maranhão faz parte."}'::jsonb),
('teoria_geografia', 14, '{"t": "cap", "x": "Agricultura, Pecuária e Extrativismo"}'::jsonb),
('teoria_geografia', 15, '{"t": "art", "n": "Atividades econômicas primárias", "x": "Agricultura: soja, milho e algodão em expansão no sul (MATOPIBA, agricultura mecanizada de exportação); arroz e mandioca tradicionais em pequenas propriedades. Pecuária: bovina disseminada pelo estado, bubalina concentrada na Baixada Maranhense. Extrativismo vegetal: babaçu (amêndoa/óleo, atividade histórica das “quebradeiras de coco”, já vista em História); extrativismo mineral: destaque para o minério de ferro da Serra dos Carajás (PA), escoado pela Estrada de Ferro Carajás até o Porto do Itaqui, em São Luís.", "s": "O minério de ferro em si vem do Pará (Carajás) — o Maranhão entra como rota de ESCOAMENTO (ferrovia + porto), não como produtor do minério; é um erro comum achar que a mina fica no Maranhão."}'::jsonb),
('teoria_geografia', 16, '{"t": "cap", "x": "Indústria e Setor Terciário"}'::jsonb),
('teoria_geografia', 17, '{"t": "art", "n": "Parque industrial e serviços", "x": "Industrialização tardia e concentrada em São Luís: destaque para a ALUMAR (Consórcio de Alumínio do Maranhão — produção de alumina e alumínio, não ferro-gusa, como já visto em História) e a indústria ligada ao Porto do Itaqui. O setor terciário (comércio e serviços) é o maior empregador do estado, concentrado na capital.", "s": "Mesma pegadinha de História: ALUMAR = alumínio, nunca “siderúrgica de ferro-gusa/aço inoxidável”."}'::jsonb),
('teoria_geografia', 18, '{"t": "cap", "x": "Malha Viária, Portos e Aeroportos"}'::jsonb),
('teoria_geografia', 19, '{"t": "art", "n": "Principais infraestruturas de transporte", "x": "Porto do Itaqui (São Luís): um dos principais portos de granéis (minério, soja) do Brasil, ligado à Estrada de Ferro Carajás. Principais rodovias federais: BR-135 (liga São Luís ao sul do estado/Tocantins) e BR-316/BR-222 (ligação com o Piauí/Pará). Aeroporto Internacional Marechal Cunha Machado, em São Luís, o principal do estado.", "s": "A combinação “ferrovia (Carajás) + porto (Itaqui)” é o eixo logístico mais cobrado em prova — decore essa dupla."}'::jsonb),
('teoria_geografia', 20, '{"t": "cap", "x": "Cultura Maranhense"}'::jsonb),
('teoria_geografia', 21, '{"t": "art", "n": "Síntese cultural (já vista em História)", "x": "Patrimônio arquitetônico colonial de São Luís (azulejos portugueses, Patrimônio Mundial UNESCO desde 1997); Bumba-meu-boi (Patrimônio Imaterial da Humanidade, UNESCO 2019); forte identidade reggae (“Jamaica Brasileira”); culinária com influências indígena/africana/portuguesa (arroz de cuxá).", "s": "Essa parte se conecta diretamente com os quadrinhos e a aula de História do Maranhão já disponíveis no app — não é conteúdo isolado."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('teoria_ingles', 0, '{"t": "tit", "x": "LÍNGUA ESTRANGEIRA — INGLÊS"}'::jsonb),
('teoria_ingles', 1, '{"t": "cap", "x": "Estratégias de Leitura (estilo CEBRASPE)"}'::jsonb),
('teoria_ingles', 2, '{"t": "art", "n": "Como a banca cobra Inglês", "x": "CEBRASPE normalmente apresenta um texto curto (notícia, trecho institucional) e pede julgamento Certo/Errado sobre afirmações em português OU em inglês sobre o conteúdo do texto — raramente cobra gramática pura isolada, o foco é compreensão.", "s": "Mesma regra de ouro do Português: julgue pelo que o texto diz, não pelo que você sabe do assunto em geral."}'::jsonb),
('teoria_ingles', 3, '{"t": "art", "n": "Palavras-chave de negação e restrição", "x": "Fique atento a: not, no, never, hardly, barely, few, little, unless, except, without — elas invertem ou restringem o sentido de uma frase e são o alvo favorito de pegadinha de prova.", "s": "“She rarely travels” (ela raramente viaja) é quase o OPOSTO de “she regularly travels”; um item que trocar “rarely” por “always” está errado."}'::jsonb),
('teoria_ingles', 4, '{"t": "cap", "x": "Falsos Cognatos (false friends) Mais Cobrados"}'::jsonb),
('teoria_ingles', 5, '{"t": "art", "n": "Lista de falsos cognatos clássicos", "x": "actually = na verdade (não “atualmente”, isso é “currently/nowadays”); parents = pais (não “parentes”, isso é “relatives”); push = empurrar (não “puxar”, isso é “pull”); pretend = fingir (não “pretender”, isso é “intend”); realize = perceber/dar-se conta (não necessariamente “realizar”, que é “carry out/accomplish”); library = biblioteca (não “livraria”, que é “bookstore”); college = faculdade (não “colégio”, que é “high school”).", "s": "Esses 7 são os mais recorrentes em provas de nível médio/concurso — decore em pares (palavra em inglês x armadilha em português)."}'::jsonb),
('teoria_ingles', 6, '{"t": "cap", "x": "Conectores e Estruturas Gramaticais Relevantes"}'::jsonb),
('teoria_ingles', 7, '{"t": "art", "n": "Conectores de contraste, causa e condição", "x": "Contraste: although/though/even though (seguido de oração), despite/in spite of (seguido de substantivo/gerúndio), however (início de frase, com vírgula). Causa: because (oração), because of/due to (substantivo). Condição: if (condicional comum), unless (= “if...not”, condição negativa).", "s": "“Despite” e “although” têm o MESMO sentido (contraste), mas estrutura diferente: despite + substantivo/-ing; although + sujeito + verbo."}'::jsonb),
('teoria_ingles', 8, '{"t": "art", "n": "Verbos modais mais cobrados", "x": "Must/have to = obrigação; should = recomendação/conselho; can/could = capacidade/permissão; may/might = possibilidade; must not = proibição (diferente de “don’t have to” = não é obrigatório, mas é permitido).", "s": "Pegadinha clássica: “must not” (proibido) ≠ “don’t have to” (opcional) — são opostos em força, não sinônimos."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('teoria_logica', 0, '{"t": "tit", "x": "RACIOCÍNIO LÓGICO"}'::jsonb),
('teoria_logica', 1, '{"t": "cap", "x": "Estruturas Lógicas e Argumentação"}'::jsonb),
('teoria_logica', 2, '{"t": "art", "n": "Dedução x Indução x Analogia", "x": "Dedução: a conclusão decorre NECESSARIAMENTE das premissas (se as premissas são verdadeiras, a conclusão é certamente verdadeira). Indução: generaliza a partir de casos observados (conclusão apenas provável, não garantida). Analogia: raciocínio por semelhança entre relações (A está para B assim como C está para D).", "s": "CEBRASPE cobra principalmente argumentos DEDUTIVOS — a tarefa mais comum é verificar se uma conclusão decorre logicamente de premissas dadas, não avaliar a “qualidade” do argumento indutivo."}'::jsonb),
('teoria_logica', 3, '{"t": "cap", "x": "Lógica Proposicional"}'::jsonb),
('teoria_logica', 4, '{"t": "art", "n": "Proposições simples e compostas", "x": "Proposição simples: uma única afirmação, com valor lógico V ou F (ex.: “Chove”). Proposição composta: duas ou mais proposições simples ligadas por um conectivo lógico.", "s": "Todo cuidado com frases que parecem simples mas escondem um “e”/“ou” implícito (ex.: “João e Maria foram ao cinema” = duas proposições simples unidas por “e”)."}'::jsonb),
('teoria_logica', 5, '{"t": "art", "n": "Os 5 conectivos e suas tabelas-verdade", "x": "Negação (~p): inverte o valor. Conjunção (p∧q, “e”): só é V quando AMBAS são V. Disjunção inclusiva (p∨q, “ou”): só é F quando AMBAS são F (basta uma V pra ser V). Disjunção exclusiva (“ou...ou”): V quando exatamente UMA é V (as duas iguais = F). Condicional (p→q, “se...então”): só é FALSA no caso p=V e q=F — em todos os outros 3 casos é V. Bicondicional (p↔q, “se e somente se”): V quando p e q têm o MESMO valor (ambas V ou ambas F).", "s": "O condicional é o mais cobrado e o mais mal-entendido: “se p então q” é falsa SÓ quando a condição (p) se cumpre mas a consequência (q) não acontece — fora isso (inclusive quando p é falsa), o condicional inteiro é considerado VERDADEIRO."}'::jsonb),
('teoria_logica', 6, '{"t": "art", "n": "Leis de De Morgan (negação de conjunção/disjunção)", "x": "~(p∧q) ≡ (~p)∨(~q) — negar “e” vira “ou” com os termos negados. ~(p∨q) ≡ (~p)∧(~q) — negar “ou” vira “e” com os termos negados.", "s": "Exemplo prático: negar “Pedro é alto e magro” = “Pedro NÃO é alto OU NÃO é magro” (não é “Pedro não é alto e não é magro” com “e”)."}'::jsonb),
('teoria_logica', 7, '{"t": "art", "n": "Negação do condicional", "x": "~(p→q) ≡ p∧(~q) — a negação de “se p então q” é “p e não-q” (afirma a condição, nega a consequência).", "s": "Negar “Se chove, então a rua molha” = “Chove e a rua NÃO molha” — nunca é “se chove então a rua não molha” (isso trocaria o condicional por outro condicional, não é uma negação válida)."}'::jsonb),
('teoria_logica', 8, '{"t": "art", "n": "Equivalências lógicas úteis", "x": "p→q ≡ ~p∨q (todo condicional pode virar uma disjunção). p→q ≡ ~q→~p (contrapositiva — forma equivalente mais usada em prova disfarçada). Uma proposição e sua contrapositiva têm SEMPRE o mesmo valor lógico; a recíproca (q→p) e a inversa (~p→~q) NÃO são equivalentes ao condicional original.", "s": "Pegadinha maior da prova: achar que “se p então q” é a mesma coisa que “se q então p” (recíproca) — NÃO é; só a contrapositiva (~q→~p) é equivalente."}'::jsonb),
('teoria_logica', 9, '{"t": "cap", "x": "Diagramas Lógicos (Quantificadores)"}'::jsonb),
('teoria_logica', 10, '{"t": "art", "n": "Todo, Algum, Nenhum — e suas negações", "x": "“Todo A é B” (universal afirmativa) — negação correta é “Algum A não é B” (não é “Nenhum A é B”!). “Algum A é B” (particular afirmativa) — negação é “Nenhum A é B”. “Nenhum A é B” (universal negativa) — negação é “Algum A é B”.", "s": "Erro mais comum: achar que a negação de “Todo político é honesto” é “Nenhum político é honesto” — na verdade é só “Algum político NÃO é honesto” (basta UM político desonesto pra negar a frase inteira)."}'::jsonb),
('teoria_logica', 11, '{"t": "art", "n": "Diagramas de Venn — como representar", "x": "“Todo A é B”: o círculo A fica TOTALMENTE dentro do círculo B. “Algum A é B”: os círculos A e B se CRUZAM parcialmente (interseção não vazia, mas nenhum precisa estar contido no outro). “Nenhum A é B”: os círculos A e B NÃO se tocam (disjuntos).", "s": "Pra verificar se uma conclusão “Algum A é C” decorre de “Todo A é B” + “Todo B é C”, desenhe os 3 círculos encaixados (A dentro de B dentro de C) — a conclusão sai direto do desenho.", "img": "venn"}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('teoria_socorros', 0, '{"t": "tit", "x": "NOÇÕES DE PRIMEIROS SOCORROS"}'::jsonb),
('teoria_socorros', 1, '{"t": "cap", "x": "Avaliação Inicial da Vítima"}'::jsonb),
('teoria_socorros', 2, '{"t": "art", "n": "Sequência da avaliação inicial", "x": "1) Garantir a segurança da cena (sinalizar, afastar riscos) antes de se aproximar; 2) checar responsividade (chamar, tocar os ombros); 3) checar respiração e pulso; 4) acionar o serviço de emergência (SAMU 192/Bombeiros 193) o quanto antes, de preferência em paralelo ao atendimento.", "s": "Regra de ouro: socorrista NUNCA se expõe a risco pra salvar a vítima — cena insegura primeiro se torna segura, só depois começa o atendimento."}'::jsonb),
('teoria_socorros', 3, '{"t": "cap", "x": "Suporte Básico de Vida (SBV)"}'::jsonb),
('teoria_socorros', 4, '{"t": "art", "n": "Sequência C-A-B (parada cardiorrespiratória)", "x": "Protocolo atual prioriza: C (compressões torácicas, centro do peito, ritmo de ~100-120/min) → A (abertura das vias aéreas) → B (respiração/boa ventilação) — compressão vem ANTES da ventilação, diferente do antigo “ABC”.", "s": "Decore a ordem atual: C-A-B (compressão primeiro), não A-B-C — mudança de protocolo que CEBRASPE gosta de cobrar justamente por ser recente."}'::jsonb),
('teoria_socorros', 5, '{"t": "cap", "x": "Hemorragias"}'::jsonb),
('teoria_socorros', 6, '{"t": "art", "n": "Controle de hemorragias externas", "x": "1ª conduta: compressão DIRETA sobre o ferimento com pano limpo/gaze; se possível, elevar o membro acima do nível do coração. Torniquete é MEDIDA DE ÚLTIMO RECURSO, só quando a compressão direta falha ou em hemorragia maciça de membro, anotando o horário de aplicação.", "s": "Torniquete não é a primeira opção — item que recomenda torniquete como PRIMEIRA conduta pra qualquer sangramento está errado.", "img": "corpo"}'::jsonb),
('teoria_socorros', 7, '{"t": "cap", "x": "Fraturas"}'::jsonb),
('teoria_socorros', 8, '{"t": "art", "n": "Conduta geral em fraturas", "x": "Imobilizar o membro NA POSIÇÃO EM QUE FOI ENCONTRADO (nunca tentar realinhar ou “colocar no lugar”), imobilizando as articulações acima e abaixo do local da fratura, e encaminhar para atendimento médico.", "s": "Tentar reduzir/realinhar a fratura no local do acidente é erro grave — função do socorrista é imobilizar, não tratar a fratura."}'::jsonb),
('teoria_socorros', 9, '{"t": "cap", "x": "Queimaduras"}'::jsonb),
('teoria_socorros', 10, '{"t": "art", "n": "Conduta geral em queimaduras", "x": "Resfriar a área com água corrente em temperatura ambiente (nunca gelada/com gelo direto) por alguns minutos, remover acessórios/roupas que não estejam grudadas, cobrir com pano limpo. NUNCA aplicar pasta de dente, manteiga, gelo direto ou qualquer substância caseira sobre a queimadura.", "s": "Gelo direto PIORA a lesão (queimadura por frio somada à térmica) — item que recomenda gelo está errado."}'::jsonb),
('teoria_socorros', 11, '{"t": "cap", "x": "Obstrução de Vias Aéreas (OVACE)"}'::jsonb),
('teoria_socorros', 12, '{"t": "art", "n": "Manobra de Heimlich", "x": "Em vítima CONSCIENTE engasgada (sinal universal: mãos no pescoço), aplicar compressões abdominais bruscas (manobra de Heimlich) logo acima do umbigo, voltadas pra dentro e pra cima, até desobstruir. Em vítima inconsciente, inicia-se RCP (compressões torácicas) mesmo sem pulso ausente confirmado por obstrução.", "s": "Em gestantes/obesos, a compressão é feita no TÓRAX (não no abdome) — detalhe que costuma aparecer como pegadinha.", "img": "viasAereas"}'::jsonb),
('teoria_socorros', 13, '{"t": "cap", "x": "Transporte de Vítimas"}'::jsonb),
('teoria_socorros', 14, '{"t": "art", "n": "Princípios do transporte", "x": "Só mover a vítima se houver risco iminente na cena (incêndio, afogamento, trânsito) ou se for estritamente necessário pro atendimento; suspeita de lesão de coluna exige rolamento em bloco (“rolamento em prancha”), mantendo cabeça-pescoço-tronco alinhados, evitando qualquer torção.", "s": "Regra geral: na dúvida sobre lesão de coluna, trate como SE HOUVESSE lesão (imobilização cervical) — não arrisque movimentar sem técnica adequada."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('teoria_incendio', 0, '{"t": "tit", "x": "NOÇÕES DE COMBATE A INCÊNDIO"}'::jsonb),
('teoria_incendio', 1, '{"t": "cap", "x": "Teoria do Fogo"}'::jsonb),
('teoria_incendio', 2, '{"t": "art", "n": "Triângulo e Tetraedro do Fogo", "x": "O fogo precisa de 3 elementos básicos (triângulo do fogo): combustível (material que queima), comburente (geralmente o oxigênio do ar) e calor (energia de ativação). A versão mais completa, o TETRAEDRO do fogo, acrescenta um 4º elemento: a reação em cadeia (radicais livres que sustentam a combustão).", "s": "Remover QUALQUER um dos 4 elementos interrompe o fogo — essa é a base de todos os métodos de extinção.", "img": "fogo"}'::jsonb),
('teoria_incendio', 3, '{"t": "cap", "x": "Classes de Incêndio"}'::jsonb),
('teoria_incendio', 4, '{"t": "art", "n": "As 5 classes (padrão brasileiro)", "x": "Classe A: materiais sólidos comuns que deixam resíduo/brasa (madeira, papel, tecido). Classe B: líquidos e gases inflamáveis (gasolina, álcool, GLP) — queimam na superfície, sem brasa. Classe C: equipamentos elétricos ENERGIZADOS (nunca usar água nesse caso, risco de choque). Classe D: metais pirofóricos (magnésio, titânio, sódio) — reagem perigosamente com água. Classe K: óleos e gorduras de cozinha (incêndios em cozinhas industriais).", "s": "Pegadinha clássica: incêndio em equipamento elétrico DESLIGADO/sem energia vira Classe A ou B (conforme o material), deixa de ser Classe C — a classificação C é só enquanto o equipamento está energizado."}'::jsonb),
('teoria_incendio', 5, '{"t": "cap", "x": "Métodos de Extinção"}'::jsonb),
('teoria_incendio', 6, '{"t": "art", "n": "Os 4 métodos (ligados aos 4 lados do tetraedro)", "x": "Resfriamento: retira o CALOR (ex.: água). Abafamento: retira o COMBURENTE/oxigênio (ex.: espuma, cobertor). Isolamento (ou retirada do material): retira o COMBUSTÍVEL (ex.: cortar o gás, afastar material não queimado). Extinção química/quebra da reação em cadeia: interrompe a reação química do fogo (ex.: pó químico seco).", "s": "Cada agente extintor está ligado a UM (ou mais) desses 4 métodos — por isso é importante saber qual método cada agente usa, não só decorar o nome do agente."}'::jsonb),
('teoria_incendio', 7, '{"t": "cap", "x": "Agentes Extintores"}'::jsonb),
('teoria_incendio', 8, '{"t": "art", "n": "Água", "x": "Age por RESFRIAMENTO; indicada pra Classe A (sólidos). PROIBIDA em incêndio Classe C (equipamento energizado — risco de choque elétrico) e Classe D (reage perigosamente com metais pirofóricos) e não recomendada para Classe B de líquidos (pode espalhar o líquido inflamável, exceto como neblina em técnicas específicas).", "s": "“Pode usar água em qualquer incêndio” é a pegadinha mais básica e mais cobrada — água é restrita, não universal."}'::jsonb),
('teoria_incendio', 9, '{"t": "art", "n": "Espuma, CO2 e Pó Químico", "x": "Espuma: abafamento, indicada pra Classe A e B (não usar em C, é condutora e energizada por água). Gás carbônico (CO2): abafamento + resfriamento leve, indicado pra Classe B e C (não deixa resíduo, ideal pra equipamentos eletrônicos). Pó Químico Seco (PQS): quebra a reação em cadeia, indicado pra Classe B e C (e algumas formulações ABC, pra sólidos/líquidos/elétricos combinados).", "s": "CO2 é o preferido pra incêndio em computador/painel elétrico justamente por não deixar resíduo e não ser condutor — diferente da espuma e do pó.", "img": "extintor"}'::jsonb),
('teoria_incendio', 10, '{"t": "art", "n": "Agente Extintor para Classe D e Classe K", "x": "Classe D (metais pirofóricos): exige pó extintor ESPECIAL específico para metais (nunca água, nunca os extintores comuns ABC). Classe K (óleos/gorduras de cozinha): agente à base de acetato de potássio, que forma uma película de saponificação sobre o óleo quente — a água comum faria o óleo quente espirrar violentamente (efeito “slop-over”).", "s": "Incêndio em fritadeira industrial é Classe K, NUNCA tente apagar com água — risco de explosão/espirramento do óleo em chamas."}'::jsonb),
('teoria_incendio', 11, '{"t": "cap", "x": "EPI e Equipamentos de Proteção Respiratória (EPR)"}'::jsonb),
('teoria_incendio', 12, '{"t": "art", "n": "EPI básico do combate a incêndio", "x": "Capacete de combate, capuz, roupa de aproximação/estrutural, luvas, botas de segurança — protegem contra calor, impacto e produtos químicos durante a ação de combate direto.", "s": "EPI = proteção do CORPO; já o EPR (próximo tópico) é especificamente pra proteção RESPIRATÓRIA — são conjuntos complementares, não sinônimos."}'::jsonb),
('teoria_incendio', 13, '{"t": "art", "n": "EPR — Equipamento de Proteção Respiratória", "x": "O principal é o conjunto autônomo de respiração (popularmente chamado de SCBA, do inglês), com cilindro de ar comprimido próprio — usado em ambientes com fumaça densa, gases tóxicos ou deficiência de oxigênio, já que máscaras comuns (sem cilindro) não protegem contra falta de oxigênio.", "s": "Máscara contra gases SEM cilindro de ar próprio NÃO protege em ambiente com pouco oxigênio — só o equipamento autônomo (com ar próprio) garante isso."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('teoria_historia', 0, '{"t": "tit", "x": "MARANHÃO PRÉ-COLONIAL"}'::jsonb),
('teoria_historia', 1, '{"t": "cap", "x": "Povos Indígenas"}'::jsonb),
('teoria_historia', 2, '{"t": "art", "n": "Ocupação pré-colonial", "x": "O território do atual Maranhão era habitado por diversos povos indígenas muito antes da chegada dos europeus, com evidências arqueológicas de ocupação humana na ilha de São Luís e no continente que remontam a milhares de anos."}'::jsonb),
('teoria_historia', 3, '{"t": "art", "n": "Tupinambás", "x": "Os Tupinambás formavam o principal grupo indígena do litoral maranhense no início do século XVII, dominando a maior parte da costa, inclusive a ilha onde depois seria fundada São Luís. Falavam língua tupi e mantiveram alianças ora com franceses, ora com portugueses, durante a disputa colonial pela região."}'::jsonb),
('teoria_historia', 4, '{"t": "art", "n": "Tremembés e Tapuias", "x": "Os Tremembés ocupavam o litoral centro-leste, entre o Maranhão e o Ceará, até a baía de Turiaçu, e resistiram à expansão tupi. Genericamente chamados de ''tapuias'', os povos não-tupi foram em grande parte empurrados para o interior durante a chamada ''conquista tupi'' do litoral, configurando um cenário étnico diverso que os colonizadores europeus encontraram."}'::jsonb),
('teoria_historia', 5, '{"t": "tit", "x": "PERÍODO COLONIAL (1612-1755)"}'::jsonb),
('teoria_historia', 6, '{"t": "cap", "x": "A França Equinocial (1612)"}'::jsonb),
('teoria_historia', 7, '{"t": "art", "n": "Março de 1612 — Partida da expedição", "x": "A expedição francesa partiu do porto de Cancale, na Bretanha, em março de 1612, sob o comando de Daniel de La Touche, Senhor de La Ravardière, que havia passado cerca de quinze anos articulando o projeto de colonização. A frota levava aproximadamente 500 homens, vindos principalmente das cidades de Cancale, Granville e Saint-Malo."}'::jsonb),
('teoria_historia', 8, '{"t": "art", "n": "26 de julho de 1612 — Chegada", "x": "A esquadra francesa chegou a uma baía do litoral maranhense em 26 de julho de 1612. A expedição contava com apoio de nobres e comerciantes franceses para fundar a chamada França Equinocial em território tropical ainda não ocupado por Portugal."}'::jsonb),
('teoria_historia', 9, '{"t": "art", "n": "8 de setembro de 1612 — Fundação de São Luís", "x": "São Luís foi oficialmente fundada em 8 de setembro de 1612, com missa celebrada por frades capuchinhos e construção do Forte Saint-Louis, erguido com ajuda espontânea de indígenas locais. O nome homenageava Luís IX (santo padroeiro da França) e o então rei Luís XIII — tornando São Luís a única capital de estado brasileiro fundada por franceses."}'::jsonb),
('teoria_historia', 10, '{"t": "cap", "x": "Expulsão dos Franceses (1614-1615)"}'::jsonb),
('teoria_historia', 11, '{"t": "art", "n": "19 de novembro de 1614 — Batalha de Guaxenduba", "x": "Na Batalha de Guaxenduba, forças luso-espanholas e indígenas aliadas, comandadas por Jerônimo de Albuquerque, enfrentaram e derrotaram franceses e seus aliados tupinambás em combate decisivo. A vitória, obtida com uso de trincheiras e combates diretos, abriu caminho para o cerco final ao domínio francês."}'::jsonb),
('teoria_historia', 12, '{"t": "art", "n": "Jerônimo de Albuquerque e Alexandre de Moura", "x": "Jerônimo de Albuquerque, mestiço luso-indígena nascido em Pernambuco, comandou as tropas terrestres na campanha de reconquista. Alexandre de Moura, enviado com reforços vindos de Pernambuco, cercou o Forte de São Luís e, após tréguas violadas pelos franceses, forçou a rendição final da colônia."}'::jsonb),
('teoria_historia', 13, '{"t": "art", "n": "1615 — Expulsão definitiva", "x": "Em 1615 os franceses foram definitivamente expulsos do Maranhão, encerrando o projeto da França Equinocial. A vitória luso-espanhola garantiu que a foz do Amazonas e a região amazônica permanecessem sob domínio português, e não francês, moldando as futuras fronteiras do Brasil."}'::jsonb),
('teoria_historia', 14, '{"t": "cap", "x": "Os Capitães-Mores do Maranhão (1615-1621)"}'::jsonb),
('teoria_historia', 15, '{"t": "art", "n": "Administração direta da Coroa", "x": "Entre a expulsão definitiva dos franceses (1615) e a criação do Estado do Maranhão (1621), a capitania foi administrada por capitães-mores nomeados diretamente pela Coroa portuguesa — uma fase de administração direta, sem o caráter de capitania hereditária/donatária que marcou outras partes do Brasil colonial no mesmo período."}'::jsonb),
('teoria_historia', 16, '{"t": "art", "n": "Jerônimo de Albuquerque, administrador", "x": "Jerônimo de Albuquerque — o mesmo comandante vitorioso na Batalha de Guaxenduba (1614) — foi um dos primeiros capitães-mores a administrar a capitania do Maranhão logo após a reconquista, antes da estruturação mais autônoma trazida pela criação do Estado do Maranhão em 1621."}'::jsonb),
('teoria_historia', 17, '{"t": "cap", "x": "Invasão Holandesa (1641-1644)"}'::jsonb),
('teoria_historia', 18, '{"t": "art", "n": "25 de novembro de 1641 — Invasão", "x": "Uma esquadra holandesa com 19 navios e cerca de 2 mil soldados invadiu a Ilha de São Luís em 25 de novembro de 1641. A ação fazia parte da expansão holandesa no Nordeste, que já ocupara a Bahia (1624-1625) e Pernambuco (a partir de 1630), buscando agora controlar o acesso à Amazônia."}'::jsonb),
('teoria_historia', 19, '{"t": "art", "n": "1642-1644 — Resistência e expulsão", "x": "A resistência luso-brasileira começou ainda em 1641 e teve marco importante em 21 de novembro de 1642, quando as tropas de Muniz Barreiros e Teixeira de Melo derrotaram uma coluna holandesa comandada por Sandalim. Após anos de confrontos e pilhagens, os holandeses se retiraram definitivamente do Maranhão em 1644."}'::jsonb),
('teoria_historia', 20, '{"t": "cap", "x": "O Estado do Maranhão"}'::jsonb),
('teoria_historia', 21, '{"t": "art", "n": "13 de junho de 1621 — Criação do Estado do Maranhão", "x": "Por carta régia de 13 de junho de 1621, a coroa portuguesa criou o Estado do Maranhão, separando-o administrativamente do Estado do Brasil. A medida visava melhorar o contato da região amazônica com a metrópole e estimular a colonização e a exploração das ''drogas do sertão''."}'::jsonb),
('teoria_historia', 22, '{"t": "art", "n": "1626 — Instalação efetiva", "x": "Embora criado em 1621, o Estado do Maranhão só foi efetivamente instalado em 1626, com a posse do primeiro governador e capitão-general, Francisco Coelho de Carvalho. O Estado permaneceu subordinado diretamente a Lisboa e ao Conselho Ultramarino, sem vínculo com o governo-geral sediado no restante do Brasil."}'::jsonb),
('teoria_historia', 23, '{"t": "art", "n": "Mudanças de nome do Estado", "x": "A unidade administrativa passou por sucessivas denominações: Estado do Maranhão (1621-1654), depois Estado do Maranhão e Grão-Pará (1654-1751) e, por fim, Estado do Grão-Pará e Maranhão (1751-1772), quando foi extinto e incorporado ao restante da administração colonial portuguesa."}'::jsonb),
('teoria_historia', 24, '{"t": "cap", "x": "Século XVIII — Companhias de Comércio e Apogeu Econômico"}'::jsonb),
('teoria_historia', 25, '{"t": "art", "n": "1682 — Primeira Companhia de Comércio", "x": "Em 12 de fevereiro de 1682, sob o rei D. Pedro II, foi criada a primeira Companhia Geral de Comércio do Maranhão, com monopólio comercial e fornecimento de crédito e escravizados africanos aos produtores locais. A companhia não cumpriu suas obrigações (faltou crédito e mão de obra prometidos) e foi extinta em 1685, após provocar a revolta popular conhecida como Revolta de Beckman ou Bequimão (1684)."}'::jsonb),
('teoria_historia', 26, '{"t": "art", "n": "1684 — Revolta de Bequimão (ou Beckman)", "x": "Liderada pelos irmãos Manuel Beckman (também grafado Bequimão) e Tomás Beckman, senhores de engenho locais, a revolta de 1684 depôs temporariamente o governador da capitania e expulsou os jesuítas de São Luís — acusados de monopolizar a mão de obra indígena e de serem aliados dos interesses da Companhia de Comércio — em protesto contra o monopólio comercial e a falta de braços (escravizados/indígenas) para a lavoura. A revolta foi sufocada em 1685 por tropas enviadas do Pará, e Manuel Beckman foi preso e executado (enforcado) em 1685.", "s": "Dois nomes, mesmo evento: ''Revolta de Beckman'' (sobrenome original neerlandês da família) e ''Revolta de Bequimão'' (aportuguesamento) são SINÔNIMOS — não confunda com dois movimentos diferentes."}'::jsonb),
('teoria_historia', 27, '{"t": "art", "n": "7 de agosto de 1755 — Companhia Geral de Comércio do Grão-Pará e Maranhão", "x": "O Marquês de Pombal fundou, em 7 de agosto de 1755, a Companhia Geral de Comércio do Grão-Pará e Maranhão, com capital de 1.200.000 cruzados e monopólio de 20 anos sobre o tráfico negreiro e o transporte de mercadorias para a região."}'::jsonb),
('teoria_historia', 28, '{"t": "art", "n": "Intensificação do tráfico negreiro", "x": "A Companhia pombalina ampliou drasticamente a entrada de africanos escravizados: se até 1755 apenas cerca de 3 mil haviam entrado no Estado, entre 1755 e 1777 esse número saltou para cerca de 12 mil, chegando a mais de 28 mil transportados até 1778, segundo estimativas."}'::jsonb),
('teoria_historia', 29, '{"t": "art", "n": "Ciclos do algodão e do arroz", "x": "Estimulada pela Companhia de Comércio, a lavoura de algodão e de arroz se expandiu no Maranhão na segunda metade do século XVIII, tornando São Luís um dos portos mais ricos da colônia e financiando a construção dos casarões e sobrados que hoje formam o centro histórico da cidade."}'::jsonb),
('teoria_historia', 30, '{"t": "tit", "x": "PERÍODO IMPERIAL (1822-1889)"}'::jsonb),
('teoria_historia', 31, '{"t": "cap", "x": "Adesão à Independência (1823)"}'::jsonb),
('teoria_historia', 32, '{"t": "art", "n": "7 de setembro de 1822 — Independência do Brasil", "x": "Enquanto o Sudeste declarou a independência em 7 de setembro de 1822, o Maranhão, junto com outras províncias do Norte e Nordeste, manteve-se inicialmente fiel a Portugal, resistindo à ruptura com a metrópole."}'::jsonb),
('teoria_historia', 33, '{"t": "art", "n": "Causas da não adesão imediata", "x": "A elite mercantil de São Luís tinha fortes laços comerciais diretos com Portugal (sobretudo a exportação do algodão para Lisboa e Porto) e temia perder os privilégios do sistema colonial com a ruptura; havia também desconfiança em relação a uma possível dominação política do Rio de Janeiro (sede da nova Corte) sobre as demais províncias. Por isso, a administração provincial maranhense, alinhada aos interesses portugueses, resistiu à adesão mesmo depois de províncias vizinhas — como o Piauí — já terem aderido à causa da Independência.", "s": "Decore o motivo ECONÔMICO como principal: o algodão maranhense ia direto pro mercado português — aderir à Independência ameaçava essa rota comercial privilegiada."}'::jsonb),
('teoria_historia', 34, '{"t": "art", "n": "13 de março de 1823 — Batalha do Jenipapo", "x": "Tropas leais a Portugal, partindo de São Luís, marcharam para sufocar o movimento de Independência já estabelecido no Piauí e enfrentaram forças piauienses na Batalha do Jenipapo (nas proximidades de Campo Maior, no Piauí), em 13 de março de 1823. Os patriotas piauienses foram derrotados militarmente, com pesadas baixas, mas a resistência se tornou símbolo da luta pela Independência na região — a data é celebrada até hoje como marco cívico do Piauí.", "s": "Pegadinha de localização: a Batalha do Jenipapo aconteceu no PIAUÍ (não no Maranhão), mas as tropas atacantes vieram DE São Luís — por isso o episódio entra na história maranhense, como parte do esforço de resistência à Independência."}'::jsonb),
('teoria_historia', 35, '{"t": "art", "n": "Lord Cochrane", "x": "Thomas Cochrane, almirante escocês contratado por D. Pedro I para organizar a Marinha brasileira, foi enviado em 1823 no comando de uma esquadra para submeter as províncias do Norte que ainda resistiam à Independência."}'::jsonb),
('teoria_historia', 36, '{"t": "art", "n": "26 de julho de 1823 — Estratagema na Barra", "x": "Em 26 de julho de 1823, Cochrane chegou à fortaleza de Santo Antônio da Barra, que controlava o acesso ao porto de São Luís, usando a artimanha de hastear bandeira inglesa para simular embarcação aliada e evitar confronto armado."}'::jsonb),
('teoria_historia', 37, '{"t": "art", "n": "28 de julho de 1823 — Adesão do Maranhão", "x": "O documento oficial de adesão do Maranhão à Independência do Brasil foi assinado em 28 de julho de 1823, na cidade de Caxias, sem que um único tiro fosse disparado. A data é feriado estadual no Maranhão até hoje."}'::jsonb),
('teoria_historia', 38, '{"t": "cap", "x": "A Atenas Brasileira"}'::jsonb),
('teoria_historia', 39, '{"t": "art", "n": "A ''Atenas Brasileira''", "x": "No século XIX, a riqueza gerada pelo ciclo do algodão financiou uma intensa vida intelectual em São Luís, que passou a ser chamada de ''Atenas Brasileira'' pelo grande número de escritores, poetas e intelectuais que formou."}'::jsonb),
('teoria_historia', 40, '{"t": "art", "n": "Gonçalves Dias e Sousândrade", "x": "Gonçalves Dias, poeta romântico e indianista, e Joaquim de Sousândrade (nascido em 1833 na Vila de Guimarães, MA), poeta de estilo vanguardista redescoberto no século XX, foram os maiores nomes da literatura maranhense do período, ao lado de Aluísio Azevedo e Graça Aranha."}'::jsonb),
('teoria_historia', 41, '{"t": "cap", "x": "Período Regencial — A Balaiada (1838-1841)"}'::jsonb),
('teoria_historia', 42, '{"t": "art", "n": "1838-1841 — A Balaiada", "x": "A Balaiada foi uma das maiores revoltas do período regencial brasileiro, ocorrida na província do Maranhão entre 1838 e 1841, motivada por crise econômica, tensões entre o sertão pobre e o litoral dominante, e insatisfação com a administração provincial."}'::jsonb),
('teoria_historia', 43, '{"t": "art", "n": "13 de dezembro de 1838 — Início do movimento", "x": "A revolta começou em 13 de dezembro de 1838, em Vila da Manga, quando Raimundo Gomes libertou seu irmão preso, dando início ao levante que se espalhou pelo interior maranhense."}'::jsonb),
('teoria_historia', 44, '{"t": "art", "n": "Grupos envolvidos — ''bem-te-vis'' e sertanejos", "x": "O movimento uniu vaqueiros e sertanejos pobres (os chamados ''bem-te-vis'', ligados a um grupo político liberal local), além de escravizados fugidos, contra a elite conservadora que controlava a província."}'::jsonb),
('teoria_historia', 45, '{"t": "art", "n": "Cosme Bento das Chagas", "x": "Cosme Bento das Chagas, homem negro e liderança quilombola, comandou um contingente estimado em cerca de 3 mil escravizados e pobres livres, tornando-se a face mais radical e temida da Balaiada a partir de 1839."}'::jsonb),
('teoria_historia', 46, '{"t": "art", "n": "Repressão de Luís Alves de Lima e Silva", "x": "A repressão foi comandada pelo coronel Luís Alves de Lima e Silva, futuro Duque de Caxias, que assumiu o comando geral das tropas no Maranhão, Piauí e Ceará, reunindo mais de 8 mil homens armados até fevereiro de 1840."}'::jsonb),
('teoria_historia', 47, '{"t": "art", "n": "15 de janeiro de 1841 — Fim nominal da revolta", "x": "A Balaiada chegou ao fim nominal em 15 de janeiro de 1841, quando Raimundo Gomes se rendeu em Vila de Miritiba, próxima à fronteira com o Piauí."}'::jsonb),
('teoria_historia', 48, '{"t": "art", "n": "Setembro de 1842 — Execução de Cosme Bento", "x": "Cosme Bento das Chagas foi julgado e enforcado em Itapecuru-Mirim em setembro de 1842, tornando-se um dos grandes símbolos da resistência negra no Brasil imperial."}'::jsonb),
('teoria_historia', 49, '{"t": "cap", "x": "Abolição da Escravatura"}'::jsonb),
('teoria_historia', 50, '{"t": "art", "n": "Declínio da economia algodoeira", "x": "A partir da década de 1820, a concorrência do algodão dos Estados Unidos, com técnicas de produção mais avançadas, fez os preços do algodão maranhense despencarem — queda estimada em cerca de 70% no mercado internacional — iniciando um longo declínio econômico da província."}'::jsonb),
('teoria_historia', 51, '{"t": "art", "n": "13 de maio de 1888 — Lei Áurea", "x": "A abolição da escravatura, decretada pela Lei Áurea em 13 de maio de 1888, representou o ponto culminante da decadência do sistema escravista maranhense, que já vinha perdendo força havia décadas."}'::jsonb),
('teoria_historia', 52, '{"t": "art", "n": "Impactos sociais do pós-abolição", "x": "O fim da escravidão não foi acompanhado de políticas de integração social ou econômica para a população negra recém-liberta, deixando marcas de desigualdade que se estenderam por décadas na sociedade maranhense."}'::jsonb),
('teoria_historia', 53, '{"t": "tit", "x": "REPÚBLICA"}'::jsonb),
('teoria_historia', 54, '{"t": "cap", "x": "Primeira República — Oligarquias"}'::jsonb),
('teoria_historia', 55, '{"t": "art", "n": "15 de novembro de 1889 — Proclamação da República", "x": "Com a Proclamação da República em 15 de novembro de 1889, o Maranhão — assim como as demais províncias — aderiu de forma pacífica e praticamente imediata ao novo regime, sem a resistência armada que marcara a crise da Independência em 1823. A partir daí, passou a ser governado por oligarquias locais organizadas em torno do coronelismo e do controle da economia agrária e extrativista.", "s": "Contraste importante de prova: a adesão à REPÚBLICA (1889) foi pacífica; já a adesão à INDEPENDÊNCIA (1823) só veio depois de resistência armada (Jenipapo) e pressão naval (Cochrane) — não troque uma pela outra."}'::jsonb),
('teoria_historia', 56, '{"t": "art", "n": "Oligarquias da Primeira República", "x": "Durante a Primeira República (1889-1930), grupos políticos regionais controlaram o Maranhão por meio de fraudes eleitorais, clientelismo e alianças com o poder federal, um padrão que se repetiria em diferentes formas ao longo do século XX."}'::jsonb),
('teoria_historia', 57, '{"t": "cap", "x": "A Revolução de 1930 no Maranhão"}'::jsonb),
('teoria_historia', 58, '{"t": "art", "n": "Impactos locais da Revolução de 1930", "x": "A Revolução de 1930, que levou Getúlio Vargas ao poder e encerrou a Primeira República — com o fim da chamada ''política do café com leite'' e das oligarquias estaduais tradicionais alinhadas ao governo federal anterior —, teve reflexo direto no Maranhão: interventores federais, nomeados pelo novo governo central, substituíram as lideranças políticas ligadas à estrutura oligárquica da Primeira República, reorganizando as forças políticas estaduais sob a tutela do novo governo de Vargas."}'::jsonb),
('teoria_historia', 59, '{"t": "art", "n": "Ponte para a era vitorinista", "x": "É nesse contexto de reorganização política pós-1930 que Vitorino Freire inicia sua ascensão na política maranhense a partir de 1933, já com apoio direto de Getúlio Vargas — ou seja, a oligarquia vitorinista que dominaria o estado entre 1945 e 1965 nasce diretamente do novo arranjo político criado pela Revolução de 1930.", "s": "Conecte os fatos: Revolução de 1930 (nacional) → reorganização política no Maranhão → ascensão de Vitorino Freire (1933) → oligarquia vitorinista (1945-1965) — é uma cadeia causal só, não eventos soltos."}'::jsonb),
('teoria_historia', 60, '{"t": "cap", "x": "Século XX — Babaçu, Política e Infraestrutura"}'::jsonb),
('teoria_historia', 61, '{"t": "art", "n": "Economia do babaçu", "x": "No início e meados do século XX, o Maranhão se destacou como o maior produtor mundial de amêndoas de babaçu, cuja extração de óleo se tornou uma das principais atividades econômicas do estado, empregando sobretudo mulheres quebradeiras de coco."}'::jsonb),
('teoria_historia', 62, '{"t": "art", "n": "Vitorino Freire", "x": "Vitorino de Brito Freire, político nascido em Pernambuco, passou a atuar na política maranhense a partir de 1933, com apoio de Getúlio Vargas, e construiu uma máquina política de coronelismo e clientelismo sem nunca ter sido governador do estado."}'::jsonb),
('teoria_historia', 63, '{"t": "art", "n": "1945-1965 — Oligarquia vitorinista", "x": "A chamada ''oligarquia vitorinista'' dominou a política maranhense por cerca de 20 anos, entre 1945 e 1965, controlando eleições e cargos por meio de práticas clientelistas e fraudes, até se desgastar na década de 1960."}'::jsonb),
('teoria_historia', 64, '{"t": "art", "n": "1965 — Ascensão de José Sarney", "x": "Em 1965, José Sarney foi eleito governador do Maranhão, rompendo com o domínio político de Vitorino Freire e iniciando um novo ciclo de liderança política que se estenderia por décadas na vida pública maranhense."}'::jsonb),
('teoria_historia', 65, '{"t": "art", "n": "Estrada de Ferro Carajás e Porto do Itaqui", "x": "A construção da Estrada de Ferro Carajás começou em agosto de 1982 e a ferrovia, com 892 km, foi inaugurada em 28 de fevereiro de 1985, ligando as minas da Serra dos Carajás (PA) ao Porto do Itaqui, em São Luís, dentro do Programa Grande Carajás — projeto que também atraiu a instalação da fábrica de alumínio Alumar, marcando a industrialização tardia do estado."}'::jsonb),
('teoria_historia', 66, '{"t": "cap", "x": "Ditadura Militar (1964-1985)"}'::jsonb),
('teoria_historia', 67, '{"t": "art", "n": "1964 — Regime Militar", "x": "O golpe militar de 1964 reorganizou a política brasileira sob o bipartidarismo forçado pelo Ato Institucional nº 2, de 27 de outubro de 1965, que extinguiu os partidos existentes e levou lideranças maranhenses, incluindo antigos rivais, a se filiarem à Arena, o partido do governo."}'::jsonb),
('teoria_historia', 68, '{"t": "art", "n": "José Sarney no governo (1966-1970)", "x": "José Sarney foi eleito governador do Maranhão em outubro de 1965 e empossado em março de 1966, governando o estado durante o regime militar sob o projeto que chamou de ''Maranhão Novo'', voltado à modernização administrativa e educacional."}'::jsonb),
('teoria_historia', 69, '{"t": "cap", "x": "Redemocratização"}'::jsonb),
('teoria_historia', 70, '{"t": "art", "n": "Redemocratização", "x": "A partir da abertura política de 1985 e da Constituição de 1988, o Maranhão retomou eleições diretas para governador, mantendo, contudo, forte influência de grupos políticos tradicionais ligados a lideranças históricas do estado."}'::jsonb),
('teoria_historia', 71, '{"t": "art", "n": "Valorização do patrimônio histórico", "x": "Nas décadas seguintes à redemocratização, o poder público intensificou políticas de preservação do patrimônio histórico e cultural maranhense, movimento que culminou no reconhecimento internacional do centro histórico de São Luís pela UNESCO em 1997."}'::jsonb),
('teoria_historia', 72, '{"t": "tit", "x": "PATRIMÔNIO E CULTURA MARANHENSE"}'::jsonb),
('teoria_historia', 73, '{"t": "cap", "x": "Centro Histórico de São Luís — Patrimônio da UNESCO"}'::jsonb),
('teoria_historia', 74, '{"t": "art", "n": "6 de dezembro de 1997 — Patrimônio Mundial da UNESCO", "x": "O Centro Histórico de São Luís foi inscrito na lista de Patrimônio Mundial da UNESCO em 6 de dezembro de 1997, durante a 21ª sessão do Comitê do Patrimônio Mundial, realizada no Palácio Real de Nápoles, na Itália. O reconhecimento valorizou o traçado urbano preservado e o conjunto arquitetônico colonial português."}'::jsonb),
('teoria_historia', 75, '{"t": "art", "n": "1974 — Tombamento pelo IPHAN", "x": "Antes do reconhecimento internacional, o Centro Histórico de São Luís já havia sido tombado como patrimônio nacional pelo IPHAN em 1974, reconhecendo a importância de seu conjunto arquitetônico colonial."}'::jsonb),
('teoria_historia', 76, '{"t": "cap", "x": "Bumba-meu-boi"}'::jsonb),
('teoria_historia', 77, '{"t": "art", "n": "Bumba-meu-boi", "x": "O Bumba-meu-boi maranhense foi registrado como patrimônio cultural do Brasil pelo IPHAN em 2011 e, em 11 de dezembro de 2019, o Complexo Cultural do Bumba-meu-boi do Maranhão foi declarado Patrimônio Cultural Imaterial da Humanidade pela UNESCO, em reunião em Bogotá, na Colômbia."}'::jsonb),
('teoria_historia', 78, '{"t": "cap", "x": "Reggae — A Jamaica Brasileira"}'::jsonb),
('teoria_historia', 79, '{"t": "art", "n": "Cidade dos Azulejos e Jamaica Brasileira", "x": "São Luís é conhecida como a ''Cidade dos Azulejos'', por reunir cerca de 5.600 imóveis revestidos com azulejaria portuguesa dos séculos XVIII e XIX — o maior acervo de azulejos coloniais da América Latina — e também como a ''Jamaica Brasileira'', pela forte identidade reggae que teria chegado via ondas de rádio caribenhas nos anos 1970 e conta com museu próprio desde 2018."}'::jsonb),
('teoria_historia', 80, '{"t": "cap", "x": "Culinária e Tradições"}'::jsonb),
('teoria_historia', 81, '{"t": "art", "n": "Culinária maranhense", "x": "A gastronomia do Maranhão reúne influências indígenas, africanas e portuguesas, com destaque para pratos como o arroz de cuxá, preparado com a folha da vinagreira, camarão seco e farinha — símbolo da identidade cultural maranhense reforçado ao lado do Bumba-meu-boi e do reggae."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('flash_6513', 0, '{"front": "Qual a idade máxima para matrícula na PMMA, segundo o Art. 9º?", "back": "30 anos, na data-limite da inscrição (Art. 9º)."}'::jsonb),
('flash_6513', 1, '{"front": "Qual a altura mínima exigida para matrícula de candidatos do sexo masculino e feminino?", "back": "1,65m para o sexo masculino e 1,60m para o sexo feminino (Art. 9º)."}'::jsonb),
('flash_6513', 2, '{"front": "O exame toxicológico exigido na matrícula tem que natureza?", "back": "É obrigatório e eliminatório (Art. 9º, parágrafo único)."}'::jsonb),
('flash_6513', 3, '{"front": "Como se dá o ingresso no Quadro de Oficiais da PMMA?", "back": "Mediante Curso de Formação de Oficiais (Art. 10)."}'::jsonb),
('flash_6513', 4, '{"front": "Como ingressa um Subtenente com diploma de nível superior no QOA/QOE?", "back": "Por seleção, com tempo mínimo de serviço/graduação e aprovação em CHOA/CHOE (Art. 11)."}'::jsonb),
('flash_6513', 5, '{"front": "Qual a idade-limite para ingresso no QOS e em qual posto se dá a nomeação?", "back": "35 anos; nomeação como 1º Tenente (Médico, Dentista, Veterinário ou Psicólogo) (Art. 13)."}'::jsonb),
('flash_6513', 6, '{"front": "Como se preenchem as graduações de 3º Sargento e Cabo? E a de Soldado?", "back": "3º Sargento e Cabo são preenchidos por promoção; Soldado é preenchido por concurso público (Art. 15)."}'::jsonb),
('flash_6513', 7, '{"front": "Como é denominado o candidato aprovado no concurso de Soldado durante o curso de formação?", "back": "ALUNO, e não ''praça especial'' (Art. 16)."}'::jsonb),
('flash_6513', 8, '{"front": "Que certificado escolar e exames são exigidos para matrícula de Oficiais e Praças?", "back": "Certificado de 2º Grau, além de exames físico, médico e psicotécnico (Art. 9º)."}'::jsonb),
('flash_6513', 9, '{"front": "O que é hierarquia, segundo o Art. 17, §1º?", "back": "Ordenação da autoridade em níveis, por postos ou graduações e, dentro de cada posto/graduação, pela antiguidade (Art. 17, §1º)."}'::jsonb),
('flash_6513', 10, '{"front": "O que é disciplina, segundo o Art. 17, §2º?", "back": "Rigorosa observância e acatamento integral das leis, regulamentos e normas (Art. 17, §2º)."}'::jsonb),
('flash_6513', 11, '{"front": "Quem confere o posto de Oficial e por qual ato?", "back": "O Governador, por decreto, confirmado em Carta Patente (Art. 19, §1º)."}'::jsonb),
('flash_6513', 12, '{"front": "Quem confere a graduação de praça e por qual ato?", "back": "O Comandante-Geral, por ato (Art. 19, §2º)."}'::jsonb),
('flash_6513', 13, '{"front": "Quais são as únicas praças especiais previstas na lei?", "back": "Aspirante-a-Oficial e Cadete (Art. 19, §3º)."}'::jsonb),
('flash_6513', 14, '{"front": "Em qual círculo hierárquico o Aspirante-a-Oficial se enquadra?", "back": "Frequenta o círculo dos oficiais subalternos (Art. 19)."}'::jsonb),
('flash_6513', 15, '{"front": "Como se estabelece a precedência entre militares, segundo o Art. 20?", "back": "Primeiro pelo posto/graduação; em igualdade, pela antiguidade, salvo precedência funcional prevista em lei (Art. 20)."}'::jsonb),
('flash_6513', 16, '{"front": "Na declaração de Aspirante ou promoção de 3º Sgt/Cabo, o que prevalece para a antiguidade?", "back": "A ordem de classificação obtida no curso ou concurso (Art. 21, §1º)."}'::jsonb),
('flash_6513', 17, '{"front": "Entre militar da ativa e militar da reserva remunerada convocado, no mesmo posto, o que define a precedência?", "back": "O tempo de serviço no posto/graduação (Art. 21, §4º)."}'::jsonb),
('flash_6513', 18, '{"front": "O Aspirante-a-Oficial é superior a quais militares? E o Cadete?", "back": "O Aspirante-a-Oficial é superior a todas as demais praças; o Cadete é superior aos Subtenentes (Art. 22)."}'::jsonb),
('flash_6513', 19, '{"front": "Quem declara os Cadetes Aspirantes-a-Oficial?", "back": "O Comandante-Geral (Art. 24)."}'::jsonb),
('flash_6513', 20, '{"front": "Quem pode exercer um cargo policial-militar?", "back": "Somente militar em serviço ativo, sendo o cargo criado por lei (Art. 25)."}'::jsonb),
('flash_6513', 21, '{"front": "Como se dá o provimento de cargo policial-militar?", "back": "Por ato de nomeação do Governador, sendo delegável (Art. 26)."}'::jsonb),
('flash_6513', 22, '{"front": "Quem nomeia o Comandante-Geral da PMMA e entre quais oficiais?", "back": "O Governador, entre os Oficiais da ativa do último posto do Quadro de Combatentes (Art. 31)."}'::jsonb),
('flash_6513', 23, '{"front": "Quais são as duas situações possíveis no exercício do cargo, segundo o Art. 33?", "back": "Efetivo (satisfaz todos os requisitos) ou Interino (não satisfaz os requisitos) (Art. 33)."}'::jsonb),
('flash_6513', 24, '{"front": "O que constitui violação dos deveres policiais-militares?", "back": "Crime militar ou transgressão disciplinar (Art. 55)."}'::jsonb),
('flash_6513', 25, '{"front": "No concurso entre crime militar e transgressão disciplinar pela mesma conduta, qual pena se aplica?", "back": "Aplica-se somente a pena relativa ao crime (Art. 55, §2º)."}'::jsonb),
('flash_6513', 26, '{"front": "Qual órgão julga os crimes militares em 1ª instância? E em 2ª?", "back": "A Auditoria da Justiça Militar Estadual em 1ª instância; o Tribunal de Justiça em 2ª instância (Art. 58)."}'::jsonb),
('flash_6513', 27, '{"front": "Qual o prazo máximo das penas disciplinares de detenção/prisão?", "back": "30 dias (Art. 59, §1º)."}'::jsonb),
('flash_6513', 28, '{"front": "Qual conselho analisa o oficial considerado incapaz de permanecer na ativa por razões ético-disciplinares?", "back": "Conselho de Justificação, sendo o oficial automaticamente afastado das funções; o TJ julga o processo (Art. 60)."}'::jsonb),
('flash_6513', 29, '{"front": "Qual conselho analisa Aspirantes e praças com estabilidade nessa mesma situação?", "back": "Conselho de Disciplina, com o Conselho Superior de Polícia julgando em última instância (Art. 61)."}'::jsonb),
('flash_6513', 30, '{"front": "Segundo o Art. 55, §1º, quando a violação da ética é considerada mais grave?", "back": "Quanto mais elevado for o grau hierárquico do transgressor (Art. 55, §1º)."}'::jsonb),
('flash_6513', 31, '{"front": "Quanto tempo de efetivo exercício garante estabilidade à praça?", "back": "5 anos de efetivo exercício (Art. 62)."}'::jsonb),
('flash_6513', 32, '{"front": "Sob qual forma é paga a remuneração dos policiais-militares, segundo o Art. 65?", "back": "Subsídio, em parcela única, vedado acréscimo de gratificação, adicional, abono ou prêmio (Art. 65)."}'::jsonb),
('flash_6513', 33, '{"front": "Como é chamada a remuneração paga ao militar inativo?", "back": "Proventos (Art. 66)."}'::jsonb),
('flash_6513', 34, '{"front": "Cite verbas indenizatórias previstas no Art. 69.", "back": "Diárias, ajuda de custo e salário-família (entre outras: ajuda de curso, fardamento, adicional de férias, retribuição por local de difícil provimento) (Art. 69)."}'::jsonb),
('flash_6513', 35, '{"front": "A remuneração da inatividade pode ser reduzida?", "back": "Não; é irredutível e revista automaticamente junto com a da ativa, mantendo paridade (Art. 73)."}'::jsonb),
('flash_6513', 36, '{"front": "Qual o prazo de prescrição para recurso relativo a Quadro de Acesso para promoção?", "back": "30 dias (Art. 63, §1º)."}'::jsonb),
('flash_6513', 37, '{"front": "Qual o prazo de prescrição para os demais recursos administrativos?", "back": "120 dias corridos (Art. 63, §1º)."}'::jsonb),
('flash_6513', 38, '{"front": "O militar em atividade pode ser filiado a partido político?", "back": "Não (Art. 64, §2º)."}'::jsonb),
('flash_6513', 39, '{"front": "É permitida a sindicalização e a greve aos policiais-militares?", "back": "Não, ambas são proibidas (Art. 64, §3º)."}'::jsonb),
('flash_6513', 40, '{"front": "Quais são os critérios de promoção previstos no Art. 78?", "back": "Antiguidade, merecimento, tempo de serviço, bravura e post mortem (e, para praças, completar requisitos para transferência) (Art. 78)."}'::jsonb),
('flash_6513', 41, '{"front": "Em quais meses do ano ocorrem as promoções?", "back": "Agosto e dezembro, duas vezes por ano (Art. 79-A)."}'::jsonb),
('flash_6513', 42, '{"front": "Há promoção por ocasião da transferência para reserva ou reforma?", "back": "Não (Art. 79)."}'::jsonb),
('flash_6513', 43, '{"front": "O que ocorre com uma promoção realizada em desacordo com a lei?", "back": "É nula de pleno direito (Art. 78, §3º)."}'::jsonb),
('flash_6513', 44, '{"front": "Como é calculada a pensão em caso de promoção post mortem?", "back": "Com base no posto/graduação alcançado, a contar da data da morte (Art. 78, §5º)."}'::jsonb),
('flash_6513', 45, '{"front": "Quantos dias de férias o militar tem por ano e a partir de quando?", "back": "30 dias de férias por ano, somente após 12 meses de exercício (Art. 80)."}'::jsonb),
('flash_6513', 46, '{"front": "Qual o adicional pago sobre a remuneração de férias?", "back": "Adicional de 1/3 (Art. 80, §5º)."}'::jsonb),
('flash_6513', 47, '{"front": "Até quanto tempo as férias podem ser acumuladas?", "back": "Até o máximo de 2 anos, por imperiosa necessidade do serviço (Art. 82)."}'::jsonb),
('flash_6513', 48, '{"front": "Quantos dias de afastamento são concedidos por núpcias e por luto?", "back": "8 dias para núpcias e 8 dias para luto (Art. 84)."}'::jsonb),
('flash_6513', 49, '{"front": "Até que idade um filho é considerado dependente para o salário-família?", "back": "Até 21 anos, ou 24 anos se estudante, ou qualquer idade se inválido (Art. 86-90)."}'::jsonb),
('flash_6513', 50, '{"front": "Qual a duração da licença-prêmio e a cada quanto tempo de serviço é concedida?", "back": "3 meses, concedida por quinquênio de serviço, gozada de uma só vez (Art. 93)."}'::jsonb),
('flash_6513', 51, '{"front": "A licença-prêmio anula o direito a outras licenças?", "back": "Não, exceto em relação à licença de saúde de pessoa da família (Art. 93, §2º)."}'::jsonb),
('flash_6513', 52, '{"front": "Qual o prazo máximo da licença para tratamento de saúde de pessoa da família?", "back": "Não excede 6 meses (Art. 94)."}'::jsonb),
('flash_6513', 53, '{"front": "Como é a remuneração durante a licença de saúde de pessoa da família?", "back": "Vencimentos integrais até 3 meses; depois, desconto de 1/3 (Art. 94)."}'::jsonb),
('flash_6513', 54, '{"front": "Quais os requisitos para a licença por interesse particular?", "back": "Mais de 10 anos de serviço; sempre com prejuízo de remuneração e tempo de serviço; concedida até 2 anos (Art. 95)."}'::jsonb),
('flash_6513', 55, '{"front": "Quem julga a incapacidade temporária para fins de licença-saúde própria?", "back": "A Junta Militar de Saúde (Art. 96)."}'::jsonb),
('flash_6513', 56, '{"front": "Qual a duração da licença-maternidade?", "back": "180 dias, sem prejuízo de remuneração; mesmo prazo em caso de adoção ou guarda judicial (Art. 97)."}'::jsonb),
('flash_6513', 57, '{"front": "Quais licenças podem ser interrompidas por punição disciplinar, mobilização ou situações semelhantes?", "back": "Licença-prêmio, licença-paternidade e licença-interesse particular (Art. 98)."}'::jsonb),
('flash_6513', 58, '{"front": "Qual a duração da licença-paternidade e sua possível prorrogação?", "back": "5 dias consecutivos, prorrogável por 15 dias mediante comprovação de programa de paternidade responsável (Art. 98, §3º)."}'::jsonb),
('flash_6513', 59, '{"front": "Durante a prorrogação da licença-paternidade, o militar pode exercer outra atividade remunerada?", "back": "Não (Art. 98, §3º)."}'::jsonb),
('flash_6513', 60, '{"front": "O que caracteriza a licença, de forma geral, segundo o Art. 92?", "back": "Afastamento total temporário do serviço (Art. 92)."}'::jsonb),
('flash_6513', 61, '{"front": "Onde o militar deve cumprir pena de prisão, segundo o Art. 99?", "back": "Somente em unidade cujo comandante tenha precedência hierárquica sobre o apenado (Art. 99)."}'::jsonb),
('flash_6513', 62, '{"front": "Em que situação a autoridade policial civil pode prender um policial-militar?", "back": "Somente em flagrante delito (Art. 100)."}'::jsonb),
('flash_6513', 63, '{"front": "Após prisão em flagrante por autoridade civil, o que ocorre com o militar detido?", "back": "Fica detido na delegacia só até a lavratura do flagrante, sendo depois apresentado à autoridade militar (Art. 100)."}'::jsonb),
('flash_6513', 64, '{"front": "Os militares da ativa são obrigados a servir como jurados ou na Justiça Eleitoral?", "back": "Não; são dispensados do serviço de jurados e da Justiça Eleitoral (Art. 101)."}'::jsonb),
('flash_6513', 65, '{"front": "O uso indevido de uniformes e distintivos da PM constitui o quê?", "back": "Crime (Art. 102-103)."}'::jsonb),
('flash_6513', 66, '{"front": "O que é agregação, segundo o Art. 106?", "back": "Situação em que o militar da ativa deixa de ocupar vaga na escala hierárquica, permanecendo sem número (Art. 106)."}'::jsonb),
('flash_6513', 67, '{"front": "Após quanto tempo de licença-saúde própria o militar é agregado?", "back": "Mais de 1 ano de tratamento (Art. 106, §1º)."}'::jsonb),
('flash_6513', 68, '{"front": "Após quanto tempo de licença de interesse particular o militar é agregado?", "back": "Mais de 6 meses (Art. 106, §1º)."}'::jsonb),
('flash_6513', 69, '{"front": "O militar agregado pode ser promovido durante a agregação?", "back": "Não (Art. 106, §8º)."}'::jsonb),
('flash_6513', 70, '{"front": "Quem determina a agregação de um militar?", "back": "O Governador ou autoridade delegada (Art. 107)."}'::jsonb),
('flash_6513', 71, '{"front": "O que é reversão?", "back": "Retorno do militar agregado ao quadro quando cessa o motivo da agregação (Art. 108-109)."}'::jsonb),
('flash_6513', 72, '{"front": "Após quanto tempo de agregação a reversão passa a ser automática?", "back": "Após 2 anos de agregação (Art. 108-109)."}'::jsonb),
('flash_6513', 73, '{"front": "O que caracteriza a situação de ''excedente''?", "back": "Situação transitória de quem reverte quando o quadro está com efetivo completo; considerado em efetivo serviço para todos os efeitos (Art. 110)."}'::jsonb),
('flash_6513', 74, '{"front": "Após quanto tempo sem comparecer sem licença o militar é considerado ''ausente''? E ''desaparecido''?", "back": "Ausente após 24 horas; desaparecido após mais de 8 dias sem indícios de deserção (Art. 111 e 113-114)."}'::jsonb),
('flash_6513', 75, '{"front": "Quais os requisitos para transferência para reserva remunerada a pedido, com proventos integrais?", "back": "35 anos ou mais de serviço, dos quais ao menos 30 anos de atividade militar (Art. 118-120)."}'::jsonb),
('flash_6513', 76, '{"front": "Qual a idade-limite para transferência compulsória para a reserva do Coronel? E dos demais oficiais/praças?", "back": "Coronel, 67 anos; demais oficiais e praças, 65 anos (Art. 118-120)."}'::jsonb),
('flash_6513', 77, '{"front": "Por quanto tempo, no máximo, pode ser feita a convocação da reserva para o serviço ativo?", "back": "Máximo de 6 meses, com inspeção de saúde prévia (Art. 122, §2º)."}'::jsonb),
('flash_6513', 78, '{"front": "O militar da reserva convocado concorre a promoção?", "back": "Não (Art. 122, §1º)."}'::jsonb),
('flash_6513', 79, '{"front": "Qual a idade-limite na reserva para reforma ex-officio do Coronel/Tenente-Coronel/Major? E dos demais?", "back": "72 anos para Coronel, Tenente-Coronel e Major; 70 anos para os demais oficiais e praças (Art. 124-131)."}'::jsonb),
('flash_6513', 80, '{"front": "Como é a remuneração da reforma por incapacidade relacionada ao serviço?", "back": "Integral (Art. 128)."}'::jsonb),
('flash_6513', 81, '{"front": "Como é a remuneração da reforma por incapacidade sem relação com o serviço?", "back": "Proporcional ao tempo de serviço (Art. 130)."}'::jsonb),
('flash_6513', 82, '{"front": "A demissão a pedido do oficial gera indenização em qual hipótese?", "back": "Gera indenização se tiver menos de 3 anos de oficialato; não gera se tiver mais de 3 anos (Art. 133-134)."}'::jsonb),
('flash_6513', 83, '{"front": "Quem pode ser licenciado, segundo o Art. 139?", "back": "Somente praças, a pedido ou ex-officio (Art. 139)."}'::jsonb),
('flash_6513', 84, '{"front": "Após quanto tempo de agregação se processa a deserção de oficial ou praça com estabilidade?", "back": "Após 1 ano de agregação, se não houver captura ou apresentação antes (Art. 144, §1º)."}'::jsonb),
('flash_6513', 85, '{"front": "O que ocorre com a praça sem estabilidade declarada desertora?", "back": "É automaticamente excluída (Art. 144, §2º)."}'::jsonb),
('flash_6513', 86, '{"front": "Qual divisor é usado para o cálculo dos anos de efetivo serviço?", "back": "365 (Art. 150, §3º)."}'::jsonb),
('flash_6513', 87, '{"front": "Qual o prazo máximo de dispensa do serviço concedida como recompensa?", "back": "8 dias (Art. 158-159)."}'::jsonb),
('flash_6513', 88, '{"front": "Em caso de matéria não regulada por esta lei, quais normas se aplicam?", "back": "As leis e regulamentos do Exército Brasileiro (Art. 166)."}'::jsonb),
('flash_6513', 89, '{"front": "A quem mais, além dos policiais-militares da PMMA, esta lei se aplica?", "back": "Aos servidores militares do Corpo de Bombeiros Militar do Maranhão - CBMMA (Art. 167)."}'::jsonb);
insert into content_items (deck_key, order_index, data) values
('flash_historia', 0, '{"title": "Pré-história maranhense", "text": "Ocupação indígena da ilha de São Luís e do continente maranhense remonta a milhares de anos antes da chegada dos europeus, comprovada por sítios arqueológicos."}'::jsonb),
('flash_historia', 1, '{"title": "Tupinambás", "text": "Principal povo indígena do litoral maranhense no século XVII, os Tupinambás dominavam a região onde depois foi fundada São Luís."}'::jsonb),
('flash_historia', 2, '{"title": "Março de 1612", "text": "Expedição francesa parte do porto de Cancale (Bretanha) rumo ao Maranhão, sob comando de Daniel de La Touche, Senhor de La Ravardière."}'::jsonb),
('flash_historia', 3, '{"title": "26 de julho de 1612", "text": "A esquadra francesa de La Ravardière chega à baía do litoral maranhense, dando início ao projeto da França Equinocial."}'::jsonb),
('flash_historia', 4, '{"title": "8 de setembro de 1612", "text": "Fundação oficial de São Luís pelos franceses, com construção do Forte Saint-Louis — única capital de estado brasileiro fundada por franceses."}'::jsonb),
('flash_historia', 5, '{"title": "La Ravardière", "text": "Daniel de La Touche, Senhor de La Ravardière, comandou a expedição de cerca de 500 homens que fundou São Luís em 1612."}'::jsonb),
('flash_historia', 6, '{"title": "França Equinocial", "text": "Nome do projeto colonial francês, apoiado pela coroa francesa, para ocupar o território tropical maranhense ainda não dominado por Portugal."}'::jsonb),
('flash_historia', 7, '{"title": "19 de novembro de 1614", "text": "Batalha de Guaxenduba: vitória luso-indígena, comandada por Jerônimo de Albuquerque, decisiva contra franceses e tupinambás aliados."}'::jsonb),
('flash_historia', 8, '{"title": "Jerônimo de Albuquerque", "text": "Militar luso-brasileiro que comandou as forças que derrotaram os franceses na Batalha de Guaxenduba, em 1614."}'::jsonb),
('flash_historia', 9, '{"title": "Alexandre de Moura", "text": "Comandante que, com reforços de Pernambuco, cercou o Forte de São Luís e forçou a rendição francesa em 1615."}'::jsonb),
('flash_historia', 10, '{"title": "1615", "text": "Ano da expulsão definitiva dos franceses do Maranhão, encerrando o projeto da França Equinocial."}'::jsonb),
('flash_historia', 11, '{"title": "Consequência da expulsão", "text": "A vitória luso-espanhola sobre os franceses garantiu que a região amazônica permanecesse sob domínio português."}'::jsonb),
('flash_historia', 12, '{"title": "25 de novembro de 1641", "text": "Esquadra holandesa com 19 navios e cerca de 2 mil soldados invade a Ilha de São Luís."}'::jsonb),
('flash_historia', 13, '{"title": "Contexto da invasão holandesa", "text": "A invasão do Maranhão seguiu as ocupações holandesas anteriores na Bahia (1624-1625) e em Pernambuco (a partir de 1630)."}'::jsonb),
('flash_historia', 14, '{"title": "21 de novembro de 1642", "text": "Tropas lusas de Muniz Barreiros e Teixeira de Melo derrotam coluna holandesa comandada por Sandalim."}'::jsonb),
('flash_historia', 15, '{"title": "1644", "text": "Ano da expulsão definitiva dos holandeses do Maranhão, após três anos de domínio e conflito."}'::jsonb),
('flash_historia', 16, '{"title": "13 de junho de 1621", "text": "Carta régia cria o Estado do Maranhão, separando-o administrativamente do Estado do Brasil."}'::jsonb),
('flash_historia', 17, '{"title": "1626", "text": "Instalação efetiva do Estado do Maranhão, com posse do primeiro governador, Francisco Coelho de Carvalho."}'::jsonb),
('flash_historia', 18, '{"title": "Subordinação direta a Lisboa", "text": "O Estado do Maranhão respondia diretamente à coroa portuguesa e ao Conselho Ultramarino, sem vínculo com o governo-geral do Brasil."}'::jsonb),
('flash_historia', 19, '{"title": "Estado do Grão-Pará e Maranhão", "text": "Denominação usada entre 1751 e 1772, após as fases de Estado do Maranhão (1621-1654) e Estado do Maranhão e Grão-Pará (1654-1751)."}'::jsonb),
('flash_historia', 20, '{"title": "1682", "text": "Criação da primeira Companhia Geral de Comércio do Maranhão, sob D. Pedro II, extinta em 1685 após a Revolta de Beckman."}'::jsonb),
('flash_historia', 21, '{"title": "1684", "text": "Revolta de Beckman: insurreição de senhores de engenho maranhenses contra o monopólio da primeira Companhia de Comércio."}'::jsonb),
('flash_historia', 22, '{"title": "7 de agosto de 1755", "text": "Marquês de Pombal funda a Companhia Geral de Comércio do Grão-Pará e Maranhão, com monopólio de 20 anos sobre o tráfico negreiro."}'::jsonb),
('flash_historia', 23, '{"title": "Tráfico negreiro pombalino", "text": "Entre 1755 e 1778, a Companhia pombalina transportou mais de 28 mil africanos escravizados para o Grão-Pará e Maranhão."}'::jsonb),
('flash_historia', 24, '{"title": "Ciclo do algodão e do arroz", "text": "Na segunda metade do século XVIII, algodão e arroz tornaram-se as bases da riqueza de São Luís, financiando seus casarões coloniais."}'::jsonb),
('flash_historia', 25, '{"title": "Apogeu econômico de São Luís", "text": "O século XVIII marcou o auge econômico do Maranhão colonial, sustentado pela exportação de algodão e pelo trabalho escravizado."}'::jsonb),
('flash_historia', 26, '{"title": "7 de setembro de 1822", "text": "Independência do Brasil proclamada no Sudeste; o Maranhão inicialmente permaneceu fiel a Portugal."}'::jsonb),
('flash_historia', 27, '{"title": "Lord Cochrane", "text": "Thomas Cochrane, almirante escocês contratado por D. Pedro I, foi enviado em 1823 para submeter as províncias do Norte à Independência."}'::jsonb),
('flash_historia', 28, '{"title": "26 de julho de 1823", "text": "Cochrane chega à fortaleza de Santo Antônio da Barra, em São Luís, hasteando bandeira inglesa como estratagema para evitar combate."}'::jsonb),
('flash_historia', 29, '{"title": "28 de julho de 1823", "text": "Adesão oficial do Maranhão à Independência do Brasil, assinada em Caxias — hoje feriado estadual."}'::jsonb),
('flash_historia', 30, '{"title": "Atenas Brasileira", "text": "Apelido dado a São Luís no século XIX pela intensa produção literária financiada pela riqueza do ciclo do algodão."}'::jsonb),
('flash_historia', 31, '{"title": "Gonçalves Dias e Sousândrade", "text": "Maiores nomes da literatura maranhense do século XIX: Gonçalves Dias (romantismo indianista) e Sousândrade (poesia vanguardista)."}'::jsonb),
('flash_historia', 32, '{"title": "1838-1841", "text": "Período da Balaiada, uma das maiores revoltas populares do período regencial brasileiro, na província do Maranhão."}'::jsonb),
('flash_historia', 33, '{"title": "13 de dezembro de 1838", "text": "Início da Balaiada, quando Raimundo Gomes liberta seu irmão preso em Vila da Manga."}'::jsonb),
('flash_historia', 34, '{"title": "''Bem-te-vis''", "text": "Nome dado aos vaqueiros e sertanejos pobres aliados ao grupo político liberal que apoiou a revolta da Balaiada."}'::jsonb),
('flash_historia', 35, '{"title": "Cosme Bento das Chagas", "text": "Líder negro quilombola que comandou cerca de 3 mil escravizados e pobres livres na fase mais radical da Balaiada, a partir de 1839."}'::jsonb),
('flash_historia', 36, '{"title": "Duque de Caxias na Balaiada", "text": "Luís Alves de Lima e Silva, futuro Duque de Caxias, comandou a repressão à Balaiada com mais de 8 mil homens armados em fevereiro de 1840."}'::jsonb),
('flash_historia', 37, '{"title": "15 de janeiro de 1841", "text": "Rendição de Raimundo Gomes em Vila de Miritiba, marco do fim nominal da Balaiada."}'::jsonb),
('flash_historia', 38, '{"title": "Setembro de 1842", "text": "Cosme Bento das Chagas é julgado e enforcado em Itapecuru-Mirim, tornando-se símbolo da resistência negra no Império."}'::jsonb),
('flash_historia', 39, '{"title": "Declínio do algodão maranhense", "text": "A partir da década de 1820, a concorrência do algodão dos EUA fez os preços caírem cerca de 70%, iniciando o declínio econômico maranhense."}'::jsonb),
('flash_historia', 40, '{"title": "13 de maio de 1888", "text": "Lei Áurea abole a escravidão no Brasil, culminando a decadência do sistema escravista no Maranhão."}'::jsonb),
('flash_historia', 41, '{"title": "Pós-abolição maranhense", "text": "A ausência de políticas de integração após 1888 deixou marcas profundas de desigualdade social entre a população negra maranhense."}'::jsonb),
('flash_historia', 42, '{"title": "15 de novembro de 1889", "text": "Proclamação da República; o Maranhão passa a ser controlado por oligarquias locais ligadas ao coronelismo."}'::jsonb),
('flash_historia', 43, '{"title": "Primeira República no Maranhão", "text": "Entre 1889 e 1930, grupos políticos regionais controlaram o Maranhão por meio de clientelismo e fraudes eleitorais."}'::jsonb),
('flash_historia', 44, '{"title": "Economia do babaçu", "text": "No século XX, o Maranhão se tornou o maior produtor mundial de amêndoas de babaçu, base da economia extrativista do estado."}'::jsonb),
('flash_historia', 45, '{"title": "Vitorino Freire", "text": "Político pernambucano que, a partir de 1933 (com apoio de Getúlio Vargas), passou a controlar a política maranhense sem nunca ser governador."}'::jsonb),
('flash_historia', 46, '{"title": "1945-1965", "text": "Duração da ''oligarquia vitorinista'', que dominou a política maranhense por 20 anos através de clientelismo e coronelismo."}'::jsonb),
('flash_historia', 47, '{"title": "1965 — Fim do vitorinismo", "text": "José Sarney é eleito governador do Maranhão, rompendo o domínio político de Vitorino Freire."}'::jsonb),
